abs_0_00000800:
	move.l #EntrypointIrq,m68k_vector_privilege_violation.l
	move #$2700,sr
    ; Set supervisor A7 to B3CE after the SR/privilege entry. This is the initial stack top, not a proved allocation extent, high-water mark or guarantee after later nonlocal stack restores.
EntrypointIrq:
	movea.l #initialSupervisorStackTop,a7
	jsr BumpSounds80.l
	clr.w flagUpdateAudioChannels.l
	move.w #$2,gEscapePodState.l
    ; Initialize the LONG draw-bank byte offset to zero. The name describes address use; aliases, loaded callbacks and interrupted lifetimes do not establish a global two-value domain.
	move.l #$0,gDrawBankByteOffset.l
	move.w #$FFFF,counterIrq1000s.l
	lea.l BasePlaneBuffer.l,a0
	lea.l absolute_slot_00078000.l,a1
    ; (8000/2)-1
	move.w #$F9F,d7
abs_0_0000084A:
	move.w (a0)+,(a1)
	move.w (a0)+,$2000(a1)
	move.w (a0)+,$4000(a1)
	move.w (a0)+,$6000(a1)
	addq.w #2,a1
	dbf.w d7,abs_0_0000084A
	lea.l BasePlaneBuffer.l,a1
	lea.l absolute_slot_00078000.l,a0
    ; (8000/2)-1
	move.w #$F9F,d0
abs_0_0000086E:
	move.w (a0),(a1)
