	dbf.w d0,abs_0_0000086E
	jsr SetupIrqsCopperlist.l
	jsr WaitIrqAndPresentDrawBuffer.l
	jsr InitializePolygonSpanLookup.l
	lea.l tableColours1.l,a0
	lea.l _custom+color.l,a1
	moveq.l #15,d7
abs_0_000008AA:
	move.w (a0)+,(a1)+
	dbf.w d7,abs_0_000008AA
	lea.l tableColours1.l,a0
	moveq.l #15,d7
