	eori.l #32768,gDrawBankByteOffset.l
	jsr ClearViewRectangleFourPlanes.l
	eori.l #32768,gDrawBankByteOffset.l
	lea.l textEnglishKeyboard(pc),a0
	jsr DisplayText1.l
	lea.l textFrenchKeyboard(pc),a0
	jsr DisplayText1.l
	lea.l textGermanKeyboard(pc),a0
	jsr DisplayText1.l
abs_0_00000968:
