	beq.b abs_0_00000974
	tst.w $0004(a0)
	bne.b abs_0_000009AC
	st.b flagEnglishKeyboard.l
	eori.l #32768,gDrawBankByteOffset.l
	lea.l BasePlaneBuffer.l,a0
    ; 49 * 40
	lea.l $07A8(a0),a0
	bsr.w DrawSelectedKeyboardMarker
	moveq.l #0,d0
	jsr abs_0_00010CD6.l
	bra.w MainFlightFrameLoop
abs_0_000009AC:
	tst.w $0006(a0)
	bne.b abs_0_000009DC
	st.b flagFrenchKeyboard.l
	eori.l #32768,gDrawBankByteOffset.l
	lea.l BasePlaneBuffer.l,a0
    ; Offset of '2 French' (+10*40)
