	bsr.w UpdateAndDrawHyperspaceParticles
	st.b gIrqWaitPending.l
.wait_exit:
	tst.w gIrqWaitPending.l
	bne.b .wait_exit
	move.w gRoundPrimitiveScaleSlot.l,d0
