InitializeHyperspaceParticles:
	moveq.l #100,d5
.warm_random:
	jsr RandomWordMaybe.l
	dbf.w d5,.warm_random
	lea.l hyperspaceParticleRecords(pc),a0
	moveq.l #99,d7
.next_particle:
	jsr RandomWordMaybe.l
	andi.w #511,d0
	cmp.w #$126,d0
	blt.b .check_x_min
	andi.w #255,d0
.check_x_min:
	cmp.w #$10,d0
	bgt.b .store_x
	addi.w #128,d0
.store_x:
	move.w d0,(a0)	; operand 2: HyperspaceParticleRecord_x at (a0)
	jsr RandomWordMaybe.l
	andi.w #127,d0
	cmp.w #$10,d0
	bgt.b .choose_y_step
	addi.w #34,d0
.choose_y_step:
	cmp.w #$40,d0
	ble.b .negative_y_step
	move.w #$28,HyperspaceParticleRecord_rowByteStep(a0)
	bra.b .seed_motion
.negative_y_step:
	move.w #$FFD8,HyperspaceParticleRecord_rowByteStep(a0)
.seed_motion:
	move.w d0,d2
	mulu.w #$28,d0
	movea.l d0,a1
	move.l a1,HyperspaceParticleRecord_relativeRowOffset(a0)
	move.w #$1,HyperspaceParticleRecord_xStep(a0)
	move.w #$A0,d0
	sub.w (a0),d0	; operand 1: HyperspaceParticleRecord_x at (a0)
	bpl.b .choose_x_step
	neg.w d0
	neg.w HyperspaceParticleRecord_xStep(a0)
.choose_x_step:
	neg.w HyperspaceParticleRecord_xStep(a0)
	move.w #$40,d1
	sub.w d2,d1
	bpl.b .seed_delays
	neg.w d1
.seed_delays:
	cmp.w d0,d1
	bge.b .x_major
	move.w #$1,HyperspaceParticleRecord_xTimer(a0)
	move.w #$1,HyperspaceParticleRecord_xReload(a0)
	divu.w d1,d0
	move.w d0,HyperspaceParticleRecord_rowTimer(a0)
	move.w d0,HyperspaceParticleRecord_rowReload(a0)
	bra.b .choose_speed
.x_major:
	move.w #$1,HyperspaceParticleRecord_rowTimer(a0)
	move.w #$1,HyperspaceParticleRecord_rowReload(a0)
	divu.w d0,d1
	move.w d1,HyperspaceParticleRecord_xTimer(a0)
	move.w d1,HyperspaceParticleRecord_xReload(a0)
.choose_speed:
	jsr RandomWordMaybe.l
	andi.w #1,d0
	beq.b .advance
	asl HyperspaceParticleRecord_xStep(a0)
	asl HyperspaceParticleRecord_rowByteStep(a0)
.advance:
	lea.l $0012(a0),a0
	dbf.w d7,.next_particle
	rts
    ; Disable particle respawn, repeatedly draw while any point remains visible, then reinitialize and clear drain mode. Static loop behavior; runtime termination is not observed.
DrainAndResetHyperspaceParticles:
	jsr WaitIrqAndPresentDrawBuffer.l
	st.b gHyperspaceParticleDrainMode.l
	jsr ClearViewRectangleFourPlanes.l
	jsr UpdateAndDrawHyperspaceParticles.l
	tst.w d6
	bne.b DrainAndResetHyperspaceParticles
	bsr.w InitializeHyperspaceParticles
	clr.w gHyperspaceParticleDrainMode.l
	rts
