    ; For each slot, write low8(153-offset) to only the first byte of its separate sprite data, then install that data address. Initial POS low byte and CTL bytes are untouched here.
UpdateSprite6And7:
	moveq.l #93,d0
	sub.w sprite7Offset.l,d0
	addi.w #60,d0
    ; Write the high BYTE of slot 7 source positionWord: low8(153-offset). With offset 0..93, the first segment has 2..95 rows; subsequent in-asset F000/F000 pairs have equal start/stop values.
	move.b d0,dataSprite7_1.l
    ; Stage this distinct source address in slot 7 software pointer $10ABA. The recognized IRQ transfer at $10A22 copies it to SPR7PTH/PTL; actual DMA fetch ordering is not observed.
	move.l #dataSprite7_1,pSPR7PTH.l
	moveq.l #93,d0
	sub.w sprite6Offset.l,d0
	addi.w #60,d0
    ; Slot 6 updates its distinct source positionWord high BYTE in the same way. The low position BYTE, controlWord, 100 uniform data pairs and final zero pair are untouched by this helper.
	move.b d0,dataSprite6_1.l
    ; Stage slot 6 source in software pointer $10AB6. The recognized IRQ transfer at $10A18 copies it to SPR6PTH/PTL. Equal body bytes do not make the two writable headers aliases.
	move.l #dataSprite6_1,pSPR6PTH.l
	rts
dataSprite7_1:
	INCBIN "assets/dataSprite7_1.bin"
; opaque_data
dataSprite6_1:
	INCBIN "assets/dataSprite6_1.bin"
; opaque_data
    ; y*8
DrawMaskedPlanePixel:
	asl.w #3,d1
	move.w d1,d2
    ; (y*8)*2
	add.w d1,d1
    ; (y*8)*4
	add.w d1,d1
    ; (y*8)*5: y_offset = y*40
	add.w d1,d2
	lea.l BasePlaneBuffer.l,a0
	adda.l gDrawBankByteOffset.l,a0
    ; Y offset in screen buffer
	adda.w d2,a0
	move.w d0,d1
    ; x/8
	asr.w #3,d1
    ; Y and X offset in screen buffer.
	adda.w d1,a0
	not.w d0
    ; Convert x position in current byte to bit offset.
	andi.w #7,d0
	bclr.b d0,(a0)
	btst.b #0,bitsPlanePixelMask.l
	beq.b .plane2
	bset.b d0,(a0)
.plane2:
	bclr.b d0,$2000(a0)
	btst.b #1,bitsPlanePixelMask.l
	beq.b .plane3
	bset.b d0,$2000(a0)
.plane3:
	bclr.b d0,$4000(a0)
	btst.b #2,bitsPlanePixelMask.l
	beq.b .plane4
	bset.b d0,$4000(a0)
.plane4:
	bclr.b d0,$6000(a0)
	btst.b #3,bitsPlanePixelMask.l
	beq.b .done
	bset.b d0,$6000(a0)
.done:
	rts
	dc.b $4E,$75
