	bmi.w RoundPrimitiveDone
	beq.w RoundPrimitiveDone
	move.w (a5),d1
	ext.l d1
	lsl.l #8,d1
	divs.w d3,d1
	addi.w #160,d1
	move.w d1,(a5)
	move.w $0002(a5),d2
	ext.l d2
	lsl.l #8,d2
	divs.w d3,d2
	moveq.l #64,d3
	sub.w d2,d3
	move.w d3,$0002(a5)
	move.w $0004(a5),d3
	move.l $0016(a5),d2
	divs.w d3,d2
	move.w d2,$0016(a5)
	cmp.w #$64,d2
	ble.b .clip_projected_bounds
	move.w #$64,$0016(a5)
.clip_projected_bounds:
