	sub.w $0016(a5),d0
	cmp.w #$127,d0
	bge.w RoundPrimitiveDone
	move.w $0002(a5),d0
	sub.w $0016(a5),d0
	cmp.w #$80,d0
	bge.w RoundPrimitiveDone
	move.w $0002(a5),d0
	add.w $0016(a5),d0
	cmp.w #$F,d0
	ble.w RoundPrimitiveDone
    ; Set state and mask roots before either size path. Small sizes select row profiles; the large loop uses both four-WORD patterns. Screen-space and projected input contracts remain distinct.
DrawRoundPrimitive:
	lea.l gRoundPrimitiveX(pc),a5
	lea.l spanSuffixMasks(pc),a6
	lea.l spanPrefixMasks(pc),a4
	moveq.l #0,d7
	moveq.l #0,d6
	move.w $0016(a5),d5
	cmp.w #$9,d5
