.next_ring_row:
	add.w d6,d7
	addq.w #1,d6
	move.w d5,d0
	asr.w #1,d0
	move.w d0,gRoundHalfSpanScratch.l
	move.w (a5),d0
	move.w $0002(a5),d2
	addq.w #2,d2
	move.w d0,d1
	sub.w gRoundHalfSpanScratch(pc),d0
	sub.w d6,d2
	sub.w d5,d1
	move.w d0,-(a7)
	move.w d2,-(a7)
	bsr.w DrawPatternSpanA
	move.w (a7)+,d2
	move.w (a7)+,d0
	move.w (a5),d1
	add.w d5,d1
	bsr.w DrawPatternSpanB
	move.w d5,d0
	lsr.w #1,d0
	move.w d0,gRoundHalfSpanScratch.l
	move.w (a5),d0
	move.w $0002(a5),d2
	subq.w #2,d2
	move.w d0,d1
	sub.w gRoundHalfSpanScratch(pc),d0
	add.w d6,d2
	sub.w d5,d1
	move.w d0,-(a7)
	move.w d2,-(a7)
	bsr.w DrawPatternSpanA
	move.w (a7)+,d2
	move.w (a7)+,d0
	move.w (a5),d1
	add.w d5,d1
	bsr.w DrawPatternSpanB
	move.w d6,d0
	asr.w #1,d0
	move.w d0,gRoundHalfSpanScratch.l
	move.w (a5),d0
	move.w $0002(a5),d2
	addq.w #2,d2
	move.w d0,d1
	sub.w gRoundHalfSpanScratch(pc),d0
	sub.w d5,d2
	sub.w d6,d1
	move.w d0,-(a7)
	move.w d2,-(a7)
