	move.w (a7)+,d2
	move.w (a7)+,d0
	move.w (a5),d1
	add.w d6,d1
	bsr.w DrawPatternSpanB
	move.w d6,d0
	lsr.w #1,d0
	move.w d0,gRoundHalfSpanScratch.l
