RoundPrimitiveDone:
	rts
    ; Span A orders endpoints and clips Y to 16..127 and X to 25..295 before computing byte offsets. Four WORD planes use strides 2000/4000/6000; current draw-bank provenance remains separate.
DrawPatternSpanA:
	cmp.w #$10,d2
	blt.w PatternSpanDone
	cmp.w #$80,d2
	bge.w PatternSpanDone
	cmp.w d1,d0
	blt.b .clip_left
	exg d0,d1
.clip_left:
	cmp.w #$19,d1
	ble.w PatternSpanDone
	cmp.w #$19,d0
	bge.b .clip_right
	moveq.l #25,d0
.clip_right:
	cmp.w #$127,d0
	bge.w PatternSpanDone
	cmp.w #$127,d1
	ble.b .emit_span
	move.w #$127,d1
.emit_span:
	lea.l BasePlaneBuffer.l,a0
	adda.l gDrawBankByteOffset.l,a0
	asl.w #3,d2
	move.w d2,d3
	asl.w #2,d2
	add.w d3,d2
	adda.w d2,a0
	movea.l a0,a1
	move.w d0,d2
	lsr.w #4,d0
	add.w d0,d0
	adda.w d0,a0
	move.w d1,d4
	lsr.w #4,d1
	add.w d1,d1
	adda.w d1,a1
	andi.w #15,d2
	andi.w #15,d4
	add.w d2,d2
	add.w d4,d4
	cmpa.l a0,a1
