.first_word:
	move.w $0(a6,d2.w),d0
	move.w d0,d2
	not.w d2
	and.w d2,(a0)
	move.w $0006(a5),d3
	and.w d0,d3
	or.w d3,(a0)
	and.w d2,$2000(a0)
	move.w $0008(a5),d3
	and.w d0,d3
	or.w d3,$2000(a0)
	and.w d2,$4000(a0)
	move.w $000A(a5),d3
	and.w d0,d3
	or.w d3,$4000(a0)
	and.w d2,$6000(a0)
	move.w $000C(a5),d3
	and.w d0,d3
	or.w d3,$6000(a0)
	addq.w #2,a0
	cmpa.l a0,a1
	beq.w .last_word
.fill_words:
	move.w $0006(a5),(a0)
	move.w $0008(a5),$2000(a0)
	move.w $000A(a5),$4000(a0)
	move.w $000C(a5),$6000(a0)
	addq.w #2,a0
	cmpa.l a0,a1
	bne.b .fill_words
.last_word:
	move.w $0(a4,d4.w),d0
.merge_mask:
	move.w d0,d2
	not.w d2
	and.w d2,(a0)
	move.w $0006(a5),d1
	and.w d0,d1
	or.w d1,(a0)
	and.w d2,$2000(a0)
	move.w $0008(a5),d1
	and.w d0,d1
	or.w d1,$2000(a0)
	and.w d2,$4000(a0)
	move.w $000A(a5),d1
	and.w d0,d1
	or.w d1,$4000(a0)
	and.w d2,$6000(a0)
	move.w $000C(a5),d1
	and.w d0,d1
	or.w d1,$6000(a0)
PatternSpanDone:
	rts
    ; Span B has the same clipping, mask and plane-WORD contract as span A, but reads the second four pattern WORDs at state +14/+16/+18/+20. Its clipped branches share the existing return.
