    ; Subtract the clamped size from the shared Y WORD before drawing. Each profile scanline increments that WORD; the original Y is not restored by this helper.
abs_0_00010180:
	sub.w d5,$0002(a5)
	asl.w #2,d5
	lea.l smallRoundProfilePointers(pc),a3
	movea.l $0(a3,d5.w),a3
