	dc.w $4E75
    ; Original code writes choose BSET/BCLR by changing bit 6 of four instruction low bytes at caller A1 offsets 1/3/7/11. Reconstruct this self-write; do not infer arbitrary patch targets.
SetFourPlaneBitOperationMask:
	move.w d0,-(a7)
	bclr.b #6,$0001(a1)
	lsr.w #1,d0
	bcc.b abs_0_000113AC
	bset.b #6,$0001(a1)
abs_0_000113AC:
	bclr.b #6,$0003(a1)
	lsr.w #1,d0
	bcc.b abs_0_000113BC
	bset.b #6,$0003(a1)
abs_0_000113BC:
	bclr.b #6,$0007(a1)
	lsr.w #1,d0
	bcc.b abs_0_000113CC
	bset.b #6,$0007(a1)
abs_0_000113CC:
	bclr.b #6,$000B(a1)
	lsr.w #1,d0
	bcc.b abs_0_000113DC
	bset.b #6,$000B(a1)
abs_0_000113DC:
	move.w (a7)+,d0
	rts
    ; Use D5 as radius term and D0 as four-plane set/clear mask. Save registers, configure the four pixel operations and visit eight symmetric center offsets through the existing clipping helper.
DrawClippedFourPlaneCircle:
	movem.l d0-d7/a0-a6,-(a7)
	lea.l circlePlaneBitOperations.l,a1
	bsr.b SetFourPlaneBitOperationMask
	lea.l BasePlaneBuffer.l,a0
	adda.l gDrawBankByteOffset.l,a0
	moveq.l #0,d7
	moveq.l #0,d6
abs_0_000113FC:
	move.w gCircleRasterCenterX(pc),d0
	move.w gCircleRasterCenterY(pc),d1
	sub.w d6,d1
	add.w d5,d0
	bsr.w PlotClippedCirclePoint
	move.w gCircleRasterCenterX(pc),d0
	move.w gCircleRasterCenterY(pc),d1
	sub.w d6,d1
	sub.w d5,d0
	bsr.w PlotClippedCirclePoint
	move.w gCircleRasterCenterX(pc),d0
	move.w gCircleRasterCenterY(pc),d1
	add.w d6,d1
	sub.w d5,d0
	bsr.w PlotClippedCirclePoint
	move.w gCircleRasterCenterX(pc),d0
	move.w gCircleRasterCenterY(pc),d1
	add.w d6,d1
	add.w d5,d0
	bsr.w PlotClippedCirclePoint
	move.w gCircleRasterCenterX(pc),d0
	move.w gCircleRasterCenterY(pc),d1
	sub.w d6,d0
	add.w d5,d1
	bsr.w PlotClippedCirclePoint
	move.w gCircleRasterCenterX(pc),d0
	move.w gCircleRasterCenterY(pc),d1
	sub.w d6,d0
	sub.w d5,d1
	bsr.w PlotClippedCirclePoint
	move.w gCircleRasterCenterX(pc),d0
	move.w gCircleRasterCenterY(pc),d1
	add.w d6,d0
	sub.w d5,d1
	bsr.w PlotClippedCirclePoint
	move.w gCircleRasterCenterX(pc),d0
	move.w gCircleRasterCenterY(pc),d1
	add.w d6,d0
	add.w d5,d1
	bsr.w PlotClippedCirclePoint
	add.w d6,d7
	addq.w #1,d6
	cmp.w d5,d7
	blt.w abs_0_000113FC
	sub.w d5,d7
	subq.w #1,d5
	cmp.w d6,d5
	bge.w abs_0_000113FC
	movem.l (a7)+,d0-d7/a0-a6
	rts
    ; Plot only for X=26..294 and Y=16..127. Address the selected bank with forty-byte rows and four 2000-hex plane offsets; visible output and bank validity remain unobserved.
PlotClippedCirclePoint:
	cmp.w #$80,d1
	bge.w abs_0_000114B6
	cmp.w #$F,d1
	ble.w abs_0_000114B6
	cmp.w #$19,d0
	ble.w abs_0_000114B6
	cmp.w #$127,d0
	blt.w abs_0_000114B8
abs_0_000114B6:
	rts
abs_0_000114B8:
	move.w d1,d2
	mulu.w #$28,d2
	lea.l (a0),a1
	adda.w d2,a1
	move.w d0,d3
	move.w d3,d2
	asr.w #3,d2
	adda.w d2,a1
	not.w d3
	andi.w #7,d3
circlePlaneBitOperations:
	bset.b d3,(a1)
	bset.b d3,$2000(a1)
	bset.b d3,$4000(a1)
	bset.b d3,$6000(a1)
	rts
gCircleRasterCenterY:
	dc.w $0000
gCircleRasterCenterX:
	dc.w $0000
    ; Show rank/identity and require the dock-status bit. Select a new mission or dispatch its checker at the check system; other-system visits show the active notice.
HandleFederationHeadquarters:
	jsr fClsCommand.l
	lea.l headquartersIntroTextRecords(pc),a6
	jsr DrawTextLines.l
	move.w gRank.l,d0
	add.w d0,d0
	add.w d0,d0
	lea.l tableRankStrings.l,a0
	movea.l $0(a0,d0.w),a0
	move.w #$C,(a0)
	move.w #$24,$0002(a0)
	jsr DisplayText1.l
	lea.l sNetHello.l,a1
	lea.l playerIdentityTextRecord.l,a0
	move.l $000A(a1),$0004(a0)
	move.l $000E(a1),$0008(a0)
	move.l $0012(a1),$000C(a0)
	move.l $0016(a1),$0010(a0)
	move.l $001A(a1),$0014(a0)
	move.w #$16,(a0)
	move.w #$24,$0002(a0)
	move.w #$0,$0010(a0)
	jsr DisplayText1.l
	jsr WaitMissionDisplayHandshakes.l
	btst.b #4,abs_0_0004E37C.l
	bne.b .check_active_mission
	lea.l sPleaseWaitUntilDocked(pc),a0
	jsr DisplayText1.l
	jsr WaitMissionDisplayHandshakes.l
	jsr fClsCommand.l
	clr.w flagKeyDownEvent.l
	rts
sPleaseWaitUntilDocked:
	dc.w $0005
	dc.w $005A
	dc.b "Please Wait Until Docked",$00
	dc.b $00	; opaque_data
HandleFederationHeadquarters\.check_active_mission:
	tst.w gMissionActive.l
	bne.w HandleFederationHeadquarters\.check_mission_system
	lea.l textSelectingMission(pc),a0
	jsr DisplayText1.l
	jsr WaitMissionDisplayHandshakes.l
	jsr fClsCommand.l
	lea.l sFedHQ(pc),a0
	jsr DisplayText1.l
	moveq.l #3,d2
	moveq.l #2,d1
	move.w gRank.l,d0
HandleFederationHeadquarters\.build_mission_mask:
	bset d1,d2
	addq.w #1,d1
	dbf.w d0,HandleFederationHeadquarters\.build_mission_mask
	jsr RandomWordMaybe.l
	and.w d2,d0
	andi.w #15,d0
    ; The final AND 15 bounds a new mission type to sixteen table slots. This same WORD is later zero-extended as the rank-point reward or failure penalty; active dispatch does not remask it here.
	move.w d0,gMissionTypeAndRankReward.l
	add.w d0,d0
	add.w d0,d0
	lea.l tableMissions(pc),a0
	movea.l $0(a0,d0.w),a0
	jsr (a0)
    ; After the chosen assignment and its shared acknowledgment return, clear both intercept outcome WORDs for every assignment. The original alien ID writer also overlaps these bytes.
	clr.w gInterceptOutcomeWord0.l
	clr.w gInterceptOutcomeWord1.l
	clr.w gConvoyShipsLost.l
	clr.w gPatrolCategory7RemovalCount.l
	rts
HandleFederationHeadquarters\.check_mission_system:
	lea.l sFedHQ(pc),a0
	jsr DisplayText1.l
    ; Only a matching current system reaches the checker. The galaxy map and encounter setup also consume this check-system field; the displayed second system is separate.
	move.w gMissionCheckSystemIndex.l,d0
	cmp.w gCurrentSystemIndex.l,d0
	bne.b HandleFederationHeadquarters\.show_active_elsewhere
	move.w gMissionTypeAndRankReward.l,d0
	add.w d0,d0
	add.w d0,d0
	lea.l tableMissionChecks(pc),a0
	movea.l $0(a0,d0.w),a0
	jsr (a0)
	rts
HandleFederationHeadquarters\.show_active_elsewhere:
	lea.l textMissionActive(pc),a0
	jsr DisplayText1.l
	jsr WaitMissionDisplayHandshakes.l
	bra.w AcknowledgeMissionAssignment
headquartersIntroTextRecords:
	dc.l sFedHQ
	dc.l sWelcomeToFedHQ
	dc.l sAccessingRecords
	dc.l $00000000	; pointer_table
sFedHQ:
	dc.w $0004
	dc.w $0012
	dc.b "* Federation Headquarters *",$00
sWelcomeToFedHQ:
	dc.w $0004
	dc.w $0024
	dc.b "Welcome",$00
sAccessingRecords:
	dc.w $0004
	dc.w $0036
	dc.b "Accessing Records",$00
textSelectingMission:
	dc.w $0004
	dc.w $003F
	dc.b "Selecting Mission",$00
textMissionActive:
	dc.w $0004
	dc.w $003F
	dc.b "Mission Active",$00
	dc.b $00	; opaque_data
    ; Sixteen LONG setup-slot values addressed by the selected type times four. These are code destinations, not a data-pointer table declaration or new code-entry seeds.
tableMissions:
	dc.l $00011CDE,$00011D72,$00011E1C,$00011EFC
	dc.l $00011F9A,$000120D6,$0001216A,$00012206
	dc.l $000122A2,$0001233A,$00012470,$00012552
	dc.l $00012630,$000126C6,$00012758,$00012470
    ; Sixteen LONG checker-slot values. Slot nine selects the evacuation checker. Scalar storage typing preserves literals and existing code admission; it does not prove all dynamic checker states.
tableMissionChecks:
	dc.l $00011770,$00011770,$0001186C,$0001187A
	dc.l $000118F2,$0001197A,$000119E4,$00011A08
	dc.l $00011A3C,$00011A52,$000119E4,$00011AE0
	dc.l $00011AEE,$00011B14,$00011758,$000119E4
    ; Copy recorded destruction to D0, clear both pirate-base flags, then test the saved WORD. Zero fails; nonzero falls directly into shared completion without a separate success message.
fMissionCheckSearchForPirateBase:
	move.w gPirateBaseDestructionRecorded.l,d0
	clr.w gPirateBaseDestructionRecorded.l
	clr.w gPirateBaseSearchEnabled.l
	tst.w d0
	beq.w MissionFailed
    ; Shared completion adds unsigned credit and rank rewards, clears mission-active, displays payment and refreshes rank. Acknowledgment precedes clearing the three scenario flags.
CompleteMissionAndAwardRewards:
	move.w gRewardCredits.l,d0
	andi.l #65535,d0
	add.l d0,gCreditBalance.l
	clr.w gMissionActive.l
	lea.l textMissionComplete1(pc),a0
	jsr DisplayText1.l
	lea.l textMissionComplete2(pc),a0
	jsr DisplayText1.l
	lea.l textMissionComplete3(pc),a0
	jsr DisplayText1.l
	moveq.l #20,d0
	moveq.l #90,d1
	jsr MoveCursor.l
	move.w gRewardCredits.l,d2
	jsr DrawBase10Number.l
	move.w gMissionTypeAndRankReward.l,d0
	andi.l #65535,d0
	add.l d0,gRankPointsBalance.l
	jsr UpdatePlayerRank.l
	clr.w flagKeyDownEvent.l
.wait_ack:
	tst.w flagKeyDownEvent.l
	beq.b .wait_ack
	clr.w flagKeyDownEvent.l
	jsr fClsCommand.l
	clr.w gMissionEncounterOverride.l
	clr.w gLostShipSearchEnabled.l
	clr.w gLostShipRecoveryRecorded.l
	rts
textMissionComplete1:
	dc.w $0005
	dc.w $0051
	dc.b "WELL DONE     Mission Complete",$00
	dc.b $00	; opaque_data
textMissionComplete2:
	dc.w $0005
	dc.w $0063
	dc.b "Please Redial For Next Mission",$00
	dc.b $00	; opaque_data
textMissionComplete3:
	dc.w $0005
	dc.w $005A
	dc.b "Please accept         credits",$00
    ; A nonzero category-7 removal count fails; zero enters shared completion. This checker does not require a separate hostile-removal count and does not clear its input.
fMissionCheckPatrolSystem:
	tst.w gPatrolCategory7RemovalCount.l
	bne.w MissionFailed
	bra.w CompleteMissionAndAwardRewards
    ; Disable escort. No losses completes; one to four sets payment 50 before completion; more than four fails. Preserve storage and original signed comparisons.
fMissionCheckEscortConvoyToSystem:
	clr.w gConvoyEscortEnabled.l
	move.w gConvoyShipsLost.l,d0
	beq.w CompleteMissionAndAwardRewards
	cmp.w #$4,d0
	ble.b .partial_loss_reward
	lea.l textTooManyShipsLost(pc),a0
	jsr DisplayText1.l
	bra.w MissionFailed
.partial_loss_reward:
	lea.l textMissionPartialSuccessShipsLost(pc),a0
	jsr DisplayText1.l
	move.w #$32,gRewardCredits.l
	bra.w CompleteMissionAndAwardRewards
textTooManyShipsLost:
	dc.w $0005
	dc.w $003F
	dc.b "Too Many Ships Lost",$00
textMissionPartialSuccessShipsLost:
	dc.w $0005
	dc.w $003F
	dc.b "Partial Success - Some Ships lost",$00
    ; First check copies secondary to check system, enables escort and sets ready. Later checks delegate to escort outcomes. The evacuation checker lacks this direct handoff.
CheckConvoyRendezvousProgress:
	tst.w gConvoyRendezvousReady.l
	bne.b fMissionCheckEscortConvoyToSystem
	move.w gMissionSecondarySystemIndex.l,gMissionCheckSystemIndex.l
	st.b gConvoyEscortEnabled.l
	st.b gConvoyRendezvousReady.l
	lea.l sConvoyReady(pc),a0
	jsr DisplayText1.l
	lea.l sProceedWithMission(pc),a0
	jsr DisplayText1.l
	clr.w flagKeyDownEvent.l
.wait_ready_ack:
	tst.w flagKeyDownEvent.l
	beq.b .wait_ready_ack
	clr.w flagKeyDownEvent.l
	jsr fClsCommand.l
	rts
sConvoyReady:
	dc.w $0005
	dc.w $0048
	dc.b "   Convoy Is Now Ready ",$00
sProceedWithMission:
	dc.w $0005
	dc.w $0051
	dc.b "   Proceed With Mission",$00
gConvoyRendezvousReady:
	dc.w $0000
    ; At the eligible HQ system, zero recovery-recorded fails. Nonzero displays the saved-trader messages and enters shared completion; the flag is not proof of a physical pickup.
fMissionCheckSearchForLostShip:
	tst.w gLostShipRecoveryRecorded.l
	beq.w MissionFailed
	lea.l sCongratsYouSavedTrader1(pc),a0
	jsr DisplayText1.l
	lea.l sCongratsYouSavedTrader2(pc),a0
	jsr DisplayText1.l
	bra.w CompleteMissionAndAwardRewards
sCongratsYouSavedTrader1:
	dc.w $0005
	dc.w $003F
	dc.b "Congratulations You have Saved",$00
	dc.b $00	; opaque_data
sCongratsYouSavedTrader2:
	dc.w $0006
	dc.w $0048
	dc.b "  The Life Of A Fellow Trader ",$00
	dc.b $00	; opaque_data
    ; Shared by slots 6, 10 and 15: subtract the LONG baseline, fail on full-LONG zero, then use signed low-WORD comparisons with 5 and 20. This is not a dedicated hostile-removal count.
CheckMissionRankPointProgress:
	move.l gRankPointsBalance.l,d0
	sub.l gMissionRankPointBaseline.l,d0
	beq.w MissionFailed
	cmp.w #$5,d0
	ble.w MissionFailed
	cmp.w #$14,d0
	blt.w MissionPartialSuccess
	bra.w CompleteMissionAndAwardRewards
    ; A nonzero satellite destruction record displays its message and completes; zero fails. The checker does not directly clear either satellite flag.
fMissionCheckDestroyFaultySatellite:
	tst.w gSatelliteDestructionRecorded.l
	beq.w MissionFailed
	lea.l sSatelliteDestroyed(pc),a0
	jsr DisplayText1.l
	bra.w CompleteMissionAndAwardRewards
sSatelliteDestroyed:
	dc.w $0005
	dc.w $003F
	dc.b "    Satellite Destroyed",$00
    ; Progress zero fails; exactly eight completes; any other nonzero WORD enters shared partial success. The recognized listing has no progress increment; do not infer the missing writer.
fMissionCheckDestroyMeteorites:
	move.w gMeteoriteProgressCount.l,d0
	beq.w MissionFailed
	cmp.w #$8,d0
	bne.w MissionPartialSuccess
	bra.w CompleteMissionAndAwardRewards
    ; If civilians-loaded is nonzero, enter shared completion. Otherwise require landing-recorded, display/set civilians-loaded and return after acknowledgment without payment.
fMissionCheckEvacuateCivilians:
	tst.w gEvacuationCiviliansLoaded.l
	bne.w CompleteMissionAndAwardRewards
	tst.w gAutomaticLandingRecorded.l
	beq.w MissionFailed
	lea.l sCiviliansLoaded1(pc),a0
	jsr DisplayText1.l
	lea.l sCiviliansLoaded2(pc),a0
	jsr DisplayText1.l
    ; Set only the first BYTE of the civilians-loaded WORD. This checker does not copy the secondary system into the mission check system or clear landing-recorded. Preserve the two-stage ordering.
	st.b gEvacuationCiviliansLoaded.l
	clr.w flagKeyDownEvent.l
.wait_loaded_ack:
	tst.w flagKeyDownEvent.l
	beq.b .wait_loaded_ack
	clr.w flagKeyDownEvent.l
	jsr fClsCommand.l
	rts
    ; Zero WORD, BYTE-set/tested by evacuation. Outside reset/save/load copies, unlike landing-recorded. No assignment clear or post-load refresh is proved; helper and alias writes remain open.
gEvacuationCiviliansLoaded:
	dc.w $0000
sCiviliansLoaded1:
	dc.w $0005
	dc.w $003F
	dc.b "     Civilians now loaded",$00
	dc.b $00	; opaque_data
	dc.b $00	; opaque_data
sCiviliansLoaded2:
	dc.w $0005
	dc.w $0051
	dc.b "  Continue with your mission",$00
	dc.b $00	; opaque_data
    ; Alien assignment BYTE-sets the outcome WORD. HQ fails on nonzero and completes on zero. No recognized direct encounter clear or comparison with the generated identity is established.
CheckAlienMissionOutcomeWord:
	tst.w gAlienMissionOutcomeWord.l
	bne.w MissionFailed
	bra.w CompleteMissionAndAwardRewards
    ; Only a nonzero first WORD with a zero second WORD fails here. Otherwise the signed second WORD is compared with four; below four is partial success, the rest shared completion.
CheckInterceptOutcomeWords:
	move.w gInterceptOutcomeWord0.l,d0
	beq.w .check_second_word
	move.w gInterceptOutcomeWord1.l,d0
	beq.w MissionFailed
.check_second_word:
	move.w gInterceptOutcomeWord1.l,d0
	cmp.w #$4,d0
	blt.w MissionPartialSuccess
	bra.w CompleteMissionAndAwardRewards
    ; A nonzero VIP outcome WORD fails; zero enters shared completion. Assignment BYTE-sets this WORD. Its ordinary encounter clear/producer is not established by recognized direct references.
CheckVIPEscortOutcomeWord:
	tst.w gVIPEscortOutcomeWord.l
	bne.w MissionFailed
	bra.w CompleteMissionAndAwardRewards
    ; Clear mission-active, subtract the unsigned type/reward WORD and clamp a negative rank-point balance to zero. Wait for acknowledgment, then clear the three scenario flags.
MissionFailed:
	lea.l textMissionFailure1(pc),a0
	jsr DisplayText1.l
	lea.l textMissionFailure2(pc),a0
	jsr DisplayText1.l
	move.w gMissionTypeAndRankReward.l,d0
	andi.l #65535,d0
	clr.w gMissionActive.l
	sub.l d0,gRankPointsBalance.l
	tst.l gRankPointsBalance.l
	bpl.b .prepare_ack
	clr.l gRankPointsBalance.l
.prepare_ack:
	clr.w flagKeyDownEvent.l
.wait_ack:
	tst.w flagKeyDownEvent.l
	beq.b .wait_ack
	clr.w flagKeyDownEvent.l
	jsr fClsCommand.l
	clr.w gMissionEncounterOverride.l
	clr.w gLostShipSearchEnabled.l
	clr.w gLostShipRecoveryRecorded.l
	rts
textMissionFailure1:
	dc.w $0005
	dc.w $003F
	dc.b "You have Failed In Your Mission",$00
textMissionFailure2:
	dc.w $0005
	dc.w $0048
	dc.b "   This Is Now On Your Record",$00
    ; Quarter the unsigned WORD credit reward by shifting right twice, then use shared completion. The rank-point amount is not quartered here; other callers can choose a different partial reward.
MissionPartialSuccess:
	lea.l sPartialSuccessPayment1(pc),a0
	jsr DisplayText1.l
	lea.l sPartialSuccessPayment2(pc),a0
	jsr DisplayText1.l
	lea.l sPartialSuccessPayment3(pc),a0
	jsr DisplayText1.l
	move.w gRewardCredits.l,d0
	lsr.w #2,d0
	move.w d0,gRewardCredits.l
	bra.w CompleteMissionAndAwardRewards
sPartialSuccessPayment1:
	dc.w $0002
	dc.w $0036
	dc.b "   Your Mission Was Only A Partial",$00
	dc.b $00	; opaque_data
sPartialSuccessPayment2:
	dc.w $0005
	dc.w $003F
