	move.w #$12C,gRewardCredits.l
	st.b gPirateBaseSearchEnabled.l
	clr.w gPirateBaseDestructionRecorded.l
	bra.w AcknowledgeMissionAssignment
textMissionSearchForPirateBase1:
	dc.w $0004
	dc.w $0024
	dc.b "Search for pirate base in system",$00
	dc.b $00	; opaque_data
textMissionSearchForPirateBase2:
	dc.w $0004
	dc.w $003F
	dc.b "  Engage and DESTROY if found ",$00
	dc.b $00	; opaque_data
    ; Choose a non-current primary system, store it as the check-system index and display its number/name. Mask/reduction and procedural reseeding are unchanged; no termination proof is added.
ChooseAndDisplayMissionCheckSystem:
	jsr RandomWordMaybe.l
	andi.w #255,d0
.reduce_candidate:
	cmp.w gSystemCoordinateLastIndex.l,d0
	ble.b .reject_current
	subq.w #8,d0
	bra.b .reduce_candidate
.reject_current:
	cmp.w gCurrentSystemIndex.l,d0
	beq.b ChooseAndDisplayMissionCheckSystem
	move.w d0,-(a7)
	moveq.l #12,d0
	moveq.l #45,d1
	jsr MoveCursor.l
	move.w (a7)+,d2
	move.w d2,gMissionCheckSystemIndex.l
	jsr DrawBase10Number.l
	move.w gMissionCheckSystemIndex.l,d0
	swap.w d0
	move.w gMissionCheckSystemIndex.l,d0
	move.l abs_0_0004E380.l,d1
	eor.l d1,d0
	jsr SeedProceduralSequenceAndNext.l
	jsr GenerateSystemNameGlyphs.l
	lea.l generatedSystemNameGlyphs.l,a0
	lea.l missionCheckSystemNameText.l,a1
	move.w gGeneratedSystemNameGlyphCount.l,d7
	subq.w #1,d7
.copy_name_ascii:
	move.w (a0)+,d0
	subi.w #50,d0
	ext.l d0
	divu.w #$5,d0
	addi.b #97,d0
	move.b d0,(a1)+
	dbf.w d7,.copy_name_ascii
	clr.b (a1)
	lea.l sMissionCheckSystemName.l,a0
	jsr DisplayText1.l
	rts
    ; EDI ships handler: start at model 0 and save only the draw-buffer offset. Shared view/model state is not snapshotted; the advance countdown is not reset on entry.
fShipsCommand:
	movem.l d0-d7/a0-a6,-(a7)
	clr.w shipsMenuShipIndex.l
	st.b gTextScrollSuppressed.l
	move.l gDrawBankByteOffset.l,gShipsMenuSavedBufferOffset.l
.preview_frame:
	jsr WaitIrqAndPresentDrawBuffer.l
	clr.w gViewPitchIncrement.l
	clr.w gViewRollIncrement.l
    ; Both view increments were cleared: retain/clamp the shared nine-WORD orientation and rebuild doubled basis and scale terms. This is not a reset to an identity camera.
	jsr RotateClampAndBuildBodyViewBasis.l
	jsr BuildBodyViewSignedScaleTable.l
	jsr DrawPlaneWordOccupancyGrid.l
	move.w gFlapperScaleStepIndex.l,d0
	add.w gFlapperScaleStepDelta.l,d0
	move.w d0,gFlapperScaleStepIndex.l
	bpl.b .check_scale_step_limit
	move.w #$0,gFlapperScaleStepIndex.l
	move.w #$1,gFlapperScaleStepDelta.l
	bra.b .prepare_preview
.check_scale_step_limit:
	cmp.w #$4,d0
	blt.b .prepare_preview
	move.w #$FFFF,gFlapperScaleStepDelta.l
.prepare_preview:
	jsr ClearViewRectangleFourPlanes.l
	clr.w gViewPitchIncrement.l
	clr.w gViewRollIncrement.l
	jsr RotateClampAndBuildBodyViewBasis.l
	jsr BuildBodyViewSignedScaleTable.l
    ; Clear these three original WORDs. Their wider ownership and consumer contract remain unproved; do not merge them with the preceding scale table.
	clr.w abs_0_00015BCA.l
	clr.w abs_0_00015BCC.l
	clr.w abs_0_00015BCE.l
	lea.l shipsMenuModelDepths(pc),a1
	move.w shipsMenuShipIndex(pc),d0
	add.w d0,d0
	adda.w d0,a1
	lea.l viewObjectRecords.l,a0
    ; Preview writes the view row first ten bytes: XY, depth and draw address. It does not initialize the trailing stateOffsetOrMarker WORD; this producer supplies no current source-state mapping.
	move.l #$0,(a0)	; operand 2: PackedObjectViewRecord_x at (a0)
	move.w (a1),PackedObjectViewRecord_z(a0)
    ; The masked menu index selects the same ship-model slot, depth WORD and specification list. Prefix WORDs are mutable shared state; this preview does not create private per-menu orientations.
	lea.l tableShipData.l,a1
	add.w d0,d0
    ; Read tableShipData with the current WORD-derived selection into packed +6. Mutable selection and header aliases are distinct from the initial 32 table entries.
	move.l $0(a1,d0.w),PackedObjectViewRecord_drawAddress(a0)
	movea.l PackedObjectViewRecord_drawAddress(a0),a1
    ; SUBQ.W to an address register adjusts the full address by six. This selects the shared model prefix; the following three WORD updates do not create private packed-row orientations.
	subq.w #6,a1
	addq.w #2,(a1)
	addq.w #2,$0002(a1)
	addq.w #2,$0004(a1)
	andi.w #511,(a1)
	andi.w #511,$0002(a1)
	andi.w #511,$0004(a1)
	moveq.l #1,d7
	jsr DrawDepthOrderedObjectViews.l
	move.w shipsMenuShipIndex.l,d0
	add.w d0,d0
	add.w d0,d0
	lea.l tableShipSpecText.l,a6
	movea.l $0(a6,d0.w),a6
    ; Model index 0..31 selects 13 display-record pointers and an unconsumed zero LONG. Seven headings are shared by address; equal text at distinct addresses stays distinct.
	jsr DrawTextLines.l
	lea.l bufferKeyboardState.l,a0
    ; Logical Q WORD is active at zero. Exit clears scroll suppression and both text buffers, restores the saved offset, presents once more and returns to the EDI command loop.
	tst.w $0020(a0)
	bne.b .check_advance
	clr.w gTextScrollSuppressed.l
	jsr fClsCommand.l
	move.l gShipsMenuSavedBufferOffset.l,gDrawBankByteOffset.l
	jsr WaitIrqAndPresentDrawBuffer.l
	movem.l (a7)+,d0-d7/a0-a6
	rts
    ; Negative skips decrement. Otherwise decrement and wait while nonnegative; then test Return. Advance wraps with AND 31 and reloads 10. Counts loop visits, not elapsed time.
.check_advance:
	tst.w gShipsMenuAdvanceCountdown.l
	bmi.b .test_next_model
	subq.w #1,gShipsMenuAdvanceCountdown.l
	bpl.w .preview_frame
.test_next_model:
	tst.w $0038(a0)
	bne.w .preview_frame
	addq.w #1,shipsMenuShipIndex.l
	andi.w #31,shipsMenuShipIndex.l
	move.w #$A,gShipsMenuAdvanceCountdown.l
	bra.w .preview_frame
