    ; Expand nine existing body-basis WORDs into nine 28-byte blocks. Each block holds seven arithmetic-shift terms and their WORD negations; reuse shared scratch, not a private camera.
BuildBodyViewSignedScaleTable:
	lea.l bodyViewSignedScaleWords.l,a0
	lea.l (a0),a2	; operand 1: SignedHalfScaleBlock_valueShift14 at (a0)
	move.w bodyViewBasisWords.l,d0
	bsr.w WriteBodyViewSignedScaleBlock
	lea.l SignedHalfScaleBlock_valueShift14+3*SignedHalfScaleBlock_SIZEOF(a0),a0
	move.w bodyViewBasisWords_m10.l,d0
	bsr.w WriteBodyViewSignedScaleBlock
	lea.l SignedHalfScaleBlock_valueShift14+3*SignedHalfScaleBlock_SIZEOF(a0),a0
	move.w bodyViewBasisWords_m20.l,d0
	bsr.w WriteBodyViewSignedScaleBlock
	lea.l SignedHalfScaleBlock_valueShift14+SignedHalfScaleBlock_SIZEOF(a2),a0
	move.w bodyViewBasisWords_m01.l,d0
	bsr.w WriteBodyViewSignedScaleBlock
	lea.l SignedHalfScaleBlock_valueShift14+3*SignedHalfScaleBlock_SIZEOF(a0),a0
	move.w bodyViewBasisWords_m11.l,d0
	bsr.w WriteBodyViewSignedScaleBlock
	lea.l SignedHalfScaleBlock_valueShift14+3*SignedHalfScaleBlock_SIZEOF(a0),a0
	move.w bodyViewBasisWords_m21.l,d0
	bsr.w WriteBodyViewSignedScaleBlock
	lea.l SignedHalfScaleBlock_valueShift14+2*SignedHalfScaleBlock_SIZEOF(a2),a0
	move.w bodyViewBasisWords_m02.l,d0
	bsr.w WriteBodyViewSignedScaleBlock
	lea.l SignedHalfScaleBlock_valueShift14+3*SignedHalfScaleBlock_SIZEOF(a0),a0
	move.w bodyViewBasisWords_m12.l,d0
	bsr.w WriteBodyViewSignedScaleBlock
	lea.l SignedHalfScaleBlock_valueShift14+3*SignedHalfScaleBlock_SIZEOF(a0),a0
	move.w bodyViewBasisWords_m22.l,d0
