WriteBodyViewSignedScaleBlock:
	moveq.l #12,d1
	ext.l d0
	asr.l #7,d0
.halve_and_store:
	asr.l #1,d0
	move.w d0,d2
	neg.w d2
	move.w d0,$0(a0,d1.w)
	move.w d2,$E(a0,d1.w)
	subq.w #2,d1
	bpl.b .halve_and_store
	rts
