    ; Raster points are screen-space WORD pairs; bounds scan and both chains step four bytes. Scanline edge pairs have phase-dependent order, so x0/x1 do not mean permanent left/right edges.
RasterizeProjectedPolygon:
	lea.l polygonScreenVertexPairs(pc),a4
	lea.l pPolygonMaskRow(pc),a5
    ; Input d7w
	subq.w #1,d7
	move.l #$70000,d0
	add.l gDrawBankByteOffset.l,d0
	move.l d0,$0008(a5)
	lea.l (a4),a3	; operand 1: ScreenPointRecord_x at (a4)
	move.w #$7FFF,d0
	move.w #$8000,d1
	move.w d0,d2
	move.w d1,d3
	move.w d7,d6
.scan_bounds:
	cmp.w $0002(a3),d0
	blt.b .check_max_y
	move.w $0002(a3),d0
	lea.l (a3),a2
.check_max_y:
	cmp.w $0002(a3),d1
	bgt.b .check_min_x
	move.w $0002(a3),d1
.check_min_x:
	cmp.w (a3),d2
	blt.b .check_max_x
	move.w (a3),d2
.check_max_x:
	cmp.w (a3),d3
	bgt.b .next_bound_vertex
	move.w (a3),d3
.next_bound_vertex:
	addq.w #4,a3
	dbf.w d6,.scan_bounds
	cmp.w #$7F,d0
	bgt.w PolygonRasterReturn
	cmp.w #$F,d1
	blt.w PolygonRasterReturn
	cmp.w #$126,d2
	bgt.w PolygonRasterReturn
	cmp.w #$19,d3
	blt.w PolygonRasterReturn
	move.w d0,gPolygonBoundsMinY.l
	move.w d1,gPolygonBoundsMaxY.l
	move.w d2,gPolygonBoundsMinX.l
	move.w d3,gPolygonBoundsMaxX.l
    ; With a stable original 3..6-point face, the circular forward walk reaches a computed maximum within six points. This 24-byte source view is not the whole 64-byte backing interval.
	lea.l polygonForwardEdgeVertices(pc),a0
	lea.l (a2),a1
.copy_forward_chain:
	move.w (a1)+,(a0)+
	move.w (a1)+,(a0)+
	cmpa.l a1,a3
	bne.b .forward_wrapped
	lea.l (a4),a1	; operand 1: ScreenPointRecord_x at (a4)
.forward_wrapped:
	cmp.w $0002(a1),d1
	bne.b .copy_forward_chain
	move.w (a1)+,(a0)+
	move.w (a1)+,(a0)+
