	addi.l #91224,d0
	move.l d0,(a5)
	lea.l polygonForwardEdgeVertices(pc),a0
	lea.l polygonEdgeXPairs(pc),a1
	bsr.w BuildPolygonEdgeXByScanline
	lea.l polygonReverseEdgeVertices(pc),a0
