	lea.l polygonForwardEdgeVertices+130(pc),a1
	bsr.w BuildPolygonEdgeXByScanline
	lea.l polygonXSpanRecords(pc),a3
	lea.l polygonEdgeXPairs(pc),a2
	move.l a4,d4
	move.w $0006(a5),d0
	cmp.w #$F,d0
	bge.b .fill_scanline
	move.w #$F,d0
	move.w d0,$0006(a5)
	mulu.w #$28,d0
	addi.l #91224,d0
	move.l d0,(a5)
.fill_scanline:
	moveq.l #-1,d6
	move.w (a2)+,d0
	move.w (a2)+,d1
	cmp.w d1,d0
	blt.b .order_span
	exg d0,d1
.order_span:
