	move.w gPolygonBoundsMinY.l,d0
	cmp.w #$F,d0
	bge.b .top_clipped
	move.w #$F,d0
.top_clipped:
	move.w d0,d1
	mulu.w #$28,d1
	movea.l d1,a0
	move.w gPolygonBoundsMinX.l,d1
	cmp.w #$19,d1
