	move.w #$19,d1
.left_clipped:
	move.w d1,d2
	lsr.w #3,d2
	andi.w #254,d2
	adda.w d2,a0
	lea.l (a0),a1
    ; Mask source is $16458 + clippedY*40 + aligned X byte offset. The four destination planes use a separate display base; no exclusive owner of surrounding scratch is proved.
