    ; Initialize 320 eight-byte X-span rows: byte offset and start/end mask WORDs, skip +6. Sparse PolygonXSpanRecord preserves that unknown WORD; the mask fill reads only the three proved fields.
InitializePolygonSpanLookup:
	moveq.l #0,d7
	lea.l polygonXSpanRecords.l,a0
	lea.l polygonSpanStartMasks(pc),a1
	lea.l polygonSpanEndMasks(pc),a2
.next_x:
	move.w d7,d0
    ; counter/8
	lsr.w #3,d0
	andi.w #65534,d0
	move.w d0,(a0)+
	move.w (a1)+,(a0)+
	move.w (a2)+,(a0)+
	addq.w #2,a0
	addq.w #1,d7
	move.w d7,d0
	andi.w #15,d0
	bne.b .next_group
	lea.l polygonSpanStartMasks(pc),a1
	lea.l polygonSpanEndMasks(pc),a2
.next_group:
	cmp.w #$140,d7
	bne.b .next_x
	rts
polygonSpanStartMasks:
	dc.w $FFFF,$7FFF,$3FFF,$1FFF,$0FFF,$07FF,$03FF,$01FF
	dc.w $00FF,$007F,$003F,$001F,$000F,$0007,$0003,$0001
polygonSpanEndMasks:
	dc.w $8000,$C000,$E000,$F000,$F800,$FC00,$FE00,$FF00
	dc.w $FF80,$FFC0,$FFE0,$FFF0,$FFF8,$FFFC,$FFFE,$FFFF
    ; Clips endpoint WORDs D0/D1 and D2/D3, rejects zero length and prepares line-mode state for four planes. The last submit returns without another local wait.
DrawClippedLineOnFourPlanes:
	bsr.w ClipLine_X26To295_Y16To127
	tst.w d7
	bpl.b .order_by_x_ascending
	rts
    ; Accepted endpoints are ordered by X: exchange both pairs unless X1 > X0, including equal-X lines. D7 is reused in setup; the outer renderer does not retain the clipper status contract.
.order_by_x_ascending:
	cmp.w d0,d2
	bgt.b .exclude_zero_length
	exg d0,d2
	exg d1,d3
.exclude_zero_length:
	cmp.w d0,d2
	bne.b .line_valid
	cmp.w d1,d3
	bne.b .line_valid
	rts
.line_valid:
	move.w #$BFA,d4
    ; BLTCON1 = LINE
	move.w #$1,d5
	move.w d0,d6
    ; ASH bits (x0&1111b)
	andi.w #15,d6
    ; Put ASH bits into place.
	ror.w #4,d6
    ; BLT0CON |= ASH high bits
	or.w d6,d4
    ; Cache (X0 & 15) in BLTCON0 shift bits. Subsequent WORD delta arithmetic prepares line-mode octant, error accumulator, two error increments and BLTSIZE.
	move.w d4,vLineDrawBLTCON0.l
	move.w d3,d4
	sub.w d1,d4
	move.w d4,-(a7)
	bpl.b .abs_y_delta
	neg.w d4
.abs_y_delta:
	move.w d4,d6
	move.w #$28,vLineDrawBLTCMOD.l
	move.w #$28,vLineDrawBLTDMOD.l
	add.w d6,d6
	move.w d6,d7
	add.w d6,d6
	move.w d6,vLineDrawErrorStepB.l
	move.w d2,d4
	sub.w d0,d4
	move.w d4,-(a7)
	bpl.b .abs_x_delta
	neg.w d4
.abs_x_delta:
	sub.w d4,d7
	move.w d7,vLineDrawInitialError.l
	sub.w d4,d7
	add.w d7,d7
	move.w d7,vLineDrawErrorStepA.l
	move.w (a7)+,d7
	move.w (a7)+,d6
	tst.w d6
	bpl.b .nonnegative_y
	neg.w d6
	cmp.w d7,d6
	bge.b .negative_y_major
    ; BLT1CON = LINE | SUL | SUD
	ori.w #24,d5
	bra.w .octant_ready
    ; BLT1CON = LINE | AUL
.negative_y_major:
	ori.w #4,d5
	bra.w .octant_ready
.nonnegative_y:
	cmp.w d6,d7
	ble.b .octant_ready
    ; BLT1CON = LINE | SUD
	ori.w #16,d5
.octant_ready:
	move.w d5,vLineDrawBLTCON1.l
	cmp.w d6,d7
	bge.b .x_major
	move.w d3,d4
	neg.w vLineDrawErrorStepA.l
	move.w d2,d7
	sub.w d0,d7
	add.w d7,d7
	add.w d7,d7
	move.w d7,vLineDrawErrorStepB.l
	sub.w d1,d4
	bpl.b .size_ready
	neg.w d4
	bra.w .size_ready
.x_major:
	move.w d2,d4
	sub.w d0,d4
	bpl.b .size_ready
	neg.w d4
.size_ready:
	lsl.w #6,d4
	ori.w #2,d4
	move.w d4,vLineDrawBLTSIZE.l
	andi.w #65520,d0
	asr.w #3,d0
	mulu.w #$28,d1
	add.w d1,d0
    ; Cache Y0*40 + 2*(X0 >> 4) for the clipped starting pixel. Both C and D use this offset at the current display base; later planes advance $2000 bytes.
	move.w d0,vLineDrawCDScreenOffset.l
	bsr.w WaitBlitterReady
	move.w vLineDrawBLTCON0(pc),_custom+bltcon0.l
	move.w vLineDrawBLTCON1(pc),_custom+bltcon1.l
    ; BLTADAT
	move.w #$8000,_custom+bltadat.l
    ; BLTBDAT
	move.w #$FFFF,_custom+bltbdat.l
	move.w vLineDrawErrorStepA(pc),_custom+bltamod.l
	move.w vLineDrawErrorStepB(pc),_custom+bltbmod.l
	move.w vLineDrawBLTCMOD(pc),_custom+bltcmod.l
	move.w vLineDrawBLTDMOD(pc),_custom+bltdmod.l
	move.w vLineDrawInitialError(pc),_custom+bltapt+$02.l	; blitter_source pointer
	lea.l BasePlaneBuffer.l,a0
	adda.l gDrawBankByteOffset.l,a0
	adda.w vLineDrawCDScreenOffset(pc),a0
    ; BLTCPTH
	move.l a0,_custom+bltcpt.l	; blitter_source pointer
    ; BLTDPTH
	move.l a0,_custom+bltdpt.l	; blitter_destination pointer
	move.w vLineDrawBLTSIZE(pc),_custom+bltsize.l
	bsr.w WaitBlitterReady
	move.w vLineDrawBLTCON0(pc),_custom+bltcon0.l
	move.w vLineDrawBLTCON1(pc),_custom+bltcon1.l
	move.w #$8000,_custom+bltadat.l
	move.w #$FFFF,_custom+bltbdat.l
	move.w vLineDrawErrorStepA(pc),_custom+bltamod.l
	move.w vLineDrawErrorStepB(pc),_custom+bltbmod.l
	move.w vLineDrawBLTCMOD(pc),_custom+bltcmod.l
	move.w vLineDrawBLTDMOD(pc),_custom+bltdmod.l
	move.w vLineDrawInitialError(pc),_custom+bltapt+$02.l	; blitter_source pointer
	adda.w #$2000,a0
	move.l a0,_custom+bltcpt.l	; blitter_source pointer
	move.l a0,_custom+bltdpt.l	; blitter_destination pointer
	move.w vLineDrawBLTSIZE(pc),_custom+bltsize.l
	bsr.w WaitBlitterReady
	move.w vLineDrawBLTCON0(pc),_custom+bltcon0.l
	move.w vLineDrawBLTCON1(pc),_custom+bltcon1.l
	move.w #$8000,_custom+bltadat.l
	move.w #$FFFF,_custom+bltbdat.l
	move.w vLineDrawErrorStepA(pc),_custom+bltamod.l
	move.w vLineDrawErrorStepB(pc),_custom+bltbmod.l
	move.w vLineDrawBLTCMOD(pc),_custom+bltcmod.l
	move.w vLineDrawBLTDMOD(pc),_custom+bltdmod.l
	move.w vLineDrawInitialError(pc),_custom+bltapt+$02.l	; blitter_source pointer
	adda.w #$2000,a0
	move.l a0,_custom+bltcpt.l	; blitter_source pointer
	move.l a0,_custom+bltdpt.l	; blitter_destination pointer
	move.w vLineDrawBLTSIZE(pc),_custom+bltsize.l
	bsr.w WaitBlitterReady
	move.w vLineDrawBLTCON0(pc),_custom+bltcon0.l
	move.w vLineDrawBLTCON1(pc),_custom+bltcon1.l
	move.w #$8000,_custom+bltadat.l
	move.w #$FFFF,_custom+bltbdat.l
	move.w vLineDrawErrorStepA(pc),_custom+bltamod.l
	move.w vLineDrawErrorStepB(pc),_custom+bltbmod.l
	move.w vLineDrawBLTCMOD(pc),_custom+bltcmod.l
	move.w vLineDrawBLTDMOD(pc),_custom+bltdmod.l
	move.w vLineDrawInitialError(pc),_custom+bltapt+$02.l	; blitter_source pointer
	adda.w #$2000,a0
	move.l a0,_custom+bltcpt.l	; blitter_source pointer
	move.l a0,_custom+bltdpt.l	; blitter_destination pointer
	move.w vLineDrawBLTSIZE(pc),_custom+bltsize.l
	rts
    ; Nine cached WORD parameters, written by the line setup and read by four plane submissions. The BLTAPT low WORD holds the line error accumulator, not a source-data pointer.
vLineDrawBLTCON0:
	dc.w $0000
vLineDrawBLTCON1:
	dc.w $0000
vLineDrawBLTSIZE:
	dc.w $0000
vLineDrawErrorStepA:
	dc.w $0000
vLineDrawErrorStepB:
	dc.w $0000
vLineDrawBLTCMOD:
	dc.w $0000
vLineDrawBLTDMOD:
	dc.w $0000
vLineDrawInitialError:
	dc.w $0000
vLineDrawCDScreenOffset:
	dc.w $0000
WaitBlitterReady:
	btst.b #DMAB_BLTDONE,_custom+dmaconr.l
	bne.b WaitBlitterReady
	rts
    ; DEAD CODE
DeadFunc_19418:
	moveq.l #0,d7
	lea.l tDeadFunc_19418.l,a0
.loop:
	move.w d7,d0
	lsr.w #1,d0
	andi.w #65528,d0
	btst #3,d7
	beq.b .skip
	addq.w #1,d0
.skip:
	move.w d0,(a0)+
	addq.w #1,d7
	cmp.w #$140,d7
	bne.b .loop
	rts
tDeadFunc_19418:
	dcb.w $141,$0000
    ; D0w,D1w,D2w,D3w
    ; Screen WORD endpoints are D0/D1 and D2/D3. Inclusive bounds are X=26..295, Y=16..127. This helper returns D7=0 on acceptance and -1 on common-side rejection; it may exchange the endpoints.
ClipLine_X26To295_Y16To127:
	moveq.l #0,d7
	moveq.l #0,d6
	cmp.w #$10,d1
	bge.b .check_y0_high
    ; D1<16
	bset #3,d7
.check_y0_high:
	cmp.w #$7F,d1
	ble.b .check_x0_high
    ; D1>127
	bset #2,d7
.check_x0_high:
	cmp.w #$127,d0
	ble.b .check_x0_low
    ; D0>295
	bset #1,d7
.check_x0_low:
	cmp.w #$1A,d0
	bge.b .check_y1_low
    ; D0<26
	bset #0,d7
.check_y1_low:
	cmp.w #$10,d3
	bge.b .check_y1_high
    ; D3<16
	bset #3,d6
.check_y1_high:
	cmp.w #$7F,d3
	ble.b .check_x1_high
    ; D3>127
	bset #2,d6
.check_x1_high:
	cmp.w #$127,d2
	ble.b .check_x1_low
    ; D2>295
	bset #1,d6
.check_x1_low:
	cmp.w #$1A,d2
	bge.b .check_bounds
    ; D2<26
	bset #0,d6
    ; D7/D6 encode endpoint sides: bit 0 left, 1 right, 2 below Y=127, 3 above Y=16. A shared bit rejects the line; otherwise an outside endpoint is clipped and the outcodes are recomputed.
.check_bounds:
	move.w d7,d5
	and.w d6,d5
	bne.b .out_of_bounds
	move.w d7,d5
	or.w d6,d5
	bne.b .clipping_required
	moveq.l #0,d7
	rts
.out_of_bounds:
	moveq.l #-1,d7
	rts
    ; If endpoint 0 is inside, exchange endpoint pairs and outcodes to clip the outside endpoint. Signed WORD differences and MULS/DIVS preserve original intersection rounding and preconditions.
.clipping_required:
	tst.w d7
	bne.b .clip_x0_low
	exg d7,d6
	exg d0,d2
	exg d1,d3
    ; x0 low
.clip_x0_low:
	btst #0,d7
	beq.w .clip_x0_high
	moveq.l #26,d4
	sub.w d0,d4
	move.w d3,d5
	sub.w d1,d5
	beq.b .retry_low_x0
	muls.w d5,d4
	move.w d2,d5
	sub.w d0,d5
	divs.w d5,d4
	add.w d4,d1
.retry_low_x0:
	moveq.l #26,d0
	bra.w ClipLine_X26To295_Y16To127
    ; x0 high
.clip_x0_high:
	btst #1,d7
	beq.b .clip_y0_high
	move.w #$127,d4
	sub.w d0,d4
	move.w d3,d5
	sub.w d1,d5
	beq.b .retry_high_x0
	muls.w d5,d4
	move.w d2,d5
	sub.w d0,d5
	divs.w d5,d4
	add.w d4,d1
.retry_high_x0:
	move.w #$127,d0
	bra.w ClipLine_X26To295_Y16To127
    ; y0 high
.clip_y0_high:
	btst #2,d7
	beq.b .clip_y0_low
	moveq.l #127,d4
	sub.w d1,d4
	move.w d2,d5
	sub.w d0,d5
	beq.b .retry_high_y0
	muls.w d5,d4
	move.w d3,d5
	sub.w d1,d5
	divs.w d5,d4
	add.w d4,d0
.retry_high_y0:
	moveq.l #127,d1
	bra.w ClipLine_X26To295_Y16To127
.clip_y0_low:
	moveq.l #16,d4
	sub.w d1,d4
	move.w d2,d5
	sub.w d0,d5
	beq.w .retry_low_y0
	muls.w d5,d4
	move.w d3,d5
	sub.w d1,d5
	divs.w d5,d4
	add.w d4,d0
.retry_low_y0:
	moveq.l #16,d1
	bra.w ClipLine_X26To295_Y16To127
    ; y
    ; Accepts signed WORD X=26..294, Y=16..126. There A0 is the bitmap byte, D0.w=X>>3 and D1.w=(~X)&7; sets four plane bits. Rejection does not establish those outputs.
Draw4BitplanePixel:
	cmp.w #$7F,d1
	bge.b .skip
	cmp.w #$F,d1
	ble.b .skip
    ; x
	cmp.w #$127,d0
	bge.b .skip
	cmp.w #$19,d0
	ble.b .skip
	lea.l BasePlaneBuffer.l,a0
    ; With a preserved draw offset of 0 or 8000, the clipped pixel BYTE stores stay in the four bitmap planes and exclude count, view, backup and saved offset. Unknown bank writes remain open.
	adda.l gDrawBankByteOffset.l,a0
    ; y line offset
	mulu.w #$28,d1
	adda.w d1,a0
	move.w d0,d1
    ; x byte offset
	lsr.w #3,d0
	adda.w d0,a0
	not.w d1
    ; x final bit offset
	andi.w #7,d1
    ; Four explicit BYTE read/modify/write destinations follow clipped X=26..294 and Y=16..126. This is a software store envelope, not active-plane ownership, presentation or IRQ/DMA evidence.
	bset.b d1,(a0)
	bset.b d1,$2000(a0)
	bset.b d1,$4000(a0)
	bset.b d1,$6000(a0)
.skip:
	rts
DrawMaskedPlanePixel_Mask2:
	cmp.w #$80,d1
	bge.b .exit
	cmp.w #$F,d1
	ble.b .exit
	cmp.w #$127,d0
	bge.b .exit
	cmp.w #$1A,d0
	ble.b .exit
	move.b bitsPlanePixelMask2.l,bitsPlanePixelMask.l
	jmp DrawMaskedPlanePixel.l
.exit:
	rts
bitsPlanePixelMask2:
	dc.w $0000
    ; Consumes D0+1 face records: WORD style index, vertex count, then WORD byte offsets into projected records. Collects screen XY and calls the rasterizer; records advance by 4+2*count bytes.
DrawProjectedPolygonFaces:
	lea.l gProjectionInputX.l,a1
	lea.l polygonScreenVertexPairs.l,a2
	moveq.l #0,d2
    ; Three offset WORDs supply the winding test before count-driven collection. Offsets address ten-byte projected rows; variable face records retain 4+2*count length and shared/interior views.
.next_face:
	move.w $4(a0,d2.w),d1
	move.w $6(a0,d2.w),d3
	move.w $8(a0,d2.w),d4
	move.w $6(a1,d3.w),d5
	sub.w $6(a1,d1.w),d5
	move.w d5,d6
	move.w $6(a1,d4.w),d7
	sub.w $6(a1,d3.w),d7
	move.w $8(a1,d3.w),d5
	sub.w $8(a1,d1.w),d5
	muls.w d5,d7
	move.w $8(a1,d4.w),d5
	sub.w $8(a1,d3.w),d5
	muls.w d5,d6
	sub.w d6,d7
	bmi.b .skip_face
	move.w $2(a0,d2.w),d5
	move.w d5,d7
	moveq.l #0,d6
	move.w d2,d4
	addq.w #4,d4
	move.w $0(a0,d4.w),d1
	move.w d2,-(a7)
	move.w $0(a0,d2.w),d2
	add.w d2,d2
	move.w polygonStyleWords(pc,d2.w),gPolygonStyleWord.l
	move.w (a7)+,d2
.collect_vertex:
	move.w $0(a0,d4.w),d1
    ; Copy projected screen XY into four-byte raster points. The six-point source view covers the pinned model faces; it does not establish a global vertex-count limit or callback input contract.
	move.w $6(a1,d1.w),$0(a2,d6.w)
	move.w $8(a1,d1.w),$2(a2,d6.w)
	addq.w #4,d6
	addq.w #2,d4
	subq.w #1,d5
	bne.b .collect_vertex
	movem.l d0-d7/a0-a6,-(a7)
	jsr RasterizeProjectedPolygon.l
	movem.l (a7)+,d0-d7/a0-a6
.skip_face:
	move.w $2(a0,d2.w),d7
	add.w d7,d7
	addq.w #4,d7
	add.w d7,d2
	dbf.w d0,.next_face
	rts
