DrawFiveRowGlyphRun:
	move.w d5,d0
	andi.w #3,d0
	asr.w #2,d5
	add.w d5,d5
	mulu.w #$28,d4
	lea.l BasePlaneBuffer.l,a1
	adda.l gDrawBankByteOffset.l,a1
	adda.w d4,a1
	adda.w d5,a1
	cmp.w #$3,d0
	beq.w .phase3
	cmp.w #$2,d0
	beq.w .phase2
	cmp.w #$1,d0
	beq.b .phase1
.phase0:
	lea.l dataGraphics380_1.l,a0
	lea.l (a1),a2
	moveq.l #4,d2
	move.w (a5)+,d0
	add.w d0,d0
.phase0_row:
	move.w (a2),d1
	or.w $0(a0,d0.w),d1
	move.w d1,(a2)
	move.w $2000(a2),d1
	or.w $0(a0,d0.w),d1
	move.w d1,$2000(a2)
	move.w $4000(a2),d1
	or.w $0(a0,d0.w),d1
	move.w d1,$4000(a2)
	move.w $6000(a2),d1
	or.w $0(a0,d0.w),d1
	move.w d1,$6000(a2)
	lea.l $0028(a2),a2
	lea.l $0002(a0),a0
	dbf.w d2,.phase0_row
	subq.w #1,d6
	beq.w .done
.phase1:
	lea.l dataGraphics380_2.l,a0
