    ; D0 is a byte offset into 20-byte object records. Mark +12 as F0F0 first; the existing mode gate can then skip mission, loss, rank and sound bookkeeping. Preserve all registers.
MarkObjectForRemovalAndBookkeep:
	movem.l d0-d7/a0-a6,-(a7)
	lea.l objectStateStorage.l,a0
	adda.w d0,a0
	move.w #$F0F0,$000C(a0)
	st.b projectedBurstControl_activeWord.l
	tst.w abs_0_0002CEAE.l
	bne.w .restore_return
	move.w $000E(a0),d1
	cmp.w #$9,d1
	bne.b .check_patrol_category
	addq.w #1,gConvoyShipsLost.l
.check_patrol_category:
	cmp.w #$7,d1
	bne.b .check_model_flags
    ; Increment the shared WORD only for the current category 7 at removal-helper entry. There is no patrol-active or mission-system test here; the earlier mode gate still applies.
	addq.w #1,gPatrolCategory7RemovalCount.l
    ; Removal bookkeeping clears search-enabled when the model identity is 26A4A, independently of recovery-recorded. The earlier mode gate can skip this bookkeeping.
.check_model_flags:
