	bne.b .check_satellite_model
	clr.w gLostShipSearchEnabled.l
    ; Model identity 23FB8 sets the satellite destruction record in shared removal bookkeeping. This test has no satellite-enable, mission-type, category or current-system guard.
.check_satellite_model:
	cmp.l #$23FB8,d2
	bne.b .check_pirate_base
	st.b gSatelliteDestructionRecorded.l
