    ; Laser upgrade debits the selected base price first; insufficient funds restores it. Success credits (old base >> 1)+(old base >> 2), then stores selected index+1 as grade.
HandleLaserUpgrade:
	moveq.l #4,d6
	sub.w d7,d6
	add.w d6,d6
	add.w d6,d6
	lea.l laserBasePrices(pc),a0
	adda.w d6,a0
	move.l (a0),d0
	lea.l tradeAccountBase.l,a0
	sub.l d0,$0034(a0)
	bpl.b .replace
	add.l d0,$0034(a0)
	lea.l textReplaceLasersFail(pc),a0
