	bsr.w DisplayText1
	move.w gLaserGrade.l,d0
	subq.w #1,d0
	add.w d0,d0
	add.w d0,d0
	lea.l laserBasePrices(pc),a0
	adda.w d0,a0
	move.l (a0),d0
	lsr.l #1,d0
	move.l d0,d1
	lsr.l #1,d0
	add.l d0,d1
	lea.l tradeAccountBase.l,a0
	add.l d1,$0034(a0)
	lsr.w #2,d6
	addq.w #1,d6
	move.w d6,gLaserGrade.l
