    ; Displays the allocation error, waits for flagKeyDownEvent, restores the saved debit to credits, and returns. Shared by duplicate-system rejection paths.
RefundRejectedSystemPurchase:
	bsr.w fClsCommand
	lea.l systemAllocationErrorMenu(pc),a6
	bsr.w DrawTextLines
	clr.w flagKeyDownEvent.l
.wait_acknowledgement:
	tst.w flagKeyDownEvent.l
	beq.b .wait_acknowledgement
	clr.w flagKeyDownEvent.l
	lea.l tradeAccountBase.l,a0
	move.l $0034(a0),d0
	add.l gSystemPurchaseDebit(pc),d0
	move.l d0,$0034(a0)
	rts
