	jsr DrawPlaneWordOccupancyGrid.l
	lea.l bufferKeyboardState.l,a0
	tst.w $0020(a0)
	bne.b .check_pod
	clr.w flagKeyDownEvent.l
	bra.w ShowCentralStoresMenu
.check_pod:
	tst.w $000E(a0)
	bne.w .check_tank
	moveq.l #1,d2
	moveq.l #6,d0
	move.l #$3E8,d1
	bra.w PrepareGeneralStoreOrder
