    ; General Stores quote saves kind, maximum units and unit price as WORDs. Kind 0=fuel, 1=sand, 2=Gauss scrap, 3=repair droids, 5=tank extension, 6=escape pod.
PrepareGeneralStoreOrder:
	move.w d0,gGeneralOrderKind.l
	move.w d2,gGeneralOrderMaxUnits.l
	move.w d1,gGeneralOrderUnitPrice.l
	bsr.w fClsCommand
	lea.l generalOrderPromptMenu.l,a6
	bsr.w DrawTextLines
	moveq.l #25,d0
	moveq.l #63,d1
	bsr.w MoveCursor
	move.w gGeneralOrderUnitPrice.l,d2
	bsr.w DrawBase10Number
	moveq.l #25,d0
	moveq.l #72,d1
	bsr.w MoveCursor
	move.w gGeneralOrderMaxUnits.l,d2
	bsr.w DrawBase10Number
	move.w #$4,TextXCoord.l
	move.w #$63,TextYCoord.l
	moveq.l #4,d0
	moveq.l #99,d1
	bsr.w MoveCursor
	jsr DrawPlaneWordOccupancyGrid.l
	bsr.w ReadEDIInputLine
	lea.l bufferEDIInput.l,a0
	moveq.l #0,d1
	move.b (a0),d0
	cmp.b #$71,d0
	bne.b ParseGeneralOrderQuantity
	clr.w flagKeyDownEvent.l
	bra.w ShowCentralStoresMenu
    ; Normal decimal order path: accumulates with MULU.W 10 and low-nibble addition until space, then checks the maximum. This is not a claim of complete input validation.
ParseGeneralOrderQuantity:
	move.b (a0)+,d0
	cmp.b #$20,d0
	beq.b CheckGeneralOrderQuantity
	mulu.w #$A,d1
	andi.w #15,d0
	add.w d0,d1
	bra.b ParseGeneralOrderQuantity
CheckGeneralOrderQuantity:
	cmp.w gGeneralOrderMaxUnits.l,d1
	ble.b CommitGeneralStoreOrder
	lea.l textGeneralOrderExceedsMaximum(pc),a0
	bsr.w DisplayText1
	clr.w flagKeyDownEvent.l
.wait_ack:
	jsr DrawPlaneWordOccupancyGrid.l
	tst.w flagKeyDownEvent.l
	beq.b .wait_ack
	clr.w flagKeyDownEvent.l
	bra.w ShowCentralStoresMenu
    ; Preserve order: signed WORD quantity*unit price, compare credits, debit, then dispatch the equipment update. Fuel adds the accepted quantity directly.
CommitGeneralStoreOrder:
	move.w d1,d4
	muls.w gGeneralOrderUnitPrice.l,d1
	lea.l tradeAccountBase.l,a0
	cmp.l $0034(a0),d1
	bgt.w ShowGeneralOrderInsufficientFunds
	sub.l d1,$0034(a0)
	move.w gGeneralOrderKind.l,d0
	bne.b DispatchGeneralEquipmentOrder
	add.w d4,playerVarFuel.l
	clr.w flagKeyDownEvent.l
	bra.w ShowCentralStoresMenu
DispatchGeneralEquipmentOrder:
	cmp.w #$6,d0
	bne.b CheckGeneralSandOrder
	cmpi.w #3,gEscapePodState.l
	beq.w InstallPurchasedEscapePod
	cmpi.w #4,gEscapePodState.l
	bne.w ShowEscapePodAlreadyFitted
    ; Original pod order accepts states 3 or 4, writes state 2 and clears the next WORD. Other states use the already-fitted message; broader state meanings remain unproved.
InstallPurchasedEscapePod:
	move.w #$2,gEscapePodState.l
	clr.w abs_0_0004E374.l
	clr.w flagKeyDownEvent.l
	bra.w ShowCentralStoresMenu
ShowEscapePodAlreadyFitted:
	lea.l textEscapePodAlreadyFitted(pc),a0
	bsr.w DisplayText1
	clr.w flagKeyDownEvent.l
.wait_ack:
	jsr DrawPlaneWordOccupancyGrid.l
	tst.w flagKeyDownEvent.l
	beq.b .wait_ack
	clr.w flagKeyDownEvent.l
	bra.w ShowGeneralStoresMenu
textEscapePodAlreadyFitted:
	dc.w $0004
	dc.w $0063
	dc.b "Escape Pod already fitted      ",$00
CheckGeneralSandOrder:
	cmp.w #$1,d0
	bne.b CheckGeneralGaussScrapOrder
    ; General sand refill writes 100 to this gate WORD at $4E2E0. Recognized type-4 activation consumes $4E2DE instead; do not conflate them while installation remains raw.
	move.w #$64,gSandRefillGateWord.l
	clr.w flagKeyDownEvent.l
	bra.w ShowCentralStoresMenu
CheckGeneralGaussScrapOrder:
	cmp.w #$2,d0
	bne.b CheckGeneralDroidOrder
	move.w #$64,gGaussGunRemainingUnits.l
	clr.w flagKeyDownEvent.l
	bra.w ShowCentralStoresMenu
CheckGeneralDroidOrder:
	cmp.w #$3,d0
	bne.b ApplyGeneralTankExtension
    ; Repair-droid order adds the accepted quantity to total and available counts. Assignment consumes available droids; completion or return restores availability. Distinct from Weaponry Drones.
	add.w d4,gRepairDroidTotal.l
	add.w d4,gAvailableRepairDroids.l
	clr.w flagKeyDownEvent.l
	bra.w ShowCentralStoresMenu
    ; Tank extension adds accepted units*50 to capacity. The quote maximum is (400-current tankage)/50 and the advertised unit price is 300 credits.
ApplyGeneralTankExtension:
	mulu.w #$32,d4
	add.w d4,playerVarTankage.l
	clr.w flagKeyDownEvent.l
	bra.w ShowCentralStoresMenu
ShowGeneralOrderInsufficientFunds:
	lea.l textGeneralOrderInsufficientFunds(pc),a0
	bsr.w DisplayText1
	clr.w flagKeyDownEvent.l
.wait_ack:
	jsr DrawPlaneWordOccupancyGrid.l
	tst.w flagKeyDownEvent.l
	beq.b .wait_ack
	clr.w flagKeyDownEvent.l
	bra.w ShowCentralStoresMenu
