    ; Read/display the first A6 LONG pointer unconditionally, then test the next LONG. Zero stops without consumption. The normal path needs a nonempty list of valid display-record addresses.
DrawTextLines:
	movea.l (a6)+,a0
	bsr.w DisplayText1
	tst.l (a6)
	bne.b DrawTextLines
	rts
    ; Reads WORD x,y,account-byte-offset records until the next x is zero. Offset $34 draws a LONG; other values draw a WORD relative to tradeAccountBase.
DrawMarketAccountValueRecords:
	move.w (a6)+,d0
	move.w (a6)+,d1
	bsr.w MoveCursor
	move.w (a6)+,d0
	cmp.w #$34,d0
	beq.w abs_0_000347DC
	lea.l tradeAccountBase.l,a5
	move.w $0(a5,d0.w),d2
	bsr.w DrawBase10Number
	bra.b abs_0_000347EA
