	clr.w d1
.sell_digit:
	move.b (a0)+,d0
	beq.w MarketCompleteSell
	cmp.b #$20,d0
	beq.w MarketCompleteSell
	mulu.w #$A,d1
	cmp.b #$30,d0
	blt.b MarketTransactionReturn
	cmp.b #$39,d0
	bgt.b MarketTransactionReturn
	subi.b #48,d0
	andi.w #255,d0
	add.w d0,d1
	bra.b .sell_digit
MarketCompleteSell:
	lea.l cargoQuantityStorage.l,a1
	adda.w gMarketSelectionOffset(pc),a1
	subq.w #4,a1
	cmp.w (a1),d1
	bgt.b MarketTransactionReturn
	sub.w d1,(a1)
	lea.l standardMarketStock.l,a0
	adda.w gMarketSelectionOffset(pc),a0
	subq.w #4,a0
	add.w d1,(a0)
	lea.l tradeAccountBase.l,a0
	adda.w gMarketSelectionOffset(pc),a0
	subq.w #4,a0
	move.w (a0),d2
	mulu.w d1,d2
	lea.l tradeAccountBase.l,a0
	add.l d2,$0034(a0)
	add.w d1,$0032(a0)
MarketTransactionReturn:
	rts
    ; Normal market buy. Parse and quantity checks precede pricing; credit debit precedes capacity. Preserve original WORD/LONG arithmetic and the distinct GalNet settlement path.
MarketBeginBuy:
	lea.l standardMarketStock.l,a1
	adda.w gMarketSelectionOffset(pc),a1
	subq.w #4,a1
	tst.w (a1)
	beq.b MarketTransactionReturn
	lea.l textHowManyToBuy(pc),a0
	bsr.w DisplayText1
	clr.w flagKeyDownEvent.l
	move.w #$6C,TextYCoord.l
	move.w #$4,TextXCoord.l
	bsr.w ReadEDIInputLine
	lea.l bufferEDIInput.l,a0
	clr.w d1
.buy_digit:
	move.b (a0)+,d0
	beq.w MarketBuyQuantityReady
	cmp.b #$20,d0
	beq.w MarketBuyQuantityReady
	mulu.w #$A,d1
	cmp.b #$30,d0
	blt.b MarketTransactionReturn
	cmp.b #$39,d0
	bgt.b MarketTransactionReturn
	subi.b #48,d0
	andi.w #255,d0
	add.w d0,d1
	bra.b .buy_digit
MarketBuyQuantityReady:
	lea.l standardMarketStock.l,a1
	adda.w gMarketSelectionOffset(pc),a1
	subq.w #4,a1
	cmp.w (a1),d1
	bgt.b MarketTransactionReturn
	lea.l tradeAccountBase.l,a0
	adda.w gMarketSelectionOffset(pc),a0
	subq.w #4,a0
	move.w (a0),d2
	mulu.w d1,d2
	move.l d2,d3
	cmp.l #$64,d3
	ble.w MarketBuyMinimumFee
	divu.w #$64,d3
	andi.l #65535,d3
	add.l d3,d2
	bra.w MarketDebitBuyCost
    ; Minimum fee uses ADDQ.W #1,D2. Larger normal costs use DIVU.W #100 and add its WORD quotient. This annotation does not widen either operation.
MarketBuyMinimumFee:
	addq.w #1,d2
    ; Debits the total LONG before capacity is tested. A negative balance restores the same debit and returns; the capacity-failure branch occurs later.
MarketDebitBuyCost:
	lea.l tradeAccountBase.l,a0
	sub.l d2,$0034(a0)
	bpl.b MarketCheckBuyCapacity
	add.l d2,$0034(a0)
	bra.b MarketBuyReturn
MarketCheckBuyCapacity:
	move.w $0032(a0),d2
	cmp.w d2,d1
	bgt.w MarketBuyCapacityFailure
	sub.w d1,(a1)
	sub.w d1,$0032(a0)
	lea.l cargoQuantityStorage.l,a0
	adda.w gMarketSelectionOffset(pc),a0
	subq.w #4,a0
	add.w d1,(a0)
MarketBuyReturn:
	rts
    ; Static path: sound 6 then return, with no visible refund of the preceding debit in this block. No runtime outcome, complete alias closure or gameplay repair is claimed.
MarketBuyCapacityFailure:
	movem.l d0-d7/a0-a6,-(a7)
	moveq.l #6,d0
	jsr PlaySoundN.l
	movem.l (a7)+,d0-d7/a0-a6
	rts
