pTextBank1Cursor:
	dc.l $00000000
	dc.w $0008
	dc.w $001B
    ; Clear both text regions with two selector toggles, restore the incoming selector and reset the cursor to (4,18). Ships restores its saved selector only after this call.
fClsCommand:
	bsr.b .clear_buffer_region
	eori.l #32768,gDrawBankByteOffset.l
	bsr.b .clear_buffer_region
	eori.l #32768,gDrawBankByteOffset.l
	move.w #$4,TextXCoord.l
	move.w #$12,TextYCoord.l
	moveq.l #4,d0
	moveq.l #18,d1
	bsr.w MoveCursor
	rts
    ; Per bank, rows 15..127 fill pixels 25..295 with bitplane pattern $A, preserving outside edge bits. This text-region fill differs from the view clear zero pattern.
.clear_buffer_region:
	lea.l BasePlaneBuffer.l,a0
	adda.l gDrawBankByteOffset.l,a0
	lea.l $025A(a0),a0
	move.l #$FF80,d0
	move.l #$7F,d6
	move.l #$FF,d1
	move.l #$FF00,d7
	moveq.l #112,d5
.clear_row:
	and.w d0,(a0)
	and.w d0,$2000(a0)
	and.w d0,$4000(a0)
	and.w d0,$6000(a0)
	or.w d6,$6000(a0)
	or.w d6,$2000(a0)
	addq.w #2,a0
	moveq.l #7,d3
.clear_interior_longs:
	clr.l $4000(a0)
	move.l #$FFFFFFFF,$2000(a0)
	move.l #$FFFFFFFF,$6000(a0)
	clr.l (a0)+
	dbf.w d3,.clear_interior_longs
	and.w d1,(a0)
	and.w d1,$2000(a0)
	and.w d1,$4000(a0)
	and.w d1,$6000(a0)
	or.w d7,$2000(a0)
	or.w d7,$6000(a0)
	addq.w #6,a0
	dbf.w d5,.clear_row
	rts
    ; Select input-only mode, then share the line editor with the SCP instruction reader. Parsing is conditional on the Return finalization path and a nonempty count.
ReadEDIInputLine:
	move.w #$FFFF,gEDIInputOnlyMode.l
	bra.b ReadSharedTextInputLine
ReadAndParseSCPInstruction:
	clr.w gEDIInputOnlyMode.l
    ; Reset length and the write cursor, then fill exactly 128 input bytes with spaces. The following two original bytes stay outside this initialized owner.
ReadSharedTextInputLine:
	clr.w gEDIInputLength.l
	move.b #$20,d0
	lea.l bufferEDIInput(pc),a0
	move.l a0,pEDIInputWriteCursor.l
	moveq.l #127,d1
.fill_input_spaces:
	move.b d0,(a0)+
	dbf.w d1,.fill_input_spaces
    ; Toggle space/underscore per poll, saving XY and both bank cursors around the glyph draw. Restoring these fields does not undo pixel writes or possible scrolling; no blink period is implied.
.poll_cursor_and_key:
	jsr DrawPlaneWordOccupancyGrid.l
	move.b gEDIInputCursorGlyph(pc),d0
	subi.b #32,d0
	eori.b #63,d0
	addi.b #32,d0
	move.b d0,gEDIInputCursorGlyph.l
	move.l pTextBank0Cursor.l,-(a7)
	move.l pTextBank1Cursor.l,-(a7)
	move.l TextXCoord.l,-(a7)
	move.b gEDIInputCursorGlyph.l,d0
	bsr.w DrawCharacter
	move.l (a7)+,TextXCoord.l
	move.l (a7)+,pTextBank1Cursor.l
	move.l (a7)+,pTextBank0Cursor.l
	tst.w flagKeyDownEvent.l
	beq.b .poll_cursor_and_key
	clr.w flagKeyDownEvent.l
	lea.l bufferKeyboardState.l,a0
	tst.w $0038(a0)
	bne.w .check_auxiliary_erase_word
    ; Append space/NUL through local A0 without updating the stored write cursor. Then display the live XY/glyph prefix and preserve the original line-advance call order.
	movea.l pEDIInputWriteCursor(pc),a0
	move.b #$20,(a0)+
	move.b #$0,(a0)+
	move.b #$20,gEDIInputCursorGlyph.l
	lea.l TextXCoord(pc),a0
	bsr.w DisplayText1
	move.w #$4,TextXCoord.l
	addi.w #9,TextYCoord.l
	cmpi.w #109,TextYCoord.l
	bgt.b .finish_at_bottom
	movem.l d0-d7/a0-a6,-(a7)
	jsr AdvanceTerminalTextLine.l
	movem.l (a7)+,d0-d7/a0-a6
	move.w TextXCoord(pc),d0
	move.w TextYCoord(pc),d1
	bsr.w MoveCursor
	bra.w .finalize_input_flags
.finish_at_bottom:
	move.b #$20,gEDIInputCursorGlyph.l
	lea.l TextXCoord(pc),a0
	bsr.w DisplayText1
    ; Return finalization sets the empty flag from the count and parses only in SCP mode. The erase-at-left-boundary RTS bypasses this block; not every return finalizes a line.
.finalize_input_flags:
	move.w #$FFFF,gEDIInputEmpty.l
	tst.w gEDIInputLength.l
	beq.b .return_to_caller
	clr.w gEDIInputEmpty.l
	tst.w gEDIInputOnlyMode.l
	bne.b .return_to_caller
	movea.l pEDIInputWriteCursor(pc),a2
	move.b #$20,(a2)
	bsr.w ParseSCPInstruction
.return_to_caller:
	rts
.check_auxiliary_erase_word:
	tst.w $00A6(a0)
	bne.b .check_backspace
    ; Draw space at the current cursor, restore XY, then test the left boundary. Input bytes are not deleted here; cursor/length are adjusted for later overwrite.
.begin_erase_key:
	move.b #$20,gEDIInputCursorGlyph.l
	lea.l TextXCoord(pc),a0
	move.l (a0),-(a7)	; operand 1: PositionedTextCoordinates_x at (a0)
	move.b #$20,d0
	bsr.w DrawCharacter
	move.l (a7)+,TextXCoord.l
	cmpi.w #4,TextXCoord.l
	ble.b .return_to_caller
	subq.w #1,TextXCoord.l
	subq.w #1,gEDIInputLength.l
	bpl.b .reposition_after_erase
    ; On a negative count, reset length and the stored write cursor. Keep the original branch back to polling; no extra cursor reposition is inserted.
	clr.w gEDIInputLength.l
	move.l #bufferEDIInput,pEDIInputWriteCursor.l
	bra.w .poll_cursor_and_key
.reposition_after_erase:
	move.w TextXCoord.l,d0
	move.w TextYCoord.l,d1
	bsr.w MoveCursor
	subq.l #1,pEDIInputWriteCursor.l
	bra.w .poll_cursor_and_key
.check_backspace:
	tst.w $001C(a0)
	beq.b .begin_erase_key
	movea.l pEDIInputWriteCursor.l,a1
    ; Scan 79 logical WORD states in descending even-offset order ($9C..0). First zero wins; use that same offset in the existing BYTE character table.
	move.w #$9C,d0
.scan_active_key:
	tst.w $0(a0,d0.w)
	beq.b .append_character
	subq.w #2,d0
	bpl.b .scan_active_key
	bra.w .poll_cursor_and_key
    ; CMP.W #30/BEQ precedes the byte store. Advance write cursor and length, then draw. This input-length rule is independent of the display wrap threshold.
.append_character:
	cmpi.w #30,gEDIInputLength.l
	beq.w .poll_cursor_and_key
	move.b tableRawKeyCharacters(pc,d0.w),d0
	move.b d0,(a1)+
	move.l a1,pEDIInputWriteCursor.l
	addq.w #1,gEDIInputLength.l
	bsr.w DrawCharacter
	bra.w .poll_cursor_and_key
tableRawKeyCharacters:
	dc.b $20,$20,$20,$20,$31,$31,$32,$32,$33,$33,$34,$34,$35,$35,$36,$36
	dc.b $37,$37,$38,$38,$39,$39,$30,$30,$2D,$2D,$3D,$3D,$20,$20,$20,$20
	dc.b $71,$71,$77,$77,$65,$65,$72,$72,$74,$74,$79,$79,$75,$75,$69,$69
	dc.b $6F,$6F,$70,$70,$5B,$5B,$5D,$5D,$00,$00,$00,$00,$61,$61,$73,$73
