	dc.b $60,$60,$20,$20,$20,$20,$23,$23,$7A,$7A,$78,$78,$63,$63,$76,$76
	dc.b $62,$62,$6E,$6E,$6D,$6D,$2C,$2C,$2E,$2E,$2F,$2F
	dcb.b $27,$20
	dcb.b $A,$2D
	dc.b $00
gEDIInputOnlyMode:
	dc.w $0000
gEDIInputEmpty:
	dc.w $0000
gEDIInputLength:
	dc.w $000A,$0000,$0000,$0000
bufferEDIInput:
	dc.b $00	; opaque_data
abs_0_00036933:
	dc.b $00
abs_0_00036934:
	dc.b $00
abs_0_00036935:
	dc.b $00
abs_0_00036936:
	dcb.b $7E,$00
    ; Mutable next input-byte address: reset to the buffer, advanced on append and reduced on normal erase. Mapping its initial value does not establish target closure or constness.
pEDIInputWriteCursor:
	dc.l bufferEDIInput	; next_byte
gSCPParsedHandler:
	dc.l $00000000	; implementation
gSCPParsedOperand1:
	dc.l $00000000	; operand1
gSCPParsedOperand2:
	dc.l $00000000	; operand2
    ; Clear all three staged LONGs before testing input length. A match can later set the handler before operand parsing finishes; this is mutable staging, not a committed program record.
ParseSCPInstruction:
	clr.l gSCPParsedHandler.l
	clr.l gSCPParsedOperand1.l
	clr.l gSCPParsedOperand2.l
	tst.w gEDIInputLength.l
	bne.b .begin_match
	rts
.begin_match:
	lea.l bufferEDIInput.l,a0
	lea.l tableSCPParserKeywords.l,a1
    ; Restart both WORD indices for each candidate. Compare source bytes with the fixed keyword until that keyword NUL; preserve the original input and delimiter behavior.
.next_keyword:
	clr.w d0
	clr.w d2
.compare_keyword_byte:
	move.b $0(a1,d0.w),d1
	beq.b .stage_handler
	cmp.b $0(a0,d2.w),d1
	bne.b .advance_keyword_record
	addq.w #1,d0
	addq.w #1,d2
	bra.b .compare_keyword_byte
    ; Advance by twelve bytes and test only the next leading WORD for zero. The original 31-record table and separate zero sentinel are distinct from the fourteen-byte listing descriptors.
.advance_keyword_record:
	lea.l $000C(a1),a1
	tst.w (a1)
	beq.w SCPSyntaxError
	bra.b .next_keyword
    ; Stages implementation for insert/replace. Operands may be $FFFF-tagged inline WORDs, variable cells, label/string refs or special # work-cell refs.
.stage_handler:
	move.l $0008(a1),gSCPParsedHandler.l
    ; The matched record supplied its +8 implementation LONG. Advance the input index by one here; this body does not validate a general separator or use the listing operand-count field.
	addq.w #1,d2
	cmpi.b #59,$0(a0,d2.w)
	beq.w .string_operand
	cmpi.b #108,$0(a0,d2.w)
	beq.w .label_operand
	cmpi.b #35,$0(a0,d2.w)
	beq.w .work_operand
	cmpi.b #97,$0(a0,d2.w)
	blt.b .immediate_operand
	clr.l d3
	move.b $0(a0,d2.w),d3
	subi.b #97,d3
	asl.w #2,d3
	addi.l #229100,d3
	move.l d3,gSCPParsedOperand1.l
	bra.b .second_operand
    ; After the semicolon selector, form a slot offset from low8(selector-48), shifted by five, and stage that address. This body supplies no complete digit/slot-range proof.
.string_operand:
	move.b $1(a0,d2.w),d1
	subi.b #48,d1
	andi.w #255,d1
	asl.w #5,d1
	lea.l scpStringSlots.l,a1
	adda.w d1,a1
	move.l a1,gSCPParsedOperand1.l
    ; Only the matched SETSTR implementation selects the following string copy. That write occurs during parsing; the later RUN handler performs its separate signed upper-offset check.
	move.l gSCPParsedHandler(pc),d0
	cmp.l #$36EB8,d0
	bne.w .second_operand
    ; Copy through the period test with DBF initialized to 15, then append NUL. This bounds writes to at most 17 bytes from the selected destination, not the validity of that slot address.
	lea.l $3(a0,d2.w),a2
	move.w #$F,d0
.copy_setstr_character:
	move.b (a2)+,(a1)
	move.b (a1)+,d1
