	bra.b .return_operands
.second_work_operand:
	move.l #pSCPWorkCell,gSCPParsedOperand2.l
	bra.b .return_operands
.second_immediate_operand:
	lea.l $0(a0,d2.w),a2
	bsr.w ParseSCPDecimal
	ori.l #4294901760,d0
	move.l d0,gSCPParsedOperand2.l
.return_operands:
	rts
