.label_operand:
	lea.l $1(a0,d2.w),a2
	bsr.w ParseSCPDecimal
	subq.w #1,d0
	asl.w #2,d0
	lea.l scpLabelRecordPointers.l,a2
	adda.w d0,a2
	move.l a2,gSCPParsedOperand1.l
	rts
