    ; BEEP honors skip and reads one tagged immediate WORD or variable+2 WORD. The original request goes through PlaySoundN and its separate audio-enable gate.
SCPBeep:
	tst.w gSCPConditionalSkip.l
	bne.b .return
	move.l $0008(a0),d0
	swap.w d0
	cmp.w #$FFFF,d0
	beq.b .immediate_word
	swap.w d0
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
	move.w $0002(a1),d0
	bra.b .check_index
.immediate_word:
	swap.w d0
    ; The original comparison is signed WORD <=14. Retain this upper test; it is not a proof of a complete valid index range or of audible playback.
.check_index:
	cmp.w #$E,d0
	ble.b .request_sound
	st.b gSCPErrorRaised.l
	st.b gSCPStopRequested.l
	rts
    ; Save D0-D7/A0-A6 around the original sound request and restore them before the shared return. Keep this explicit wrapper distinct from a general helper-preservation rule.
.request_sound:
	movem.l d0-d7/a0-a6,-(a7)
	jsr PlaySoundN.l
	movem.l (a7)+,d0-d7/a0-a6
.return:
	rts
    ; SETSTR tests a wrapped LONG difference from $38D66 against 320 using signed BLE. There is no lower/alignment test or string write here; only the greater branch raises error/stop.
SCPCheckStringUpperOffset:
	tst.w gSCPConditionalSkip.l
	bne.b .return
	move.l $0008(a0),d0
	subi.l #232806,d0
	cmp.l #$140,d0
	ble.w .return
	st.b gSCPErrorRaised.l
	st.b gSCPStopRequested.l
.return:
	rts
    ; RND range-checks the destination and stores a WORD at variable+2. It has no local skip test. Its two persistent WORDs and literal BYTE reads remain separate input sources.
SCPStoreRandomWord:
	move.l $0008(a0),d0
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
    ; Two BYTE reads at the original absolute-short $FFFF8209 feed one WORD via ASL.W #8. Preserve that literal; hardware identity, read availability and randomness are unproved here.
	move.b $FFFF8209.w,d0
	asl.w #8,d0
	move.b $FFFF8209.w,d0
	move.w scpRandomSubtractState.l,d1
	move.w scpRandomOutputState.l,d2
	addq.w #3,d0
	subi.w #141,d1
    ; Store old subtract-state minus 141 modulo WORD before mixing. Later ADD/ROR changes D1 only; that mixed value is not written back to this first state WORD.
	move.w d1,scpRandomSubtractState.l
	rol.w #1,d2
	add.w d0,d1
	ror.w #1,d1
	add.w d1,d2
    ; Store the new output-state WORD, then copy it to destination+2. The declaration describes four initial bytes, not alias closure, statistical quality or validity of the input read.
	move.w d2,scpRandomOutputState.l
	move.w d2,$0002(a1)
	rts
scpRandomSubtractState:	; ARRAY SCPRandomWordState[1]
	dc.w $0000
scpRandomOutputState:
	dc.w $0000
    ; RASTER sets the shared IRQ-wait BYTE and polls its WORD until clear. This body neither changes the draw-bank selector nor presents planes, and establishes no elapsed wait duration.
SCPWaitForIrq:
	st.b gIrqWaitPending.l
.wait_irq:
	tst.w gIrqWaitPending.l
	bne.b .wait_irq
