    ; LET has no entry skip test like ADD/SUB/MUL. Its ordinary destination is variable+2; the special marker instead selects the current work WORD. Preserve that distinction and original writes.
SCPLet:
	move.l $0008(a0),d0
	cmp.l #$3726A,d0
	bne.b .variable_destination
