	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a2
	move.w $0002(a2),$0002(a1)
	rts
.selected_work_source:
	movea.l pSCPWorkCell.l,a2
	move.w (a2),$0002(a1)
