	move.w $0002(a1),d2
	bra.b .read_second_operand
.first_immediate:
	swap.w d0
	move.w d0,d2
.read_second_operand:
	move.l $000C(a0),d0
	swap.w d0
	cmp.w #$FFFF,d0
	beq.b .second_immediate
	swap.w d0
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
	move.w $0002(a1),d3
	bra.b .select_word
.second_immediate:
	swap.w d0
	move.w d0,d3
.select_word:
	mulu.w #$10,d3
	add.w d2,d3
	add.w d3,d3
