	lea.l scpWorkCells.l,a1
	adda.w d3,a1
    ; Store the computed address in the mutable work selector. Its original initial pointer maps to the first declared work WORD; later aliases and valid target bounds remain open.
	move.l a1,pSCPWorkCell.l
	rts
scpWorkCells:
	dcb.w $140,$0000
pSCPWorkCell:
	dc.l scpWorkCells	; wordAddress
