    ; Referenced ADD distinguishes the work-selector marker from a variable reference before reading a WORD. This continuation remains distinct from the shared instruction-return address.
SCPAddReferencedOperand:
	swap.w d0
	cmp.l #$3726A,d0
	beq.b SCPAddSelectedWorkWord
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a2
	move.w $0002(a2),d0
	add.w d0,$0002(a1)
	rts
SCPAddSelectedWorkWord:
	movea.l pSCPWorkCell.l,a2
	move.w (a2),d0
	add.w d0,$0002(a1)
