    ; SUB shares the three source forms with ADD and writes only variable+2. Preserve WORD subtraction and the original skip gate rather than implying a wider stored result.
SCPSubtractWord:
	tst.w gSCPConditionalSkip.l
	bne.b SCPInstructionReturn
	move.l $0008(a0),d0
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
	move.l $000C(a0),d0
	swap.w d0
	cmp.w #$FFFF,d0
	bne.b .referenced_operand
	swap.w d0
	sub.w d0,$0002(a1)
	rts
.referenced_operand:
	swap.w d0
	cmp.l #$3726A,d0
	beq.b .selected_work_word
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a2
	move.w $0002(a2),d0
	sub.w d0,$0002(a1)
	rts
.selected_work_word:
	movea.l pSCPWorkCell.l,a2
	move.w (a2),d0
	sub.w d0,$0002(a1)
	rts
    ; DIV honors skip, loads record+8 and checks that destination before reading record+12. Unlike AND, this handler establishes D0 from its first operand.
SCPDivideWord:
	tst.w gSCPConditionalSkip.l
	bne.b SCPInstructionReturn
	move.l $0008(a0),d0
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
	move.l $000C(a0),d0
	swap.w d0
	cmp.w #$FFFF,d0
	bne.b .referenced_operand
