	cmp.w #$FFFF,d0
	bne.b .referenced_operand
	swap.w d0
	move.w $0002(a1),d1
	muls.w d0,d1
	move.w d1,$0002(a1)
	rts
.referenced_operand:
	swap.w d0
	cmp.l #$3726A,d0
	beq.b .selected_work_word
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a2
	move.w $0002(a2),d0
	move.w $0002(a1),d1
	muls.w d0,d1
	move.w d1,$0002(a1)
	rts
.selected_work_word:
	movea.l pSCPWorkCell.l,a2
	move.w (a2),d0
	move.w $0002(a1),d1
	muls.w d0,d1
	move.w d1,$0002(a1)
