	swap.w d0
	cmp.w #$FFFF,d0
	beq.b .immediate_word
	swap.w d0
	move.l d0,d1
	subi.l #232806,d1
	bmi.b .variable_word
	cmp.l #$140,d1
	ble.w .string_value
    ; Preserve D0/A0/A1 around cursor positioning, then save record A0 around decimal display of variable+2. These are explicit wrappers, not a general callee-preservation rule.
.variable_word:
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
	movem.l d0/a0-a1,-(a7)
	move.w TextXCoord.l,d0
	move.w TextYCoord.l,d1
	bsr.w MoveCursor
	movem.l (a7)+,d0/a0-a1
	move.l a0,-(a7)
	move.w $0002(a1),d2
	bsr.w DrawBase10Number
	movea.l (a7)+,a0
	rts
.immediate_word:
	swap.w d0
	movem.l d0/a0,-(a7)
	move.w TextXCoord.l,d0
	move.w TextYCoord.l,d1
	bsr.w MoveCursor
	movem.l (a7)+,d0/a0
	move.l a0,-(a7)
	move.w d0,d2
	bsr.w DrawBase10Number
	movea.l (a7)+,a0
	rts
    ; Copy at most 16 source bytes through the period test and append NUL in existing 17-byte scratch. The inclusive base..base+320 classifier does not prove a valid string source.
.string_value:
	move.l a0,-(a7)
	movea.l d0,a1
	lea.l bufferSCPStringDisplay.l,a0
	moveq.l #15,d0
.copy_character:
	move.b (a1)+,(a0)
	move.b (a0)+,d1
	cmp.b #$2E,d1
	beq.w .finish_string
	dbf.w d0,.copy_character
.finish_string:
	move.b #$0,(a0)
	lea.l textSCPStringDisplay(pc),a0
    ; Copy live X/Y as a LONG into the shared text prefix before DisplayText1. Keep the coordinate header, mutable character buffer and excluded tail separate.
	move.l TextXCoord.l,(a0)	; operand 2: PositionedTextCoordinates_x at (a0)
	bsr.w DisplayText1
	movea.l (a7)+,a0
	rts
    ; KEY range-checks its destination and scans translated state without a local skip test. It stores a logical key index, not a raw code, character or byte offset.
SCPReadPressedKeyIndex:
	move.l $0008(a0),d0
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a2
	lea.l bufferKeyboardState.l,a1
    ; Scan 115 WORDs from index 114 down to zero; the first zero wins. Exhaustion stores zero, so index zero and no active entry share the result. The state is not consumed.
	move.w #$72,d0
.scan_index:
	move.w d0,d1
	add.w d1,d1
	tst.w $0(a1,d1.w)
	beq.b .store_index
	dbf.w d0,.scan_index
	clr.w d0
    ; Store the selected logical index as one WORD at destination+2. Preserve the existing destination helper and its inclusive address checks; no slot-alignment proof is added.
.store_index:
	move.w d0,$0002(a2)
	rts
    ; CLR honors skip, saves/restores record A0 around fClsCommand and retains its two-bank text-region/cursor reset. This is not an interpreter reset.
SCPClearText:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	move.l a0,-(a7)
	bsr.w fClsCommand
	movea.l (a7)+,a0
	rts
    ; NEWLIN adds nine to the Y WORD, scrolls/clamps only when the signed result exceeds 118, and stores X=4. It does not call MoveCursor or directly refresh cached bank cursors.
SCPNewLine:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	addi.w #9,TextYCoord.l
	move.w TextYCoord.l,d0
	cmp.w #$76,d0
	ble.b .store_x
	move.l a0,-(a7)
	bsr.w ScrollTextRegionUnlessSuppressed
	movea.l (a7)+,a0
	move.w #$76,TextYCoord.l
.store_x:
	move.w #$4,TextXCoord.l
	rts
    ; TEST honors the current skip WORD and stores one WORD from a tagged immediate or variable+2. RUN entry does not directly reset this retained test cell.
SCPStoreTestValue:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	move.l $0008(a0),d0
	swap.w d0
	cmp.w #$FFFF,d0
	bne.b .variable_value
	swap.w d0
	move.w d0,gSCPTestValue.l
	rts
.variable_value:
	swap.w d0
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
	move.w $0002(a1),gSCPTestValue.l
	rts
gSCPTestValue:
	dc.w $0000
    ; EQU sets the skip BYTE first, then clears the skip WORD only when the stored TEST WORD is zero. The predicate overwrites prior skip state; no nested conditional stack is represented here.
SCPConditionZero:
	st.b gSCPConditionalSkip.l
	move.w gSCPTestValue.l,d0
	tst.w d0
	bne.b .return
	clr.w gSCPConditionalSkip.l
.return:
	rts
    ; LT sets the skip BYTE first, then clears the skip WORD only for a negative TEST WORD. The signed test and existing return path are preserved.
SCPConditionNegative:
	st.b gSCPConditionalSkip.l
	move.w gSCPTestValue.l,d0
	tst.w d0
	bpl.b .return
	clr.w gSCPConditionalSkip.l
.return:
	rts
    ; The original GT entry clears skip for nonnegative TEST WORDs, including zero: BMI skips the CLR. Name the proven predicate, without changing it or claiming an observed language defect.
SCPConditionNonnegative:
	st.b gSCPConditionalSkip.l
	move.w gSCPTestValue.l,d0
	tst.w d0
	bmi.b .return
	clr.w gSCPConditionalSkip.l
.return:
	rts
    ; NE sets the skip BYTE first, then clears the skip WORD only for a nonzero TEST WORD. These predicates read the retained cell rather than evaluate a new record operand.
SCPConditionNonzero:
	st.b gSCPConditionalSkip.l
	move.w gSCPTestValue.l,d0
	tst.w d0
	beq.b .return
	clr.w gSCPConditionalSkip.l
.return:
	rts
    ; ENDIF clears the shared skip WORD without testing its previous value. This is one flag reset, not a restoration of an outer conditional context.
SCPEndCondition:
	clr.w gSCPConditionalSkip.l
	rts
    ; JUMP dereferences the label cell from operand+8, tests only the target low WORD, and selects target minus 16 on success. Its error path restores A0 and sets error/stop BYTEs.
SCPJump:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	lea.l (a0),a1
	movea.l $0008(a0),a0
	movea.l (a0),a0
	move.l a0,d0
	tst.w d0
	bne.b .before_target_record
	lea.l (a1),a0
	st.b gSCPErrorRaised.l
	st.b gSCPStopRequested.l
	rts
.before_target_record:
	lea.l -$0010(a0),a0
	rts
    ; AND honors skip, then range-checks incoming D0 without loading record+8. Keep that entry contract separate from the other arithmetic handlers and from a claim of successful execution.
SCPAndWord:
	tst.w gSCPConditionalSkip.l
	bne.b .return
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
    ; After the first range check returns, read the destination WORD at A1+2. MOVE.W retains the upper D0 WORD; the following operand-two classifier works in D1.
	move.w $0002(a1),d0
    ; Operand two comes from record+12. The variable branch restores its LONG, exchanges it into D0 for the same range helper, then reads that source WORD at +2.
	move.l $000C(a0),d1
	swap.w d1
	cmp.w #$FFFF,d1
	beq.b .tagged_operand
	swap.w d1
	exg d0,d1
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a2
	move.w $0002(a2),d0
	exg d0,d1
	bra.b .store_word
    ; The tagged branch swaps D0, not D1. D1 still has the tag WORD in its low half. Preserve this original register choice; do not substitute the intended immediate operation.
.tagged_operand:
	swap.w d0
    ; AND.W combines the current low WORDs and stores one WORD at destination+2. These are the post-branch values, not an inferred uniform operand-decoding contract.
.store_word:
	and.w d1,d0
	move.w d0,$0002(a1)
.return:
	rts
    ; CALL saves the current record in one mutable cell before dereferencing the label. It tests the full target LONG, restores the caller on zero, and otherwise selects target minus 16.
SCPCall:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
    ; CALL saves one program-record pointer here; ENDCALL restores it. This pair does not implement a nested return stack.
	move.l a0,pSCPCallReturnRecord.l
	movea.l $0008(a0),a0
	move.l (a0),d0
	tst.l d0
	bne.b .before_target_record
	movea.l pSCPCallReturnRecord.l,a0
	st.b gSCPErrorRaised.l
	st.b gSCPStopRequested.l
	rts
.before_target_record:
	movea.l (a0),a0
	lea.l -$0010(a0),a0
	rts
pSCPCallReturnRecord:
	dc.l $00000000	; recordAddress
    ; ENDCALL honors skip, then restores the single saved caller record. RUN advances it by 16 afterward. No nested return stack, initialization order or valid caller lifetime is established.
SCPEndCall:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	movea.l pSCPCallReturnRecord.l,a0
	rts
    ; CHAR chooses a tagged WORD or directly reads untagged base+2, then calls MoveCursor and DrawCharacter. This body has no variable-range helper call; preserve those steps.
SCPPrintCharacter:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	move.l $0008(a0),d0
	swap.w d0
	cmp.w #$FFFF,d0
	beq.w .immediate_character
	swap.w d0
	movea.l d0,a1
	move.w $0002(a1),d4
	bra.b .draw_character
.immediate_character:
	swap.w d0
	move.w d0,d4
.draw_character:
	move.w TextXCoord.l,d0
	move.w TextYCoord.l,d1
	bsr.w MoveCursor
	move.w d4,d0
	bsr.w DrawCharacter
	rts
    ; ENDPROG honors skip before setting the stop BYTE. RUN subsequently tests the WORD after advancing the record; this handler does not set the error flag.
SCPEndProgram:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	st.b gSCPStopRequested.l
	rts
    ; MOVE stores logical text position after transformed WORD checks, not the bank-pointer calculation of MoveCursor. Untagged operands are direct base+2 reads in this body.
SCPSetTextPosition:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	move.l $0008(a0),d0
	swap.w d0
	cmp.w #$FFFF,d0
	beq.b .x_value_ready
	swap.w d0
	movea.l d0,a1
	move.w $0002(a1),d0
	swap.w d0
.x_value_ready:
	swap.w d0
	addi.w #4,d0
	cmp.w #$4,d0
	blt.w SCPRangeError
	cmp.w #$1D,d0
	bgt.w SCPRangeError
	move.l $000C(a0),d1
	swap.w d1
	cmp.w #$FFFF,d1
	beq.b .y_value_ready
	swap.w d1
	movea.l d1,a1
	move.w $0002(a1),d1
	swap.w d1
.y_value_ready:
	swap.w d1
	addi.w #2,d1
    ; After WORD row+2, MULU by nine produces the register result; only its low WORD is compared with 9 and 118 and stored. Do not infer a general input-row bound.
	mulu.w #$9,d1
	cmp.w #$9,d1
	blt.w SCPRangeError
	cmp.w #$76,d1
	bgt.w SCPRangeError
    ; Store X/Y only after both component checks. These logical WORDs are the prefix template copied by display callers; following glyph storage remains separate.
	move.w d0,TextXCoord.l
	move.w d1,TextYCoord.l
	rts
gSCPStopRequested:
	dc.w $0000
    ; PLOT honors skip, reads two coordinate WORDs and checks X=20..297,Y=15..128 before storing them. These caller checks are wider than the pixel helper accepted rectangle.
SCPPlot:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	move.l $0008(a0),d0
	swap.w d0
	cmp.w #$FFFF,d0
	beq.b .immediate_x
	swap.w d0
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
	move.w $0002(a1),d0
	bra.b .read_y
.immediate_x:
	swap.w d0
.read_y:
	move.l $000C(a0),d1
	swap.w d1
	cmp.w #$FFFF,d1
	beq.b .immediate_y
	swap.w d1
	exg d0,d1
	bsr.w CheckSCPVariableAddressRange
	exg d0,d1
	movea.l d1,a1
	move.w $0002(a1),d1
	bra.b .check_point
.immediate_y:
	swap.w d1
.check_point:
	cmp.w #$14,d0
	blt.w SCPRangeError
	cmp.w #$129,d0
	bgt.w SCPRangeError
	cmp.w #$80,d1
	bgt.w SCPRangeError
	cmp.w #$F,d1
	blt.w SCPRangeError
    ; Store both coordinate WORDs before the pixel calls. Save record A0, toggle the selector for the first call, toggle back and reload the stored point for the second; restore record A0.
	move.w d0,scpGraphicsAnchor.l
	move.w d1,scpGraphicsAnchorY.l
	move.l a0,-(a7)
	eori.l #32768,gDrawBankByteOffset.l
	jsr Draw4BitplanePixel.l
	eori.l #32768,gDrawBankByteOffset.l
	move.w scpGraphicsAnchor.l,d0
	move.w scpGraphicsAnchorY.l,d1
	jsr Draw4BitplanePixel.l
	movea.l (a7)+,a0
	rts
    ; UNPLOT retains two pixel calls and two BYTE clears after each. It stores the same anchor as PLOT; its registered name alone does not establish a general pixel-erase contract.
SCPUnplot:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	move.l $0008(a0),d0
	swap.w d0
	cmp.w #$FFFF,d0
	beq.b .immediate_x
	swap.w d0
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
	move.w $0002(a1),d0
	bra.b .read_y
.immediate_x:
	swap.w d0
.read_y:
	move.l $000C(a0),d1
	swap.w d1
	cmp.w #$FFFF,d1
	beq.b .immediate_y
	swap.w d1
	exg d0,d1
	bsr.w CheckSCPVariableAddressRange
	exg d0,d1
	movea.l d1,a1
	move.w $0002(a1),d1
	bra.b .check_point
.immediate_y:
	swap.w d1
.check_point:
	cmp.w #$14,d0
	blt.w SCPRangeError
	cmp.w #$129,d0
	bgt.w SCPRangeError
	cmp.w #$80,d1
	bgt.w SCPRangeError
	cmp.w #$F,d1
	blt.w SCPRangeError
	move.w d0,scpGraphicsAnchor.l
	move.w d1,scpGraphicsAnchorY.l
	move.l a0,-(a7)
	eori.l #32768,gDrawBankByteOffset.l
	jsr Draw4BitplanePixel.l
    ; Post-call BCLRs use D0 at A0+2 and A0+4. The accepted pixel path supplies its bit number in D1; preserve the original registers and offsets rather than replacing this sequence.
	bclr.b d0,$0002(a0)
	bclr.b d0,$0004(a0)
	eori.l #32768,gDrawBankByteOffset.l
	move.w scpGraphicsAnchor.l,d0
	move.w scpGraphicsAnchorY.l,d1
	jsr Draw4BitplanePixel.l
	bclr.b d0,$0002(a0)
	bclr.b d0,$0004(a0)
	movea.l (a7)+,a0
	rts
scpGraphicsAnchor:	; ARRAY ScreenPixelWordPoint[1]
	dc.w $0000
scpGraphicsAnchorY:
	dc.w $0000
    ; DRAW honors skip and sends requested/stored WORD endpoints to the existing line clipper. It does not apply the PLOT caller rectangle or update the stored anchor after these calls.
SCPDraw:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	move.l $0008(a0),d0
	swap.w d0
	cmp.w #$FFFF,d0
	beq.b .immediate_x
	swap.w d0
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
	move.w $0002(a1),d0
	bra.b .read_y
.immediate_x:
	swap.w d0
.read_y:
	move.l $000C(a0),d1
	swap.w d1
	cmp.w #$FFFF,d1
	beq.b .immediate_y
	swap.w d1
	exg d0,d1
	bsr.w CheckSCPVariableAddressRange
	exg d0,d1
	movea.l d1,a1
	move.w $0002(a1),d1
	bra.b .draw_from_anchor
.immediate_y:
	swap.w d1
    ; Load the anchor as D2/D3 and save requested D0/D1 on the stack. The first line call receives requested -> anchor after toggling the bank selector.
.draw_from_anchor:
	move.w scpGraphicsAnchor.l,d2
	move.w scpGraphicsAnchorY.l,d3
	move.l a0,-(a7)
	move.w d0,-(a7)
	move.w d1,-(a7)
	eori.l #32768,gDrawBankByteOffset.l
	jsr DrawClippedLineOnFourPlanes.l
	eori.l #32768,gDrawBankByteOffset.l
    ; After the second selector toggle, load the anchor as D0/D1 and pop requested Y/X into D3/D2. The second line call receives anchor -> requested.
	move.w scpGraphicsAnchor.l,d0
	move.w scpGraphicsAnchorY.l,d1
	move.w (a7)+,d3
	move.w (a7)+,d2
	jsr DrawClippedLineOnFourPlanes.l
	movea.l (a7)+,a0
	rts
SCPLPrint:
	tst.w gSCPConditionalSkip.l
	bne.w SCPInstructionReturn
	move.l $0008(a0),d0
	swap.w d0
	cmp.w #$FFFF,d0
	beq.b SCPLPrintImmediateValue
	swap.w d0
	move.l d0,d1
	subi.l #232806,d1
	bmi.w SCPLPrintVariableValue
	cmp.l #$140,d1
	ble.w SCPLPrintStringValue
SCPLPrintVariableValue:
	bsr.w CheckSCPVariableAddressRange
	movea.l d0,a1
	move.l a0,-(a7)
	move.w $0002(a1),d2
	bsr.w PrintSCPWordDecimal
	bsr.w PrintSCPCrLf
	movea.l (a7)+,a0
	rts
SCPLPrintStringValue:
	move.l a0,-(a7)
	movea.l d0,a1
	lea.l bufferSCPStringDisplay.l,a0
	moveq.l #15,d0
.copy_character:
	move.b (a1)+,(a0)
	move.b (a0)+,d1
	cmp.b #$2E,d1
	beq.b .finish_string
	dbf.w d0,.copy_character
.finish_string:
	move.b #$0,(a0)
	lea.l bufferSCPStringDisplay.l,a0
	bsr.w PrintSCPString
	bsr.w PrintSCPCrLf
	movea.l (a7)+,a0
	rts
    ; Printer abort storage is cleared as a WORD, set by ST.B at its base and tested as a WORD. Its initial zero is not a proof of global lifetime or writer closure.
gSCPPrinterAbort:
	dc.w $0000
SCPLPrintImmediateValue:
	swap.w d0
	move.l a0,-(a7)
	move.w d0,d2
	bsr.w PrintSCPWordDecimal
	bsr.w PrintSCPCrLf
	movea.l (a7)+,a0
	rts
    ; Convert the D2 WORD to packed decimal, suppress leading zeros, retain the final digit and count attempted output in D4. This body does not read flagDecimalNegative or print a minus.
PrintSCPWordDecimal:
	clr.w gSCPPrinterAbort.l
	bsr.w ConvertBase10Number
	clr.w d4
	clr.w gDecimalDigitsStarted.l
	moveq.l #7,d3
.next_digit:
	rol.l #4,d2
	move.b d2,d0
	andi.w #15,d0
	addi.w #48,d0
	cmp.w #$39,d0
	ble.b .test_leading_zero
	addi.w #7,d0
.test_leading_zero:
	cmp.w #$0,d3
	beq.b .emit_digit
	cmp.b #$30,d0
	bne.b .emit_digit
	tst.w gDecimalDigitsStarted.l
	beq.b .advance_digit
.emit_digit:
	addq.w #1,d4
	bsr.w WriteSCPPrinterByte
	tst.w gSCPPrinterAbort.l
	bne.b .done
	st.b gDecimalDigitsStarted.l
.advance_digit:
	dbf.w d3,.next_digit
.done:
	rts
    ; Send CR then LF through the same byte helper. Preserve the original two calls and their error/stop effects; this is not a timing or hardware-output observation.
PrintSCPCrLf:
	move.b #$D,d0
	bsr.w WriteSCPPrinterByte
	move.b #$A,d0
	bsr.w WriteSCPPrinterByte
	rts
    ; Clear the shared error WORD, set CIAA DDRB to $FF, then poll CIAB busy before sending D0.b to CIAA PRB. The existing SELECT-bit sequence is retained, without a protocol or timing claim.
WriteSCPPrinterByte:
	clr.w gSCPErrorRaised.l
	move.b #$FF,_ciaa+ciaddrb.l
    ; D7 starts at 60000; each wait iteration decrements before checking busy. The two later D6=300 DBF loops each execute 301 iterations. Counts are not measured durations.
	move.w #$EA60,d7
.wait_ready:
	subq.w #1,d7
	beq.b .offline
	btst.b #CIAB_PRTRBUSY,_ciab+ciapra.l
	bne.b .wait_ready
	bset.b #CIAB_PRTRSEL,_ciab+ciapra.l
	move.b d0,_ciaa+ciaprb.l
	move.w #$12C,d6
.select_high_delay:
	nop
	nop
	nop
	dbf.w d6,.select_high_delay
	bclr.b #CIAB_PRTRSEL,_ciab+ciapra.l
	move.w #$12C,d6
.select_low_delay:
	nop
	nop
	nop
	dbf.w d6,.select_low_delay
	bset.b #CIAB_PRTRSEL,_ciab+ciapra.l
	rts
    ; Timeout sets the high BYTEs of error and stop, displays the positioned offline record and updates cursor/scroll state. It sets the printer-abort BYTE and returns; no guest run is implied.
.offline:
	move.l a0,-(a7)
	st.b gSCPErrorRaised.l
	st.b gSCPStopRequested.l
	lea.l textSCPPrinterOffline.l,a0
	move.l TextXCoord.l,(a0)
	move.w #$4,(a0)
	bsr.w DisplayText1
	addi.w #9,TextYCoord.l
	move.w #$4,TextXCoord.l
	move.w TextYCoord.l,d0
	cmp.w #$76,d0
	bne.b .finish_offline
	bsr.w ScrollTextRegionUnlessSuppressed
	move.w #$6D,TextYCoord.l
.finish_offline:
	movea.l (a7)+,a0
	st.b gSCPPrinterAbort.l
	rts
    ; Two coordinate WORDs precede the offline text. The timeout copies TextXCoord.L into this prefix, then replaces X with 4; the copied Y is retained for DisplayText1.
textSCPPrinterOffline:
	dc.w $0000
textSCPPrinterOfflineY:
	dc.w $0000
	dc.b "Printer Off Line Or Disconnected",$00
	dc.b $00	; opaque_data
    ; D5 counts attempted bytes, incremented before output. Send the current byte first, then test error and the next byte for NUL. This is not a prechecked empty-string or bounded-copy contract.
PrintSCPString:
	clr.w d5
	clr.w gSCPErrorRaised.l
.next_byte:
	addq.w #1,d5
	move.b (a0)+,d0
	bsr.w WriteSCPPrinterByte
	tst.w gSCPErrorRaised.l
	bne.b .done
	tst.b (a0)
	bne.b .next_byte
.done:
	rts
    ; Save and restore D7 around each byte call, which clobbers D7 for its ready wait. DBF sends D7+1 spaces for an ordinary nonnegative initial count; preserve the original count convention.
PrintSCPSpaces:
	move.w d7,-(a7)
	move.b #$20,d0
	bsr.w WriteSCPPrinterByte
	move.w (a7)+,d7
	dbf.w d7,PrintSCPSpaces
	rts
    ; Editor p prints its control/banner sequence and tests abort, then heading, WORD count times 16 and records. It reconstructs text from records and the same 14-BYTE instruction descriptors.
SCPEditorPrintListing:
	clr.w gSCPPrinterAbort.l
	lea.l sSCPPrinterBanner.l,a0
	bsr.b PrintSCPString
	tst.w gSCPPrinterAbort.l
	beq.b .header
	rts
.header:
	bsr.w PrintSCPCrLf
	lea.l sSIMPLEPrinterListTitle.l,a0
	bsr.b PrintSCPString
	bsr.w PrintSCPCrLf
