    ; Parse the original optional range and preserve its WORD arithmetic and branch order. This pass does not infer a general valid-range or malformed-input contract.
.parse_range:
	bsr.w ParseSCPDecimal
	subi.w #1,d0
	move.w d0,d2
	mulu.w #$10,d0
	adda.w d0,a0
	lea.l $1(a2,d5.w),a2
	bsr.w ParseSCPDecimal
	move.w d0,d3
	cmp.w d2,d3
	bgt.b .test_range_end
	exg d2,d3
	lea.l scpProgramRecords(pc),a0
	move.w d2,d0
	asl.w #4,d0
	adda.w d0,a0
	move.w d3,d0
.test_range_end:
	cmp.w gSCPProgramLineCount.l,d0
	ble.b .begin_listing
	move.w gSCPProgramLineCount.l,d3
.begin_listing:
	tst.w gSCPProgramLineCount.l
	beq.w PrintSCPEmptyListing
	bsr.w PrintSCPCrLf
