    ; Read the stored record prefix; the original branch selects string records or descriptor-backed instructions. Keep the 16-BYTE record stride and shared line-advance continuation.
SCPPrinterListingRecord:
	move.l (a0),d0
	beq.b .instruction_record
	cmp.l #$38BDA,d0
	blt.w PrintSCPStringRecord
.instruction_record:
	move.l $0004(a0),d0
	clr.w d1
