.find_descriptor:
	cmp.l $8(a1,d1.w),d0
	beq.b .descriptor_found
	addi.w #14,d1
	bra.b .find_descriptor
.descriptor_found:
	movem.l d0-d3/a0-a1,-(a7)
	tst.l (a0)
	beq.b .line_number
	move.l a0,-(a7)
	move.l TextXCoord.l,textSCPLineLabelPrefix.l
	lea.l textSCPLineLabelPrefix.l,a0
	lea.l $0004(a0),a0
	bsr.w PrintSCPString
	movea.l (a7)+,a0
.line_number:
