	beq.b .unlabelled_line
	move.l (a0),d2
	subi.l #232410,d2
	lsr.w #2,d2
	addq.w #1,d2
	bsr.w PrintSCPWordDecimal
	move.w #$3,d7
	bsr.w PrintSCPSpaces
	bra.b .mnemonic
.unlabelled_line:
	addq.w #1,d2
	bsr.w PrintSCPWordDecimal
	move.w #$4,d7
	bsr.w PrintSCPSpaces
.mnemonic:
