	move.l $0(a1,d1.w),scpMnemonicFirstFourChars.l
	move.l $4(a1,d1.w),scpMnemonicLastFourChars.l
	lea.l textSCPMnemonicRecord.l,a0
	lea.l $0004(a0),a0
	bsr.w PrintSCPString
	movem.l (a7)+,d0-d3/a0-a1
	move.w #$8,d7
	sub.w d5,d7
	bsr.w PrintSCPSpaces
	tst.w $C(a1,d1.w)
	beq.b AdvanceSCPPrinterListingRecord
	move.l $0008(a0),d0
	bsr.w PrintSCPOperand
	move.w $C(a1,d1.w),d0
	subi.w #1,d0
	beq.b AdvanceSCPPrinterListingRecord
	move.l $000C(a0),d0
	bsr.w PrintSCPOperand
