    ; Preserve registers, set X=4 and add 9 to Y. Above109 clears suppression before scrolling, clamps109 and positions the cursor. Other line helpers have different rules.
AdvanceTerminalTextLine:
	movem.l d0-d7/a0-a6,-(a7)
	move.w #$4,TextXCoord.l
	addi.w #9,TextYCoord.l
	cmpi.w #109,TextYCoord.l
