	movem.l d0-d7/a0-a6,-(a7)
	bsr.b AdvanceTerminalTextLine
	movem.l (a7)+,d0-d7/a0-a6
.position_initial_cursor:
	move.w TextXCoord.l,d0
	move.w TextYCoord.l,d1
	move.l a0,-(a7)
	jsr MoveCursor.l
	movea.l (a7)+,a0
    ; Shared flow point, not a separate callable entry: both text entries already saved the register frame. X>=31 clears scroll suppression and advances a terminal line.
WrappedTextWidthCheck:
	cmpi.w #31,TextXCoord.l
	blt.b .measure_remaining
	clr.w gTextScrollSuppressed.l
	bsr.w AdvanceTerminalTextLine
