	lea.l (a0),a1
	move.w TextXCoord.l,d7
.scan_to_nul:
	addq.w #1,d7
	tst.b (a1)+
	bne.b .scan_to_nul
	cmp.w #$1F,d7
	blt.b .draw_remainder
	moveq.l #31,d7
	sub.w TextXCoord.l,d7
