	movea.l (a7)+,a0
	move.b (a7)+,(a0)
	bra.b WrappedTextWidthCheck
    ; Draw the remaining bytes, then restore the one outer register frame shared by both entries and return to their caller.
.draw_remainder:
	jsr DrawNonemptyTextBytes.l
	movem.l (a7)+,d0-d7/a0-a6
	rts
    ; No eligible space found: preserve A0 across line advance and retry the same text. This branch consumes no input; arbitrary-input termination is not established.
.advance_without_consuming:
	move.l a0,-(a7)
	bsr.w AdvanceTerminalTextLine
	movea.l (a7)+,a0
	bra.b WrappedTextWidthCheck
