	bra.w GalNetConversationLoop
.possession_reply:
	lea.l sConvTradeOfferPossession(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.b SelectConversationOfferedGoods
    ; Expand from the preamble address through the shared possession tail before the one final NUL, draw it without an extra line advance, then select the offered goods.
DisplayConversationPurchasePreamble:
	lea.l sConvTradeOfferPreamble(pc),a0
	bsr.w ExpandConversationReplyScript
	lea.l conversationReplyBuffer(pc),a0
	jsr DrawWrappedText.l
    ; Use the same saved masked index 0..15 for the goods-name and LONG base-amount catalogs. Names append at the live cursor; the absolute table amount enters BeginConversationPurchase.
SelectConversationOfferedGoods:
	jsr ConversationRandomWordPreservingD1.l
	andi.w #15,d0
	move.w d0,gConversationOfferedGoodsIndex.l
	lea.l conversationOfferedGoodsNames(pc),a0
	move.w d0,-(a7)
	bsr.b IndexConversationStringCatalog
	jsr AppendWrappedTextAtCursor.l
	move.w (a7)+,d0
	add.w d0,d0
	add.w d0,d0
	lea.l conversationOfferBaseAmounts(pc),a0
    ; Load the indexed LONG base amount, then take its absolute value. The existing 16-entry table supplies initial asks from 50 through 10000; no parsed amount is displayed by this entry.
	move.l $0(a0,d0.w),d0
	bpl.w abs_0_0003B780
	neg.l d0
abs_0_0003B780:
	bra.w BeginConversationPurchase
sConvTradeRepeatedNoCargo:
	dc.b "%r3(No, I already told you/I said no and I meant it/No, no ghostly cargo appearences over here)",$00
sConvTradeNoCargo:
	dc.b "+c%r5(Not today trader./You're out of luck - empty hold./I'm just a traveller, not a trader./I only deal at spaceports where I can see the goods, too may conmen out here/I never trade in open space, it's a matter of principle)",$00
sConvTradeOfferPreamble:
	dc.b "%r3(Look/listen/Nah then), I'm a businessman, %r3(lets do some business,/let me do you a favour,/and I like you, let me help you out.) "
sConvTradeOfferPossession:
	dc.b "%r3(I've got some/I just happen to have some/How would you like some) ",$00
    ; Sixteen consecutive NUL strings end exactly at the 16-LONG amount table. The offer path uses the same saved 0..15 index for both catalogs.
conversationOfferedGoodsNames:
	dc.b "high quality bath towels ",$00
	dc.b "exotic space lingerie, very popular on some planets.",$00
	dc.b "Bottles of Qualactin hypermint extract ",$00
	dc.b "Bottles of Old Janx Spirit ",$00
	dc.b "Cases of Arcturan Mega-gin ",$00
	dc.b "Fallian marsh gas canisters ",$00
	dc.b "Algolian suntiger teeth ",$00
	dc.b "Arcturan in-flight space jackets, total luxury stuff.",$00
	dc.b "sub-etha chronographs ",$00
	dc.b "sens-o-tape copies of the latest Playbeing ",$00
	dc.b "copies of THE book (you know, THE book!) ",$00
	dc.b "octophonic supersound starport blasters, with Arcturan mega-bass woofers.",$00
	dc.b "sub-etha sens-o-matics ",$00
	dc.b "Serious Cybernetics GPP robots ",$00
	dc.b "SIMPLE programming manuals ",$00
	dc.b "class 4 missiles, like the military use ",$00
    ; The buyer rejects indices 1,7,8,11,13,14,15, exactly the negative entries; it checks index values. The offering path uses absolute amounts. Keep the table name neutral.
conversationOfferBaseAmounts:
	dc.l $00000064
	dc.l $FFFFFF38
	dc.l $000000C8
	dc.l $000003E8
	dc.l $000005DC
	dc.l $000000C8
	dc.l $00000190
	dc.l $FFFFFC18
	dc.l $FFFFFE0C
	dc.l $000007D0
	dc.l $00001388
	dc.l $FFFFEC78
	dc.l $000000C8
	dc.l $FFFFD8F0
	dc.l $FFFFFFCE
	dc.l $FFFFD8F0
    ; Format D0.W as sign/space, decimal magnitude and trailing space. X>24 advances a line first. LONG-valued trade callers still use this original low-WORD display contract.
DrawConversationWordAmount:
	move.w TextXCoord.l,d7
	cmp.w #$18,d7
	ble.b .emit_sign
	move.w d0,-(a7)
	bsr.w AdvanceTerminalTextLine
	move.w (a7)+,d0
.emit_sign:
	move.w d0,-(a7)
	btst #15,d0
	bne.b .negative_word
	moveq.l #32,d0
	bra.b .draw_sign_and_digits
    ; Bit15 selects minus; negate the saved WORD, then zero-extend the magnitude before unsigned decimal conversion. Do not extend this formatter to LONG amounts.
.negative_word:
	moveq.l #45,d0
	neg.w (a7)
.draw_sign_and_digits:
	jsr DrawCharacter.l
	move.w (a7)+,d0
	andi.l #65535,d0
	bsr.w DrawUnsignedWordDecimal
	moveq.l #32,d0
	jmp DrawCharacter.l
    ; Input here is an unsigned WORD magnitude in D0.L from the caller or a recursive quotient. DIVU10 saves the remainder and recursively emits higher digits first.
DrawUnsignedWordDecimal:
	divu.w #$A,d0
	swap.w d0
	move.w d0,-(a7)
	move.w #$0,d0
	swap.w d0
	tst.w d0
	beq.b .emit_digit
	bsr.b DrawUnsignedWordDecimal
.emit_digit:
	move.w (a7)+,d0
	addi.w #48,d0
	jmp DrawCharacter.l
    ; Four LONG slots: initial/current ask, shared offer and previous shared offer. Numeric purchase input writes the shared slot; both completion paths read it.
gConversationInitialAsk:
	dc.l $00000000
gConversationCurrentAsk:
	dc.l $00000000
gConversationSharedOfferAmount:
	dc.l $00000000
gConversationPreviousSharedOffer:
	dc.l $00000000
    ; D0 initializes the initial/current asking amounts. This entry does not initialize the shared offer slot used by the completion path.
BeginConversationPurchase:
	move.l d0,gConversationInitialAsk.l
	move.l d0,gConversationCurrentAsk.l
	lea.l sConvTradeAskAmountPrefix(pc),a0
	bsr.w ExpandConversationReplyScript
	lea.l conversationReplyBuffer(pc),a0
	bsr.w DrawWrappedText
	move.l gConversationInitialAsk(pc),d0
    ; This call displays the initial absolute table ask (50..10000 on the traced offer entry), which fits signed WORD. Keep its surrounding LONG transaction state and suffix.
	bsr.w DrawConversationWordAmount
	lea.l sConvTradeCreditSuffix(pc),a0
	jsr AppendWrappedTextAtCursor.l
	bsr.w AdvanceTerminalTextLine
	lea.l sConvTradeAskAcceptance(pc),a0
	bsr.w ExpandAndDisplayConversationReply
ReadConversationPurchaseResponse:
	bsr.w ReadConversationInput
	beq.b EvaluateConversationPurchaseResponse
	lea.l sConvTradeAskDefiniteAnswer(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.b ReadConversationPurchaseResponse
EvaluateConversationPurchaseResponse:
	lea.l sConvTradeYesPattern(pc),a0
	bsr.w MatchConversationPattern
	beq.w CheckConversationPurchaseFunds
	lea.l sConvTradeNoPattern(pc),a0
	bsr.w MatchConversationPattern
	bne.b StoreConversationCounterOffer
	bsr.w ConversationRandomWordPreservingD1
	andi.w #3,d0
	bne.b .consider_discount
	lea.l sConvTradeDeclinedSignoff(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
    ; A matched NO-pattern response sets D1 at current ask shifted right once. Wrapper preserves D1; the common adjustment then shifts only its low WORD by two. This is not the empty-input path.
.consider_discount:
	move.l gConversationCurrentAsk(pc),d1
	lsr.l #1,d1
	jsr ConversationRandomWordPreservingD1.l
	andi.w #3,d0
	bne.b AdjustConversationPurchaseAsk
	lea.l sConvTradeDeclinedSignoff(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
    ; With a found number, copies the shared offer to its previous slot and replaces it from the parsed LONG. Original comparison and adjustment arithmetic is preserved.
StoreConversationCounterOffer:
	tst.w flagConversationNumberFound.l
	beq.w RequestConversationCounterOffer
	move.l gConversationSharedOfferAmount(pc),gConversationPreviousSharedOffer.l
	move.l gConversationParsedNumber(pc),d0
	move.l d0,gConversationSharedOfferAmount.l
	move.l gConversationPreviousSharedOffer(pc),d1
	sub.l d0,d1
	bpl.b RejectConversationCounterOffer
	neg.l d1
	move.l gConversationInitialAsk(pc),d2
	lsr.l #6,d2
	cmp.l d2,d1
	blt.b RejectConversationCounterOffer
	move.l gConversationInitialAsk(pc),d1
	lsr.l #1,d1
	cmp.l d1,d0
	blt.b ConsiderConversationLowOfferSignoff
    ; For a numeric adjustment, D1 becomes current ask minus parsed offer. The signed comparison takes settlement when that difference is no greater than initial ask shifted right four.
	move.l gConversationCurrentAsk(pc),d1
	cmp.l d0,d1
	beq.w CheckConversationPurchaseFunds
	sub.l d0,d1
	move.l gConversationInitialAsk(pc),d0
	lsr.l #4,d0
	cmp.l d0,d1
	ble.b CheckConversationPurchaseFunds
    ; Keep LSR.W then LONG subtraction. On the traced positive purchase chain, both incoming D1 values fit a WORD and current ask remains positive and no greater than its initial ask.
AdjustConversationPurchaseAsk:
	lsr.w #2,d1
	sub.l d1,gConversationCurrentAsk.l
	lea.l sConvTradeCounterOfferPrefix(pc),a0
	bsr.w ExpandConversationReplyScript
	lea.l conversationReplyBuffer(pc),a0
	bsr.w DrawWrappedText
	move.l gConversationCurrentAsk(pc),d0
	bsr.w DrawConversationWordAmount
	lea.l sConvTradeCreditSuffix(pc),a0
	jsr AppendWrappedTextAtCursor.l
	lea.l sConvTradeCounterOfferSuffix(pc),a0
    ; Shared A0-script flow point: expand/display the selected purchase reply, then resume ReadConversationPurchaseResponse. This is not a new independently callable entry.
DisplayConversationPurchaseReplyAndRetry:
	bsr.w ExpandAndDisplayConversationReply
	bra.w ReadConversationPurchaseResponse
RejectConversationCounterOffer:
	lea.l sConvTradeRejectOffer(pc),a0
	bra.b DisplayConversationPurchaseReplyAndRetry
ConsiderConversationLowOfferSignoff:
	jsr ConversationRandomWordPreservingD1.l
	andi.w #3,d0
	bne.b RejectConversationCounterOffer
	lea.l sConvTradeOffendedSignoff(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
RequestConversationCounterOffer:
	lea.l sConvTradeAskOffer(pc),a0
	bra.b DisplayConversationPurchaseReplyAndRetry
    ; Reads the shared offer LONG, not the displayed ask. Signed BLT requires it to be strictly below gCreditBalance; equality takes the insufficient-funds path.
CheckConversationPurchaseFunds:
	move.l gConversationSharedOfferAmount(pc),d0
	lea.l tradeAccountBase.l,a1
	cmp.l $0034(a1),d0
	blt.b CheckConversationPurchaseSpace
	lea.l sConvTradeInsufficientFunds(pc),a0
    ; Shared A0-script flow point for success or refusal: display it, then resume GalNetConversationLoop. The actual debit, if any, has already happened.
DisplayConversationPurchaseReplyAndResumeGalNet:
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
    ; Requires the WORD at tradeAccountBase+$32 to be at least 10 before committing the purchase.
CheckConversationPurchaseSpace:
	lea.l tradeAccountBase.l,a2
	lea.l $0032(a2),a2
	cmpi.w #10,(a2)
	bge.b CompleteConversationPurchase
	lea.l sConvTradeInsufficientCargoSpace(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
    ; Subtracts the shared offer from credits, adds 10 to the selected special-goods WORD and subtracts 10 from free cargo units.
CompleteConversationPurchase:
	sub.l d0,$0034(a1)
	lea.l cargoQuantityStorage.l,a0
	lea.l $0032(a0),a0
	move.w gConversationOfferedGoodsIndex.l,d0
	add.w d0,d0
	addi.w #10,$0(a0,d0.w)
	subi.w #10,(a2)
	lea.l sConvTradePurchaseComplete(pc),a0
	bra.b DisplayConversationPurchaseReplyAndResumeGalNet
sConvTradeInsufficientCargoSpace:
	dc.b "%r3(You haven't got room man/Check your cargo manifest buster/When you've got space in your hold, try again)",$00
sConvTradeAskAmountPrefix:
	dc.b "%r5(I could let you have them for just/I need the cash, so you can have them for only/For you, only/A bargain at only/I couldn't let them go for less than)",$00
sConvTradeCreditSuffix:
	dc.b "creds ",$00
sConvTradeAskAcceptance:
	dc.b "%r3(What do you say?/How about it?/Well?)",$00
sConvTradeAskDefiniteAnswer:
	dc.b "Don't mess me about, do you want them or not?",$00
	dc.b "+! %r4(Sold, you are a hard alien/Ok, I must be mad to let you have them for that though/I'll go out of business like this, but ok/I think I've just been Had !)",$00
sConvTradeCounterOfferPrefix:
	dc.b "%r3(Tell you what,/How about you give me/You are hard,)",$00
sConvTradeCounterOfferSuffix:
	dc.b "%r6( / /- and that's my final offer./- not a cred less./,you'll put me out of business!/,think of my reputation.)",$00
sConvTradeRejectOffer:
	dc.b "%r4(What kind of a deal is that!/Don't waste my time/Less than I paid for them!/Life is short and I'm dammed if I'll waste much more time on you.)",$00
sConvTradeOffendedSignoff:
	dc.b "+! %r3(Look, just forget it eh?/Leave me alone/What kind of trader are you?)",$00
sConvTradeAskOffer:
	dc.b "%r2(Look, do you want them or not?/Make me an offer at least.)",$00
sConvTradeDeclinedSignoff:
	dc.b "+!%r3(Ok, suit yourself/Don't know what you just missed mate/You could have made a killing there)",$00
sConvTradeInsufficientFunds:
	dc.b "+!Your bank tells me you can't afford that, maybe we'll trade when you have some creds",$00
sConvTradePurchaseComplete:
	dc.b "+!%r5(It's a deal./Done [you have been!]/Done./Ok mac./So long sucker.)",$00
sConvTradeNoPattern:
	dc.b "* (n/no/get lost/go away/nein/non/never) *",$00
sConvTradeYesPattern:
	dc.b "* (y/yes/ok/right on/fine/ja/oui/yea/arr/yo/mmm/uh huh) *",$00
    ; The WORD flag is cleared; ST.B sets its first byte to FF. Callers test the WORD. The parsed LONG is replaced only when a digit run is found.
flagConversationNumberFound:
	dc.w $0000
gConversationParsedNumber:
	dc.l $00000000
    ; Extracts the first digit run from bufferEDIInput, removes it in place and sets the found flag. Arithmetic retains MULU.W #10. No digits clears only the flag, not the previous LONG value.
ExtractConversationDecimal:
	moveq.l #0,d0
	moveq.l #0,d1
	clr.w flagConversationNumberFound.l
	lea.l bufferEDIInput.l,a0
.scan:
	move.b (a0)+,d0
	beq.b .done
	cmp.b #$39,d0
	bgt.b .scan
	cmp.b #$30,d0
	blt.b .scan
	lea.l -$0001(a0),a1
    ; MULU.W discards the previous high WORD before multiplying by 10. With zero-extended digit 0..9, each accumulated LONG is at most 655359; this is not a full 32-bit decimal parser.
.accumulate_digits:
	mulu.w #$A,d1
	subi.b #48,d0
	add.l d0,d1
	move.b (a0)+,d0
	cmp.b #$39,d0
	bgt.b .remove_digit_span
	cmp.b #$30,d0
	bge.b .accumulate_digits
.remove_digit_span:
	subq.w #1,a0
.shift_suffix:
	move.b (a0)+,(a1)+
	bne.b .shift_suffix
    ; Store the parsed LONG only after finding a digit run. Its ordinary accumulator bound is 0..655359; the no-digit return retains the previous value and clears the found flag.
	move.l d1,gConversationParsedNumber.l
	st.b flagConversationNumberFound.l
.done:
	rts
    ; The intent handoff first tries matching goods in the current token stream through BeginConversationGoodsSale. It differs from the separate prompt-first route.
RouteToConversationGoodsSale:
	bra.b BeginConversationGoodsSale
    ; Fallback slots branch straight to the existing goods-sale prompt, rather than first testing the current token stream. This wrapper has no return of its own.
RouteToConversationGoodsSalePrompt:
	bra.b PromptConversationGoodsSale
BeginConversationGoodsSale:
	bsr.w MatchConversationGoodsCatalog
	beq.w ValidateConversationSaleGoods
	bra.b abs_0_0003C3F8
PromptConversationGoodsSale:
	lea.l sConvTradeRequestSpecialCargo(pc),a0
	bsr.w ExpandAndDisplayConversationReply
ReadConversationSaleGoods:
	bsr.w ReadConversationInput
	lea.l sConvTradeDeclineGoodsPattern(pc),a0
	bsr.w MatchConversationPattern
	bne.b abs_0_0003C3EC
	lea.l sConvTradeSpecialCargoDeclined(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
abs_0_0003C3EC:
	lea.l sConvTradeYesPattern.l,a0
	bsr.w MatchConversationPattern
	bne.b ValidateConversationSaleGoods
abs_0_0003C3F8:
	lea.l sConvTradeAskCargoType(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.b ReadConversationSaleGoods
abs_0_0003C402:
	lea.l sConvTradeAskSpecificCargo(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.b ReadConversationSaleGoods
    ; Explicit index refusals are 1,7,8,11,13,14,15, exactly the negative amount entries. This code checks indices, not the sign bit.
ValidateConversationSaleGoods:
	bsr.w MatchConversationGoodsCatalog
	bne.b abs_0_0003C402
    ; Refuse exactly indices 1,7,8,11,13,14,15 before normal sale pricing. The remaining original table amounts are positive 100..5000; no universal legality flag is inferred.
	cmpi.w #1,gConversationMatchedGoodsIndex.l
	bne.b .check_index_7
	lea.l sConvTradeRefuseCargoType1(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w FinishConversationGoodsRefusal
.check_index_7:
	cmpi.w #7,gConversationMatchedGoodsIndex.l
	bne.b .check_index_8
	lea.l sConvTradeRefuseCargoTypes7And14(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w FinishConversationGoodsRefusal
.check_index_8:
	cmpi.w #8,gConversationMatchedGoodsIndex.l
	bne.b .check_index_11
	lea.l sConvTradeRefuseCargoType8(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w FinishConversationGoodsRefusal
.check_index_11:
	cmpi.w #11,gConversationMatchedGoodsIndex.l
	bne.b .check_index_13
	lea.l sConvTradeRefuseCargoType11(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w FinishConversationGoodsRefusal
.check_index_13:
	cmpi.w #13,gConversationMatchedGoodsIndex.l
	bne.b .check_index_14
	lea.l sConvTradeRefuseCargoType13(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w FinishConversationGoodsRefusal
.check_index_14:
	cmpi.w #14,gConversationMatchedGoodsIndex.l
	bne.b .check_index_15
	lea.l sConvTradeRefuseCargoTypes7And14(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w FinishConversationGoodsRefusal
.check_index_15:
	cmpi.w #15,gConversationMatchedGoodsIndex.l
	bne.b ConfirmConversationSaleGoods
	lea.l sConvTradeRefuseCargoType15(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w FinishConversationGoodsRefusal
FinishConversationGoodsRefusal:
	st.b conversationFlags_peer_signed_off.l
	jsr ConversationRandomWordPreservingD1.l
	andi.w #1,d0
	bne.w GalNetConversationLoop
	lea.l sConvTradeDubiousCargoSignoff(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
ConfirmConversationSaleGoods:
	lea.l sConvTradeCargoAcknowledgement(pc),a0
	bsr.w ExpandConversationReplyScript
	lea.l conversationReplyBuffer(pc),a0
	bsr.w DrawWrappedText
	lea.l conversationGoodsDisplayNames(pc),a0
	move.w gConversationMatchedGoodsIndex(pc),d0
    ; Index the existing 16-name goods catalog with the matched index, then append its plain BYTE string. This helper skips NUL strings; it does not validate the catalog length.
	bsr.w IndexConversationStringCatalog
	jsr AppendWrappedTextAtCursor.l
	moveq.l #32,d0
	jsr DrawCharacter.l
	lea.l sConvTradeCargoQuerySuffix(pc),a0
	bsr.w ExpandConversationReplyScript
	lea.l conversationReplyBuffer.l,a0
	bsr.w AppendWrappedTextAtCursor
	bsr.w AdvanceTerminalTextLine
	bsr.w ReadConversationInput
	lea.l sConvTradeYesPattern(pc),a0
	bsr.w MatchConversationPattern
	beq.b AskConversationSalePrice
	lea.l sConvTradeAskSpecificCargo(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w ReadConversationSaleGoods
AskConversationSalePrice:
	lea.l sConvTradeAskSellingPrice(pc),a0
	bsr.w ExpandAndDisplayConversationReply
    ; Test the found WORD after ReadConversationInput without testing its D0 return. An empty input returns before numeric extraction, so the flag alone does not prove a fresh value for this line.
ReadConversationSalePrice:
	bsr.w ReadConversationInput
	tst.w flagConversationNumberFound.l
	bne.b InitializeConversationBuyerOffer
	lea.l sConvTradeRepeatPriceQuestion(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.b ReadConversationSalePrice
    ; Four LONG slots for the goods-sale negotiation. The displayed buyer offer is distinct from the shared slot read by the actual credit update.
gConversationInitialSaleAsk:
	dc.l $00000000
gConversationCurrentSaleAsk:
	dc.l $00000000
gConversationPreviousSaleAsk:
	dc.l $00000000
gConversationBuyerOffer:
	dc.l $00000000
    ; Initial/current sale asks copy the parsed LONG. Buyer offer instead starts at matched base shifted right once: 50..2500 after the normal eligible-index checks.
InitializeConversationBuyerOffer:
	move.l gConversationParsedNumber(pc),d0
	move.l d0,gConversationInitialSaleAsk.l
	move.l d0,gConversationCurrentSaleAsk.l
	move.l gConversationMatchedBaseAmount(pc),d0
	lsr.l #1,d0
	move.l d0,gConversationBuyerOffer.l
    ; These LONG signed exit tests gate this buyer-offer display only. The later acceptance/repeat path has its own display call; no global signed-WORD bound is established for the evolving offer.
EvaluateConversationBuyerOffer:
	move.l gConversationInitialSaleAsk.l,d1
	lsr.l #4,d1
	move.l gConversationCurrentSaleAsk(pc),d0
	sub.l gConversationBuyerOffer(pc),d0
	cmp.l d1,d0
	blt.w CompleteConversationCargoSale
	move.l gConversationCurrentSaleAsk(pc),d0
	sub.l gConversationMatchedBaseAmount(pc),d0
	addi.l #9,d0
	bmi.w CompleteConversationCargoSale
	lea.l sConvTradeBuyingOfferPrefix(pc),a0
	bsr.w ExpandConversationReplyScript
	lea.l conversationReplyBuffer(pc),a0
	bsr.w DrawWrappedText
    ; Load the evolving buyer-offer LONG for WORD display. Its initializer fits, but the two subsequent LONG update paths need separate range reasoning; no concrete truncation is proved here.
	move.l gConversationBuyerOffer(pc),d0
	bsr.w DrawConversationWordAmount
	lea.l sConvTradeCredSuffix(pc),a0
	jsr AppendWrappedTextAtCursor.l
	bsr.w AdvanceTerminalTextLine
    ; This sale reader also tests the found WORD without checking the input return first. Preserve the existing empty-input and flag order; current-line freshness is not established by this test.
ReadConversationRevisedSalePrice:
	bsr.w ReadConversationInput
	tst.w flagConversationNumberFound.l
	beq.w CheckConversationSaleAcceptance
	move.l gConversationParsedNumber(pc),d0
	move.l gConversationCurrentSaleAsk(pc),gConversationPreviousSaleAsk.l
	cmp.l gConversationCurrentSaleAsk(pc),d0
	beq.w CheckConversationSaleAcceptance
    ; Store the revised ask before calculating or comparing the limit. The above-limit reply loops without restoring this field; preserve that original state-update order.
	move.l d0,gConversationCurrentSaleAsk.l
    ; The normal eligible base is 100..5000. MULU.W by 5 then LSR.L by 2 produces a transient limit 125..6250, independent of the parsed ask being compared.
	move.l gConversationMatchedBaseAmount(pc),d1
	mulu.w #$5,d1
	lsr.l #2,d1
	cmp.l d1,d0
	ble.b ChooseConversationBuyerOfferUpdate
	move.l d1,-(a7)
	lea.l sConvTradeBuyingLimitPrefix(pc),a0
	bsr.w ExpandConversationReplyScript
	lea.l conversationReplyBuffer(pc),a0
	bsr.w DrawWrappedText
    ; Reload the saved computed limit for display, not the parsed number. This traced limit fits signed WORD; the current ask remains a separate LONG field.
	move.l (a7)+,d0
	bsr.w DrawConversationWordAmount
	lea.l sConvTradeCredSuffix(pc),a0
	jsr AppendWrappedTextAtCursor.l
	bsr.w AdvanceTerminalTextLine
	bra.b ReadConversationRevisedSalePrice
    ; Choose between two original LONG updates. A zero masked low WORD applies previous ask minus current ask; the other path increments the buyer offer by exactly 8, not a random percentage.
ChooseConversationBuyerOfferUpdate:
	jsr ConversationRandomWordPreservingD1.l
	andi.w #1,d0
	beq.b ApplyConversationSaleAskDeltaToOffer
	move.l gConversationCurrentSaleAsk(pc),d1
	sub.l gConversationBuyerOffer(pc),d1
	lsr.l #2,d1
	bmi.b CompleteConversationCargoSale
    ; Here the masked low WORD of D0 is 1. Unsigned WORD multiplication cannot set a high product WORD; CLR.W/SWAP leaves zero, then ADDQ 8 supplies the exact increment.
	mulu.w d1,d0
	clr.w d0
	swap.w d0
	addq.l #8,d0
	add.l d0,gConversationBuyerOffer.l
	bra.w EvaluateConversationBuyerOffer
    ; Add previous ask minus current ask to buyer offer using LONG arithmetic. No comparison here requires a reduction; an increased ask reverses the delta. Keep modulo 32-bit behavior.
ApplyConversationSaleAskDeltaToOffer:
	move.l gConversationPreviousSaleAsk(pc),d0
	sub.l gConversationCurrentSaleAsk(pc),d0
	add.l d0,gConversationBuyerOffer.l
	bra.w EvaluateConversationBuyerOffer
CheckConversationSaleAcceptance:
	lea.l sConvTradeYesPattern(pc),a0
	bsr.w MatchConversationPattern
	beq.b CompleteConversationCargoSale
	lea.l sConvTradeCurrentOfferPrefix(pc),a0
	bsr.w ExpandConversationReplyScript
	lea.l conversationReplyBuffer(pc),a0
	bsr.w DrawWrappedText
    ; This second WORD display call follows the acceptance/repeat logic, not the two EvaluateConversationBuyerOffer exit tests. It still reads buyer offer, not the settlement slot.
	move.l gConversationBuyerOffer(pc),d0
	bsr.w DrawConversationWordAmount
	lea.l sConvTradeCredSuffix(pc),a0
	jsr AppendWrappedTextAtCursor.l
	bsr.w AdvanceTerminalTextLine
	bra.w ReadConversationRevisedSalePrice
    ; A nonzero selected quantity loses 10. Credits gain the shared offer slot, not the displayed buyer offer; free units gain 10. No assignment between those offer slots is established here.
CompleteConversationCargoSale:
	lea.l cargoQuantityStorage.l,a0
	lea.l $0032(a0),a0
	move.w gConversationMatchedGoodsIndex(pc),d0
	add.w d0,d0
	adda.w d0,a0
	tst.w (a0)
	beq.w RejectConversationMissingGoods
	subi.w #10,(a0)
	lea.l tradeAccountBase.l,a0
    ; Settlement adds the distinct shared-offer LONG to credits. Its direct operand differs from the displayed buyer-offer field, independently of formatter width. Alias closure is not proved.
	move.l gConversationSharedOfferAmount(pc),d0
	add.l d0,$0034(a0)
	addi.w #10,$0032(a0)
	lea.l sConvTradeSaleAccepted(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
RejectConversationMissingGoods:
	lea.l sConvTradeMissingGoods(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
