    ; Matcher entry writes FFFF to the WORD index, then 0..15 on match. The following LONG receives the signed table entry without taking its absolute value. Initial stored bytes are unchanged.
gConversationMatchedGoodsIndex:
	dc.w $0000
gConversationMatchedBaseAmount:
	dc.l $00000000
    ; Tries 16 ordered packed patterns. A match stores its index and the raw signed table LONG. A miss leaves index FFFF and does not replace the previous amount.
MatchConversationGoodsCatalog:
	move.w #$FFFF,gConversationMatchedGoodsIndex.l
	lea.l conversationGoodsMatchPatterns(pc),a0
	moveq.l #0,d7
.try_pattern:
	move.w d7,-(a7)
	move.l a0,-(a7)
	bsr.w MatchConversationPattern
	movea.l (a7)+,a0
	move.w (a7)+,d7
	tst.w d0
	beq.b .matched
.skip_pattern:
	tst.b (a0)+
	bne.b .skip_pattern
	addq.w #1,d7
	cmp.w #$10,d7
	bne.b .try_pattern
	moveq.l #-1,d0
	rts
.matched:
	move.w d7,gConversationMatchedGoodsIndex.l
	add.w d7,d7
	add.w d7,d7
	lea.l conversationOfferBaseAmounts(pc),a0
	move.l $0(a0,d7.w),gConversationMatchedBaseAmount.l
	moveq.l #0,d0
	rts
    ; 16 consecutive NUL pattern strings are matched in order. The selected index addresses the amount table and the separately stored display-name catalog.
conversationGoodsMatchPatterns:
	dc.b $2A
	dc.b " towels *",$00
	dc.b "* lingerie *",$00
	dc.b "* hypermint *",$00
	dc.b "* janx spirit *",$00
	dc.b "* (megagin/mega gin) *",$00
	dc.b "* marsh gas *",$00
	dc.b "* suntiger teeth *",$00
	dc.b "* jackets *",$00
	dc.b "* (chronographs/watches) *",$00
	dc.b "* playbeing *",$00
	dc.b "* the book *",$00
	dc.b "* starport blasters *",$00
	dc.b "* sensomatics *",$00
	dc.b "* robots *",$00
	dc.b "* simple * manuals *",$00
	dc.b "* (missiles/spears) *",$00
    ; 16 NUL display names indexed by the matched goods index. The trailing extra NUL remains outside this catalog; do not merge differing offered-goods text by similarity.
conversationGoodsDisplayNames:
	dc.b "bath towels",$00
	dc.b "exotic space lingerie, wonder which species it fits!",$00
	dc.b "Qualactin hypermint extract",$00
	dc.b "Old Janx Spirit",$00
	dc.b "Arcturan Mega-gin",$00
	dc.b "Fallian marsh gas",$00
	dc.b "Algolian suntiger teeth",$00
	dc.b "black plastic bags",$00
	dc.b "digital watches",$00
	dc.b "copies of Playbeing",$00
	dc.b "copies of THE book",$00
	dc.b "starport blasters, banned under strategic arms limitations",$00
	dc.b "sub-etha sens-o-matics",$00
	dc.b "Serious Cybernetics GPP robots",$00
	dc.b "SIMPLE programing manuals (which everybody has)",$00
	dc.b "plastic spears",$00
	dc.b $00
    ; Try the goods-sale list first, then the purchase list. A match branches into that route without returning here; only two misses return to GenerateConversationReply.
DispatchConversationTradeIntent:
	lea.l conversationIntentToGoodsSalePatterns(pc),a0
	bsr.w MatchConversationPatternList
    ; Tail-branch with the classifier caller frame still pending. The trading paths eventually rejoin the loop that restores its saved A7; do not assume an ordinary classifier return on a match.
	beq.w RouteToConversationGoodsSale
	lea.l conversationIntentToPurchasePatterns(pc),a0
	bsr.w MatchConversationPatternList
	beq.w RouteToConversationPurchaseIntent
	rts
conversationIntentToGoodsSalePatterns:
	dc.b "* want to buy *",$00
	dc.b "ive got some * (for sale/to sell)",$00
	dc.b "* want some *",$00
	dc.b $FF
conversationIntentToPurchasePatterns:
	dc.b "* I (selling/trading) *",$00
	dc.b "* got anything * (sell/sale/trade)",$00
	dc.b "* I (sell/trade) *",$00
	dc.b $FF
    ; A0 addresses packed NUL patterns followed by a negative BYTE marker. Save/restore A0 around each matcher call. Only the two known three-pattern lists are bounded here.
MatchConversationPatternList:
	move.l a0,-(a7)
	bsr.w MatchConversationPattern
    ; The restored A0 is the candidate pattern start. This pointer save does not roll back the matcher global input/capture cursors or establish general receiver preservation.
	movea.l (a7)+,a0
	tst.w d0
	beq.w .matched
.skip_pattern:
	tst.b (a0)+
	bne.b .skip_pattern
    ; After skipping the failed pattern NUL, test the next BYTE without advancing it. A negative marker ends the list; miss returns D0=-1 and match returns D0=0, with matching Z state.
	tst.b (a0)
	bpl.b MatchConversationPatternList
	moveq.l #-1,d0
	rts
.matched:
	moveq.l #0,d0
	rts
    ; Display the original Claret request script, then branch to the shared special-goods reply loop. Its advertised price is message text, not a verified transfer calculation.
RequestConversationAlgolianClaret:
	lea.l sConvRequestAlgolianClaret(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w BeginConversationSpecialGoodsReplies
sConvRequestAlgolianClaret:
	dc.b "%r2(Have you got any bottles of Algolian Claret, I'll pay 1,000,000 creds for some/I'm really after Algolian Claret, I'll pay anything for some, do you happen to have a bottle)",$00
	dc.b $00
    ; Display the original cigar request script and use the same shared reply-loop entry. No completed goods or credit transfer is established by these wrappers.
RequestConversationAlgolianCigars:
	lea.l sConvRequestAlgolianCigars(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w BeginConversationSpecialGoodsReplies
sConvRequestAlgolianCigars:
	dc.b "%r2(Have you got any Algolian Cigars, I'll pay 10,000 creds for one/Do you know where I can get some Algolian Cigars, I'll do anything for one)",$00
    ; One WORD counts replies matching neither shared NO nor YES pattern. The two request wrappers clear it on entry; the internal YES read does not reset it. No global writer closure is claimed.
gSpecialGoodsUnmatchedReplyCount:
	dc.w $0000
    ; Both request wrappers reach this reset after their intro script. Clear the WORD, then fall into the reader; do not reset again on its retry or recursive YES edge.
BeginConversationSpecialGoodsReplies:
	clr.w gSpecialGoodsUnmatchedReplyCount.l
    ; Read input, then test NO before YES without checking the input D0 return. An empty input leaves the prior token stream, so these matches alone do not establish a fresh response.
ConversationSpecialGoodsReplyLoop:
	bsr.w ReadConversationInput
	lea.l sConvTradeNoPattern(pc),a0
	bsr.w MatchConversationPattern
	bne.b .try_yes
    ; A matched NO displays the unavailable script and branches to the saved-stack conversation loop. No inventory or credit transfer is performed in this recognized body.
	lea.l sConvSpecialGoodsUnavailable(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
.try_yes:
	lea.l sConvTradeYesPattern(pc),a0
	bsr.w MatchConversationPattern
	bne.b .unmatched_reply
    ; Load the sample-request script, then BSR back into this reader. This edge has no expander call for that pointer: ordinary input returns A0, then the NO-pattern LEA replaces it.
	lea.l sConvSpecialGoodsSampleRequest(pc),a0
    ; Keep the original internal BSR, not a tail branch. Its return address remains pending on this edge; the recognized reader has no local RTS. No recursion-depth or runtime test is implied.
	bsr.b ConversationSpecialGoodsReplyLoop
    ; The original continuation branches to the conversation loop if the internal BSR returns. No ordinary local return to it is established; retain the instruction unchanged.
	bra.w GalNetConversationLoop
    ; Failure of both pattern tests increments this WORD. On the reset chain, first unmatched reply gives 1 and prompts again; equality with 2 selects the end script. Keep equality, not a clamp.
.unmatched_reply:
	addq.w #1,gSpecialGoodsUnmatchedReplyCount.l
	cmpi.w #2,gSpecialGoodsUnmatchedReplyCount.l
	beq.b .finish_after_unmatched
	lea.l sConvSpecialGoodsAskDefiniteAnswer(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.b ConversationSpecialGoodsReplyLoop
    ; The selected end script begins with outer +!, targeting the peer-signed-off BYTE. It is then displayed and the loop is rejoined; this is not a goods/credit settlement.
.finish_after_unmatched:
	lea.l sConvSpecialGoodsEndConversation(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
sConvSpecialGoodsUnavailable:
	dc.b "%r5(Pity, I haven't had any for ages./Can't get any for love nor money/In the old days, you could get some at any old spaceport/Ahh, you just can't get hold of any these days/Haven't had any for 6 months, I'll keep looking though.)",$00
    ; Encoded sample-request text has one recognized direct load on the YES edge. That edge does not pass it to an expander before replacing A0. Other aliases and global reachability remain open.
sConvSpecialGoodsSampleRequest:
	dc.b "%r5(Really! beam me one over, I've got the money waiting/Beam one over, if it's the real thing I'll buy every one you've got./Chuck one over here, let's see if it's real./Beam one up scottie, let's see if it's any good, I get all sorts of rubbish you know./A million creds if it's real, send one over here so I can taste it.)",$00
sConvSpecialGoodsAskDefiniteAnswer:
	dc.b "%r4(Don't mess about with the salt of life sonny, have you or not?/Don't take this so lightly, have you got the stuff of not./Either you have or you have not, which is it to be, I'm very serious about my pleasures/You had better take life more seriously if you want to get anywhere. Yes or no?)",$00
sConvSpecialGoodsEndConversation:
	dc.b "+!%r3(Don't mess where Algolian goods are concerned sonny/Try taking life seriously boy, don't mess with Algolian pleasures/I'm wasting my time with you, whats the matter, never had any youself)",$00
    ; Display the small-talk script and resume the conversation loop. Some original script alternatives carry +!; this source wrapper does not guarantee every choice signs off.
DisplayConversationSmallTalkReply:
	lea.l sConvSmallTalkFallbackReply(pc),a0
	bsr.w ExpandAndDisplayConversationReply
	bra.w GalNetConversationLoop
sConvSmallTalkFallbackReply:
	dc.b "%r6(+!I've got better things to do than banter all day, I heard there were pirates in this area/Enough banter, have you any business./+!You should be careful around here, I could be a pirate you know./Say what you mean, or get off the etha./I don't care, have you got anything meaningful to tell me./Enough smalltalk, what do you want from me.)",$00
	dc.b $00	; opaque_data
    ; Conversation entry saves A7 here; the loop restores it on re-entry and both finish paths restore it before returning.
pGalNetConversationLoopStack:
	dc.l $00000000
    ; Matcher cursor into conversationTokenBuffer. Literal/wildcard handlers advance it; the alternative retry path restores its saved value.
pConversationInputCursor:
	dc.l $00000000
    ; Current pattern cursor. The subpattern helper saves/restores this slot while handlers consume syntax through it.
pConversationPatternCursor:
	dc.l $00000000
    ; MatchConversationPattern stores entry A0 here. No read consumer is established by this pass.
pConversationInitialPattern:
	dc.l $00000000
    ; 64 allocated bytes for one alternative copied from (...) through slash or closing parenthesis, then NUL. No complete write bound is proved.
conversationAlternativeScratch:
	dcb.b $40,$00
    ; 128 allocated bytes of mixed capture records ending in FF. Wildcards append plain text; alternatives prefix their text with an ordinal byte. No complete write bound is proved.
conversationCaptureBuffer:
	dcb.b $80,$00
    ; Append cursor initialized to conversationCaptureBuffer. Both capture producers update it; the wrapper writes FF at its final position.
pConversationCaptureWrite:
	dc.l $00000000
    ; Input cursor saved when * begins. The active *= producer copies through the current input cursor, replacing token NUL separators with spaces.
pConversationWildcardStart:
	dc.l $00000000
tableConvHandler:
	bra.w FinishConversationPatternScan
abs_0_0003DC82:
	bra.w MatchConversationLiteralToken
abs_0_0003DC86:
	bra.w BeginConversationWildcard
abs_0_0003DC8A:
	bra.w MatchConversationAlternatives
abs_0_0003DC8E:
	move.w d0,$00000001.l
    ; Initializes input and capture cursors, calls the subpattern matcher and appends FF. D0=0 denotes a match. Capture records are normal interpreted data, not code targets.
MatchConversationPattern:
	clr.b flagConvAsterisk.l
	clr.b flagConvAsteriskEquals.l
	lea.l conversationTokenBuffer(pc),a1
	move.l a1,pConversationInputCursor.l
	lea.l conversationCaptureBuffer(pc),a1
	move.l a1,pConversationCaptureWrite.l
	move.l a0,pConversationInitialPattern.l
	bsr.b MatchConversationSubpattern
	movea.l pConversationCaptureWrite.l,a0
	move.b #$FF,(a0)+
	tst.w d0
	rts
    ; Saves/restores pattern cursor and wildcard state. Input/capture cursors carry matching progress; alternative retries restore their saved cursor pair explicitly.
MatchConversationSubpattern:
	move.l pConversationPatternCursor(pc),-(a7)
	move.w flagConvHandlingEnd(pc),-(a7)
	move.w flagConvAsterisk(pc),-(a7)
	move.w flagConvAsteriskEquals(pc),-(a7)
	move.l pConversationWildcardStart(pc),-(a7)
	move.l a0,pConversationPatternCursor.l
	clr.b flagConvHandlingEnd.l
.process_to_end:
	bsr.w ConvCalcTableOption
	lea.l tableConvHandler(pc),a0
    ; ConvCalcTableOption returns byte offsets 0,4,8,12. This calls the four original BRA.W stubs at tableConvHandler; native discovery records all four.
	jsr $0(a0,d0.w)
	bne.b .exit_false
	tst.b flagConvHandlingEnd.l
	beq.b .process_to_end
	bsr.w AppendConversationWildcardCapture
	tst.b flagConvCopyEnd.l
	bne.b .check_open_bracket
	movea.l pConversationInputCursor(pc),a0
	tst.b (a0)
	bmi.b .exit_true
.check_open_bracket:
	tst.b flagConvHandlingOpenBracket.l
	bne.b .exit_true
	tst.b flagConvAsterisk.l
	beq.b .exit_false
.exit_true:
	moveq.l #0,d0
.exit:
	move.l (a7)+,pConversationWildcardStart.l
	move.w (a7)+,flagConvAsteriskEquals.l
	move.w (a7)+,flagConvAsterisk.l
	move.w (a7)+,flagConvHandlingEnd.l
	move.l (a7)+,pConversationPatternCursor.l
	tst.w d0
	rts
.exit_false:
	moveq.l #-1,d0
	bra.b .exit
flagConvCopyEnd:
	dc.w $0000
ConvCalcTableOption:
	movea.l pConversationPatternCursor(pc),a0
	tst.b (a0)
	bne.b .match_asterisk
	moveq.l #0,d0
	rts
.match_asterisk:
	bsr.w SkipLeadingSpacesA0
	move.b (a0)+,d0
	cmp.b #$2A,d0
	bne.b .match_open_bracket
	move.l a0,pConversationPatternCursor.l
	moveq.l #8,d0
	rts
.match_open_bracket:
	cmp.b #$28,d0
	bne.b .skip3
	move.l a0,pConversationPatternCursor.l
	moveq.l #12,d0
	rts
.skip3:
	lea.l conversationLiteralScratch(pc),a1
	move.b d0,(a1)+
.copy_char1:
	move.b (a0)+,d0
	bmi.b abs_0_0003DD96
	beq.b abs_0_0003DD96
	cmp.b #$20,d0
	beq.b .end_of_copy
	move.b d0,(a1)+
	bra.b .copy_char1
abs_0_0003DD96:
	subq.w #1,a0
ConvCalcTableOption\.end_of_copy:
	clr.b (a1)+
	move.l a0,pConversationPatternCursor.l
	st.b flagConvCopyEnd.l
	moveq.l #4,d0
	rts
SkipLeadingSpacesA0:
	cmpi.b #32,(a0)
	beq.b .loop
	rts
.loop:
	addq.w #1,a0
	bra.b SkipLeadingSpacesA0
    ; 24 allocated bytes for the literal pattern token, copied until space, NUL or negative marker. This allocation does not prove every producer write is bounded.
conversationLiteralScratch:
	dcb.b $18,$00	; opaque_data
    ; Compares the literal scratch token with the current input token. Active wildcard search can advance through later tokens; a match updates the input cursor.
MatchConversationLiteralToken:
	lea.l conversationLiteralScratch.l,a0
	movea.l pConversationInputCursor(pc),a1
abs_0_0003DDD8:
	bsr.w CompareConversationInputToken
	bne.b abs_0_0003DE0A
	move.l a1,pConversationInputCursor.l
	bsr.w AppendConversationWildcardCapture
	movea.l pConversationInputCursor(pc),a1
abs_0_0003DDEC:
	tst.b (a1)+
	beq.b abs_0_0003DDF4
	bpl.b abs_0_0003DDEC
	subq.w #1,a1
abs_0_0003DDF4:
	move.l a1,pConversationInputCursor.l
