	dc.b "you (like/enjoy/love/dig) *=",$00
	dc.b "Some say that %2 is %r3(sinful/wicked/overrated)",$00
sConvPatternSorry:
	dc.b "sorry *",$00
	dc.b "%r3(Thats ok/Why do you apologise/Thats quite alright)",$00
sConvPatternIdentityQuestion:
	dc.b "who are I",$00
	dc.b "My name is not important, you have my number.",$00
sConvPatternLikeYou:
	dc.b "you (like/love) I",$00
	dc.b "Lets keep this neutral shall we?",$00
sConvPatternHateYouOrAliens:
	dc.b "you (hate/detest/dont like) (I/aliens) *",$00
	dc.b "+!%r3(Right then, I'll go!/I'm not too keen on you!/Suits me fine!)",$00
sConvPatternBigQuestion:
	dc.b "(do I have/have I got) big *",$00
	dc.b "%r3(Yes!/massive!/huge!) {fnarr fnarr}",$00
sConvPatternNumberQuestion:
	dc.b "(whats/what is/tell you) your number *",$00
	dc.b "You already have it!",$00
    ; This farewell rule sets flag g ($67), not peer-signed-off ! ($21). The loop directly tests ! and @; no disconnect or global read closure follows from this literal farewell alone.
sConvPatternFarewell:
	dc.b "(goodbye/cheerio/bye/farewell/see I)",$00
	dc.b "+g%r5(goodbye/cheerio/bye/farewell/see you)",$00
sConvPatternPrivateRelations:
