	move.w #INTF_DSKBLK,intreq(a6)
	move.l #MFMBuffer,dskpt(a6)	; disk_buffer pointer
    ; ADKCON[CLR PRECOMP1+PRECOMP0+MFMPREC+UARTBRK+WORDSYNC+MSBSYNC+FAST]
	move.w #ADKF_PRE560NS|ADKF_MFMPREC|ADKF_UARTBRK|ADKF_WORDSYNC|ADKF_MSBSYNC|ADKF_FAST,adkcon(a6)
	move.w #$9900,d0
	move.w d0,adkcon(a6)
    ; Disk DMA off.
	move.w #$4000,dsklen(a6)
    ; Disk DMA on to write  0x17BC
	move.w #$D7BC,dsklen(a6)	; disk DMA write 12152 bytes
	move.w #$D7BC,dsklen(a6)	; disk DMA write 12152 bytes
	jsr WaitForSoftwareInterrupt(pc)
    ; Disk DMA off.
	move.w #$4000,dsklen(a6)
	move (a7)+,sr
	moveq.l #-1,d0
	rts
.exit_write_protected:
	st.b diskReadFailedFlag.l
	moveq.l #0,d0
	rts
DiskWrite_1B58:
	lea.l _custom.l,a6
	move.w #DMAF_SPRITE,dmacon(a6)
	lea.l _ciaa.l,a5
    ; DSKPROT (0 = protected)
	btst.b #3,(a5)
	beq.b .exit_write_protected
	move sr,-(a7)
	ori #1792,sr
	jsr WaitForCIABFlag(pc)
    ; INTREQ[CLR DSKBLK]
	move.w #INTF_DSKBLK,intreq(a6)
	move.l #MFMBuffer,dskpt(a6)	; disk_buffer pointer
    ; ADKCON[CLR PRECOMP1+PRECOMP0+MFMPREC+UARTBRK+WORDSYNC+MSBSYNC+FAST]
	move.w #ADKF_PRE560NS|ADKF_MFMPREC|ADKF_UARTBRK|ADKF_WORDSYNC|ADKF_MSBSYNC|ADKF_FAST,adkcon(a6)
    ; ADKCON[CLR ALL]
	move.w #ADKF_CLRALL,adkcon(a6)
    ; ADKCON[SET MFMPREC+UARTBRK+FAST]
	move.w #$9900,d0
	move.w d0,adkcon(a6)
    ; Disk DMA off.
	move.w #$4000,dsklen(a6)
    ; Disk DMA on to write 0x1B58
	move.w #$DB58,dsklen(a6)	; disk DMA write 14000 bytes
    ; Disk DMA on to write 0x1B58 (confirm)
	move.w #$DB58,dsklen(a6)	; disk DMA write 14000 bytes
	jsr WaitForSoftwareInterrupt(pc)
    ; Disk DMA off.
	move.w #$4000,dsklen(a6)
	move (a7)+,sr
	moveq.l #-1,d0
	rts
.exit_write_protected:
	st.b diskReadFailedFlag.l
	moveq.l #0,d0
	rts
WaitForSoftwareInterrupt:
	lea.l _custom.l,a6
.loop:
	move.w intreqr(a6),d0	; interrupt request state
    ; Read SOFT interrupt flag
	andi.w #2,d0
	beq.b .loop
    ; Set SOFT interrupt flag again if found.
	move.w #INTF_DSKBLK,intreq(a6)
	rts
MoveDiskToTrack:
	move.w d0,d1
	lea.l _ciaa.l,a5
	lea.l _ciab.l,a4
    ; DSKSIDE (0 = upper head)
	bclr.b #CIAB_DSKSIDE,ciaprb(a4)
	btst #0,d1
	beq.b .select_direction
    ; DSKSIDE (1 = lower head)
	bset.b #CIAB_DSKSIDE,ciaprb(a4)
    ; 80 cylinders per disk, 2 tracks per cylinder
.select_direction:
	cmpi.w #160,d1
	bge.b .step_exit
	move.w d1,d2
	move.w gCurrentDiskTrack(pc),d0
    ; Two tracks per cylinder
	lsr.w #1,d0
	lsr.w #1,d1
    ; Which cylinder
	sub.w d0,d1
	beq.b .step_done
	bmi.b .step_tracks_back
    ; DSKDIREC (0 = inward from track zero)
	bclr.b #CIAB_DSKDIREC,ciaprb(a4)
	bra.b .step_tracks
    ; DSKDIREC (1 = outward to track zero)
.step_tracks_back:
	bset.b #CIAB_DSKDIREC,ciaprb(a4)
	neg.w d1
.step_tracks:
	subq.w #1,d1
    ; DSKSTEP (high, low, high)
.next_track:
	bset.b #CIAB_DSKSTEP,ciaprb(a4)
	bclr.b #CIAB_DSKSTEP,ciaprb(a4)
	nop
	nop
	nop
	nop
	bset.b #CIAB_DSKSTEP,ciaprb(a4)
	move.w #$FA0,d0
.step_delay:
	dbf.w d0,.step_delay
	dbf.w d1,.next_track
.step_done:
	lea.l gCurrentDiskTrack(pc),a4
	move.w d2,(a4)
.step_exit:
	rts
StepDiskNextTrack:
	lea.l _ciab.l,a4
    ; DSKDIREC (0 = inward from track zero)
	bclr.b #CIAB_DSKDIREC,ciaprb(a4)
	move.w gCurrentDiskTrack(pc),d0
	addq.w #1,d0
	cmpi.w #160,d0
	beq.b .exit
	lea.l gCurrentDiskTrack(pc),a0
	move.w d0,(a0)
    ; DSKSIDE (0 = upper head)
	bclr.b #CIAB_DSKSIDE,ciaprb(a4)
	lsr.w #1,d0
	bcc.b .next_track
    ; DSKSIDE (1 = lower head)
	bset.b #CIAB_DSKSIDE,ciaprb(a4)
	bra.b .exit
    ; DSKSTEP (high, low, high)
.next_track:
	bset.b #CIAB_DSKSTEP,ciaprb(a4)
	bclr.b #CIAB_DSKSTEP,ciaprb(a4)
	nop
	nop
	nop
	nop
	bset.b #CIAB_DSKSTEP,ciaprb(a4)
	move.w #$1770,d0
.exit_wait:
	dbf.w d0,.exit_wait
.exit:
	rts
StepDiskTrack0:
	lea.l _ciaa.l,a5
	lea.l _ciab.l,a4
    ; DSKDIREC (1 = outward toward track zero).
	bset.b #CIAB_DSKDIREC,ciaprb(a4)
    ; DSKCHANGE
.step_track:
	btst.b #4,(a5)
	beq.b .track_zero
    ; DSKSTEP (high, low, high)
	bset.b #CIAB_DSKSTEP,ciaprb(a4)
	bclr.b #CIAB_DSKSTEP,ciaprb(a4)
	nop
	nop
	nop
	nop
	bset.b #CIAB_DSKSTEP,ciaprb(a4)
	move.w #$FA0,d0
.step_delay:
	dbf.w d0,.step_delay
	bra.b .step_track
.track_zero:
	lea.l gCurrentDiskTrack(pc),a4
	clr.w (a4)
    ; BUG! A4 clobbered. DSKSIDE (0 = upper head)
	bclr.b #2,$0100(a4)
	rts
PulseSelectDisk0:
	lea.l _ciab.l,a4
    ; Inactive high DISKSEL0
	bset.b #CIAB_DSKSEL0,ciaprb(a4)
    ; Inactive high DISKMOTOR
	bset.b #CIAB_DSKMOTOR,ciaprb(a4)
	nop
	nop
	nop
    ; Active low DISKSEL0
	bclr.b #CIAB_DSKSEL0,ciaprb(a4)
	nop
	nop
	nop
	nop
	nop
    ; Inactive high DISKSEL0
	bset.b #CIAB_DSKSEL0,ciaprb(a4)
	rts
WaitDisk0Ready:
	lea.l _ciab.l,a4
    ; Deselect DISKSEL0
	bset.b #CIAB_DSKSEL0,ciaprb(a4)
    ; DISKMOTOR
	bclr.b #CIAB_DSKMOTOR,ciaprb(a4)
    ; Select DISKSEL0
	bclr.b #CIAB_DSKSEL0,ciaprb(a4)
