    ; The normal kind WORD selects a two-BYTE control record. This source table is not a closed live kind domain; the FF arm also depends on the inherited upper byte of D6.W.
GenerateScenerySelectorPage:
	lea.l sceneryPlacementControlRecords.l,a1
	add.w d0,d0
	adda.w d0,a1
	tst.w (a1)
	beq.w ClearScenerySelectorPage
	move.b (a1)+,d7
    ; MOVE.B replaces only D6 low byte. The FF pattern arm later scales D6.W without first clearing its inherited upper byte; a bounded BYTE key alone does not bound that WORD receiver.
	move.b (a1),d6
	cmp.b #$FF,d7
	beq.b abs_0_0004A0D4
	move.b d7,d5
	lsr.b #4,d5
	beq.b abs_0_0004A0C8
    ; The existing random helper preserves D5/D6/D7 and A0/A1 on normal return. Compare only low BYTEs here; this does not clear the later pattern index upper byte.
	jsr RandomWordMaybe.l
	andi.w #7,d0
	cmp.b d5,d0
	bgt.b ClearScenerySelectorPage
	andi.b #15,d7
    ; Save the page base across its 256-byte clear, then restore A0 before the single-cell write. The random gate that skips placement also clears the page through its original tail path.
abs_0_0004A0C8:
	lea.l (a0),a1
	bsr.w ClearScenerySelectorPage
	lea.l (a1),a0
	bra.w WriteScenerySelectorCell
    ; Restore the page base, then index patterns by signed low16(8*D6.W). Inherited upper bits may alter this source address; no unconditional pattern receiver is declared.
abs_0_0004A0D4:
	lea.l (a0),a1
	bsr.w ClearScenerySelectorPage
	lea.l (a1),a0
	lea.l sceneryPlacementPatternRecords(pc),a1
	add.w d6,d6
	add.w d6,d6
	add.w d6,d6
	adda.w d6,a1
	moveq.l #3,d0
    ; The nominal pattern contains four selector/position BYTE pairs. Each cell helper masks selector and position; the initial BYTE key alone does not certify that this source group was selected.
abs_0_0004A0EA:
	move.b (a1)+,d7
	move.b (a1)+,d6
	bsr.w WriteScenerySelectorCell
	dbf.w d0,abs_0_0004A0EA
	rts
    ; Write a selector WORD at 32*highNibble(position)+2*lowNibble(position). The masked write may span a 512-byte view; do not equate it with the separately cleared 256-byte page.
WriteScenerySelectorCell:
	andi.w #15,d7
	move.b d6,d5
	andi.w #15,d5
	add.w d5,d5
	andi.w #240,d6
	add.w d6,d6
	add.w d6,d5
	move.w d7,$0(a0,d5.w)
	rts
    ; Clear exactly 64 LONGs, 256 bytes, at caller A0. The four ordinary page roots are distinct; callers that need the original cursor save and restore it explicitly.
ClearScenerySelectorPage:
	moveq.l #63,d5
