	lea.l hartleyTransitionPalette.l,a0
	lea.l _custom+color.l,a1
.next_transition_color:
	move.w (a0),d0
	andi.w #15,d0
	subq.w #1,d0
	bpl.b .update_green
	moveq.l #0,d0
.update_green:
	move.w (a0),d1
	lsr.w #4,d1
	andi.w #15,d1
	subq.w #1,d1
	bpl.b .update_red
	moveq.l #0,d1
.update_red:
	lsl.w #4,d1
	or.w d1,d0
	move.w (a0),d1
	lsr.w #8,d1
	andi.w #15,d1
	addq.w #1,d1
	cmp.w #$F,d1
	ble.b .store_transition_color
	moveq.l #15,d1
.store_transition_color:
	lsl.w #8,d1
	or.w d1,d0
	move.w d0,(a0)+
	move.w d0,(a1)+
	dbf.w d6,.next_transition_color
	moveq.l #2,d6
.request_transition_wait:
	st.b gIrqWaitPending.l
.wait_transition_irq:
	tst.w gIrqWaitPending.l
	bne.b .wait_transition_irq
	dbf.w d6,.request_transition_wait
	dbf.w d7,.next_transition_step
	moveq.l #110,d7
.request_hold_wait:
	st.b gIrqWaitPending.l
.wait_hold_irq:
	tst.w gIrqWaitPending.l
	bne.b .wait_hold_irq
	dbf.w d7,.request_hold_wait
	moveq.l #14,d7
.next_restore_step:
