	andi.w #15,d0
	andi.w #15,d1
	addq.w #1,d1
	cmp.w d0,d1
	ble.b .restore_green
	move.w d0,d1
.restore_green:
	move.w (a1),d0
	move.w (a0),d2
	andi.w #240,d0
	andi.w #240,d2
	addi.w #16,d2
	cmp.w d0,d2
	ble.b .restore_red
	move.w d0,d2
.restore_red:
	or.w d2,d1
	move.w (a1),d0
	move.w (a0),d2
	andi.w #3840,d0
	andi.w #3840,d2
	subi.w #256,d2
	cmp.w d0,d2
	bge.b .store_restored_color
	move.w d0,d2
.store_restored_color:
	or.w d2,d1
	move.w d1,(a0)+
	move.w d1,(a2)+
	addq.w #2,a1
	dbf.w d6,.next_restore_color
