.wait_restore_irq1:
	tst.w gIrqWaitPending.l
	bne.b .wait_restore_irq1
	st.b gIrqWaitPending.l
.wait_restore_irq2:
	tst.w gIrqWaitPending.l
	bne.b .wait_restore_irq2
	st.b gIrqWaitPending.l
.wait_restore_irq3:
	tst.w gIrqWaitPending.l
	bne.b .wait_restore_irq3
	dbf.w d7,.next_restore_step
	rts
hartleyTransitionPalette:
	dcb.w $10,$0000
dataSprite67_2:	; ARRAY SpritePositionControlRecord[1]
	dc.w $0000,$0000
	dcb.b $C,$00
    ; Copy the same 16-color base palette, then perform 15 component-decrement steps with three IRQ waits each. This routine also serves the existing outer feedback path.
FadeOutHartleyPalette:
	st.b gIrqPaletteCycleSuppressed.l
    ; Fade-out selects that same zero-control source for slots 6/7. Reinstallation of the ordinary data depends on later producers, not a pointer save/restore here.
	move.l #dataSprite67_2,pSPR6PTH.l
	move.l #dataSprite67_2,pSPR7PTH.l
	moveq.l #15,d7
	lea.l hartleyBasePalette.l,a0
	lea.l hartleyTransitionPalette.l,a1
.copy_base_palette:
	move.w (a0)+,(a1)+
	dbf.w d7,.copy_base_palette
	moveq.l #14,d7
.next_fade_step:
	moveq.l #15,d6
	lea.l hartleyTransitionPalette.l,a0
	lea.l _custom+color.l,a1
.next_fade_color:
	move.w (a0),d0
	andi.w #15,d0
	subq.w #1,d0
	bpl.b .fade_green
	moveq.l #0,d0
.fade_green:
	move.w (a0),d1
	lsr.w #4,d1
	andi.w #15,d1
	subq.w #1,d1
	bpl.b .fade_red
	moveq.l #0,d1
.fade_red:
	lsl.w #4,d1
	or.w d1,d0
	move.w (a0),d1
	lsr.w #8,d1
	andi.w #15,d1
	subq.w #1,d1
	bpl.b .store_faded_color
	moveq.l #0,d1
.store_faded_color:
	lsl.w #8,d1
	or.w d1,d0
	move.w d0,(a0)+
	move.w d0,(a1)+
	dbf.w d6,.next_fade_color
	moveq.l #2,d6
.request_fade_wait:
	st.b gIrqWaitPending.l
.wait_fade_irq:
	tst.w gIrqWaitPending.l
	bne.b .wait_fade_irq
	dbf.w d6,.request_fade_wait
	dbf.w d7,.next_fade_step
	rts
