BumpSounds80:
	lea.l dataSound1.l,a0
	lea.l dataSoundsEnd.l,a1
	move.w #$80,d0
	lea.l _custom.l,a6
abs_0_0004F32E:
	add.b d0,(a0)+
	cmpa.l a0,a1
	bne.b abs_0_0004F32E
	rts
tableAUD0:
	dc.w $0001	; dmacon_value
	dc.w $0080	; intena_value
    ; AUD0LCH
	dc.w $00A0	; offset_dff000
	dc.w $0000	; counter2
	dc.w $0000	; v4
	dc.w $0000	; counter1
	dc.l $00000000	; ptr
tableAUD2:
	dc.w $0004	; dmacon_value
	dc.w $0200	; intena_value
    ; AUD2LCH
	dc.w $00C0	; offset_dff000
	dc.w $0000	; counter2
	dc.w $0000	; v4
	dc.w $0000	; counter1
	dc.l $00000000	; ptr
    ; Called by BSR: save SR above the return PC, mask interrupts, write AUDx registers/channel state, then RTE consumes saved SR and caller PC. This is not a plain RTS or memory-pure callee.
UpdateAudioChannel:
	lea.l _custom.l,a6
	move sr,-(a7)
	ori #1792,sr
    ; INTENA
	move.w $0002(a1),intena(a6)
    ; DMACON
	move.w (a1),dmacon(a6)
    ; DFF000 offset
	move.w $0004(a1),d0
	lea.l $0(a6,d0.w),a2
    ; AUDxLCH/AUDxLCL
	move.l (a0),(a2)
    ; AUDxLEN
	move.w $0004(a0),$0004(a2)
    ; AUDxPER
	move.w $000A(a0),$0006(a2)
    ; Preserve old AUDxDAT
	move.w $0008(a0),$000A(a1)
    ; Set new AUDxVOL
	move.w $0006(a0),$0008(a2)
	move.w #$2,$0006(a1)
	rte
abs_0_0004F396:
	lea.l _custom.l,a6
	moveq.l #15,d0
    ; DMACON
	move.w d0,dmacon(a6)
    ; AUD0PER
	move.w d0,aud0+ac_per(a6)	; audio period
    ; AUD1PER
	move.w d0,aud1+ac_per(a6)	; audio period
    ; AUD2PER
	move.w d0,aud2+ac_per(a6)	; audio period
    ; AUD2PER
	move.w d0,aud3+ac_per(a6)	; audio period
	moveq.l #0,d0
    ; AUD0VOL
	move.w d0,aud0+ac_vol(a6)
    ; AUD1VOL
	move.w d0,aud1+ac_vol(a6)
    ; AUD2VOL
	move.w d0,aud2+ac_vol(a6)
    ; AUD3VOL
	move.w d0,aud3+ac_vol(a6)
	lea.l tableAUD0(pc),a0
	move.w d0,Audio1_counter2(a0)
	move.w d0,Audio1_counter2+Audio1_SIZEOF(a0)
	move.w #DMAF_SETCLR|DMAF_BLITHOG|DMAF_MASTER|DMAF_RASTER|DMAF_COPPER|DMAF_BLITTER|DMAF_SPRITE,dmacon(a6)
exit_4f3d6:
	rts
    ; Select the fixed AUD0/AUD2 software states. Their common updater writes phase/countdown WORDs and custom registers; it does not dereference the loaded +12 LONG.
UpdateSoundEffectChannels:
	lea.l _custom.l,a6
	lea.l tableAUD0(pc),a3
	bsr.w UpdateSoundEffectChannel
	lea.l tableAUD2(pc),a3
    ; A3 is one fixed channel state here. The +12 LONG is loaded into A2 but unused by the recognized phase helper. The custom offset is a signed WORD, not an arbitrary RAM pointer.
UpdateSoundEffectChannel:
	tst.w Audio1_counter2(a3)
	beq.b exit_4f3d6
	movea.l Audio1_ptr(a3),a2
	move.w Audio1_offset_dff000(a3),d0
	lea.l $0(a6,d0.w),a1
	bsr.w AdvanceSoundEffectChannelPhase
	tst.w Audio1_counter2(a3)
	bne.b exit_4f3d6
	clr.w $000A(a1)
	move.w (a3),dmacon(a6)	; operand 1: Audio1_dmacon_value at (a3)
	rts
    ; Advance the software phase/countdown at +6/+10 and poll or write custom registers. Normal source returns retain A3; no stored callback, count or backup preservation is implied globally.
AdvanceSoundEffectChannelPhase:
	tst.w Audio1_counter2(a3)
	bpl.b abs_0_0004F430
	move.w (a3),d0	; operand 1: Audio1_dmacon_value at (a3)
	and.w dmaconr(a6),d0
	bne.b exit_4f3d6
	subq.w #1,Audio1_counter1(a3)
	bne.b abs_0_0004F42A
	clr.w Audio1_counter2(a3)
	rts
abs_0_0004F42A:
	move.w #$2,Audio1_counter2(a3)
abs_0_0004F430:
	subq.w #1,Audio1_counter2(a3)
	beq.b abs_0_0004F442
	move.w (a3),d0	; operand 1: Audio1_dmacon_value at (a3)
	ori.w #32768,d0
	move.w d0,dmacon(a6)
	rts
abs_0_0004F442:
	not.w Audio1_counter2(a3)
	move.w Audio1_intena_value(a3),d0
	move.w d0,intreq(a6)
	ori.w #32768,d0
	move.w d0,intena(a6)
	rts
    ; This acknowledge body saves only D0.W on the stack and otherwise writes custom INTENA, INTREQ and DMACON. Its local frame is eight bytes on 68000; interrupted stack lifetime stays separate.
SoundEffectAudioInterruptAcknowledge:
