    ; A zero audio-update WORD returns immediately. Nonzero enters existing channel setup; a BEEP request alone is not evidence of installed samples or observed playback.
PlaySoundN:
	tst.w flagUpdateAudioChannels.l
	bne.b UpdateAudioChannels1
	rts
UpdateAudioChannels1:
	movem.l d0-d7/a0-a6,-(a7)
	move.l #SoundEffectAudioInterruptAcknowledge,m68k_vector_level_4_interrupt_autovector.w
	lea.l tableAudioChannelData1(pc),a0
	add.w d0,d0
	add.w d0,d0
    ; Two WORD doubles select a LONG from the already bounded 15-entry data table. Existing setup supplies that descriptor to AUD0 and AUD2 helpers; no broader index closure is added.
	movea.l $0(a0,d0.w),a0
	lea.l tableAUD0(pc),a1
	movem.l d0-d2/a0,-(a7)
	bsr.w UpdateAudioChannel
	movem.l (a7)+,d0-d2/a0
	lea.l tableAUD2(pc),a1
	bsr.w UpdateAudioChannel
	movem.l (a7)+,d0-d7/a0-a6
	rts
